// ─── Desktop NavBar ───────────────────────────────────────────────────────────
function DesktopNav({ filteredPages, activePage, goTo }) {
  const navRef = useRef(null);
  const [indicatorStyle, setIndicatorStyle] = useState({});

  const updateIndicator = () => {
    if (!navRef.current) return;
    const activeBtn = navRef.current.querySelector('.nav-btn.active');
    if (activeBtn) {
      const isTrash = activeBtn.classList.contains('nav-trash');
      setIndicatorStyle({
        transform: `translateX(${activeBtn.offsetLeft}px)`,
        width: activeBtn.offsetWidth,
        height: activeBtn.offsetHeight,
        background: isTrash ? 'var(--red-bg)' : 'var(--accent-bg)',
        opacity: 1
      });
    } else {
      setIndicatorStyle({ opacity: 0 });
    }
  };

  useEffect(() => {
    updateIndicator();
    window.addEventListener('resize', updateIndicator);
    return () => window.removeEventListener('resize', updateIndicator);
  }, [activePage, filteredPages]);

  return (
    <nav className="nav" ref={navRef}>
      <div className="nav-indicator" style={indicatorStyle} />
      {filteredPages.map(p => (
        <button
          key={p.id}
          className={`nav-btn ${activePage === p.id ? 'active' : ''}`}
          onClick={() => goTo(p.id)}
          data-page={p.id}
        >
          {p.icon}
          {p.label}
        </button>
      ))}
      <button
        className={`nav-btn nav-trash ${activePage === 'lixeira' ? 'active' : ''}`}
        onClick={() => goTo('lixeira')}
        data-page="lixeira"
      >
        {TRASH_PAGE.icon}
        Lixeira
      </button>
    </nav>
  );
}

// ─── Mobile Bottom Nav ────────────────────────────────────────────────────────
const MAX_VISIBLE = 4; // how many pages to show directly (last slot is "more")

function MobileNav({ filteredPages, activePage, goTo }) {
  const [drawerOpen, setDrawerOpen] = useState(false);

  // All pages plus lixeira (oculta qualquer item restrito por features)
  const allPages = [...filteredPages, TRASH_PAGE].filter(p => {
    if (p.id === 'admin' && !FEATURES.SAAS_ADMIN) return false;
    if (p.id === 'feedback' && !FEATURES.FEEDBACK) return false;
    if (p.id === 'demo' && !FEATURES.DEMO_MODE) return false;
    return true;
  });

  // Decide which pages go in bottom bar vs drawer
  const hasOverflow = allPages.length > MAX_VISIBLE;
  const visiblePages = hasOverflow ? allPages.slice(0, MAX_VISIBLE - 1) : allPages;
  const drawerPages  = hasOverflow ? allPages.slice(MAX_VISIBLE - 1) : [];

  // Check if active page is in the drawer
  const activeInDrawer = drawerPages.some(p => p.id === activePage);

  const handleNavigate = (id) => {
    goTo(id);
    setDrawerOpen(false);
  };

  return (
    <>
      {/* Bottom Nav Bar */}
      <nav className="mobile-nav">
        {visiblePages.map(p => {
          const isTrashed = p.id === 'lixeira';
          return (
            <button
              key={p.id}
              className={`mobile-nav-btn ${activePage === p.id ? 'active' : ''} ${isTrashed ? 'trash' : ''}`}
              onClick={() => handleNavigate(p.id)}
            >
              {p.icon}
              <span>{p.shortLabel || p.label}</span>
            </button>
          );
        })}

        {hasOverflow && (
          <button
            className={`mobile-nav-btn ${activeInDrawer || drawerOpen ? 'active' : ''}`}
            onClick={() => setDrawerOpen(o => !o)}
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <circle cx="5" cy="12" r="1.5" fill="currentColor" stroke="none"/>
              <circle cx="12" cy="12" r="1.5" fill="currentColor" stroke="none"/>
              <circle cx="19" cy="12" r="1.5" fill="currentColor" stroke="none"/>
            </svg>
            <span>Mais</span>
          </button>
        )}
      </nav>

      {/* Drawer Overlay */}
      {drawerOpen && (
        <div className="mobile-drawer-overlay" onClick={() => setDrawerOpen(false)}>
          <div className="mobile-drawer" onClick={e => e.stopPropagation()}>
            <div className="mobile-drawer-header">
              <span>Mais opções</span>
              <button className="mobile-drawer-close" onClick={() => setDrawerOpen(false)}>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                  <path d="M18 6 6 18M6 6l12 12"/>
                </svg>
              </button>
            </div>
            <div className="mobile-drawer-list">
              {drawerPages.map((p, idx) => {
                const isTrashed = p.id === 'lixeira';
                return (
                  <div key={p.id}>
                    {/* Visual separator before lixeira */}
                    {isTrashed && (
                      <div style={{ margin: '8px 16px', borderTop: '1px solid var(--border)', opacity: 0.6 }} />
                    )}
                    <button
                      className={`mobile-drawer-item ${activePage === p.id ? 'active' : ''} ${isTrashed ? 'trash' : ''}`}
                      onClick={() => handleNavigate(p.id)}
                    >
                      {p.icon}
                      <span>{p.label}</span>
                      {isTrashed && (
                        <span style={{ marginLeft: 'auto', fontSize: 10, fontWeight: 600, color: 'var(--red)', background: 'var(--red-bg)', padding: '2px 7px', borderRadius: 99 }}>
                          LIXO
                        </span>
                      )}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

// ─── Main Export (Apenas Mobile/Tablet agora, já que desktop usa Sidebar) ───
export default function NavBar() {
  const activePage = useDash(s => s.activePage);
  const goTo = useDash(s => s.goTo);
  const modules = useDash(s => s.configData.modules || {});

  const filteredPages = PAGES.filter(p => {
    if (p.id === 'admin' && !FEATURES.SAAS_ADMIN) return false;
    if (p.id === 'feedback' && !FEATURES.FEEDBACK) return false;
    if (p.id === 'demo' && !FEATURES.DEMO_MODE) return false;

    if (p.id === 'dashboard') return true;
    if (p.id === 'leads') return !!modules.leads;
    if (p.id === 'projetos') return !!modules.projetos;
    if (p.id === 'clientes') return modules.clientes !== false;
    if (p.id === 'recorrencia') return !!modules.recorrencia;
    if (p.id === 'financas-negocio') return !!modules.negocio;
    if (p.id === 'financas-pessoais') return !!modules.pessoal;
    if (p.id === 'uptime') return modules.uptime !== false;
    return false;
  });

  return (
    <MobileNav filteredPages={filteredPages} activePage={activePage} goTo={goTo} />
  );
}

import { useDash, fmtDate } from '../store/useStore';
import { useRef, useEffect } from 'react';

export default function NotificationCenter({ onClose, toggleRef }) {
  const data = useDash(s => s.data);
  const markAsRead = useDash(s => s.markAsRead);
  const markAllAsRead = useDash(s => s.markAllAsRead);
  const clearAllNotifications = useDash(s => s.clearAllNotifications);
  const goTo = useDash(s => s.goTo);
  const dropdownRef = useRef(null);

  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        if (toggleRef?.current && toggleRef.current.contains(event.target)) return;
        onClose();
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [onClose]);

  const sortedNotifs = [...(data.notificacoes || [])].sort((a, b) => {
    const da = a.criadoEm?.seconds ? a.criadoEm.seconds * 1000 : new Date(a.criadoEm).getTime();
    const db = b.criadoEm?.seconds ? b.criadoEm.seconds * 1000 : new Date(b.criadoEm).getTime();
    return db - da;
  });

  const timeAgo = (dateStr) => {
    if (!dateStr) return '';
    const date = dateStr?.seconds ? new Date(dateStr.seconds * 1000) : new Date(dateStr);
    const seconds = Math.floor((new Date() - date) / 1000);
    let interval = Math.floor(seconds / 3600);
    if (interval >= 1) return `${interval}h atrás`;
    interval = Math.floor(seconds / 60);
    if (interval >= 1) return `${interval}m atrás`;
    return 'Agora';
  };

  const handleNotifClick = (n) => {
    if (!n.lida) markAsRead(n.id);
    if (n.action?.page) {
      goTo(n.action.page);
      onClose();
    }
  };

  // Page label for the "go to" arrow
  const PAGE_LABELS = {
    dashboard: 'Dashboard',
    leads: 'Leads',
    projetos: 'Projetos',
    financas: 'Finanças',
    recorrencia: 'Recorrência',
    clientes: 'Clientes',
  };

  const PriorityIcon = ({ priority }) => {
    const p = priority || 'Baixa';
    if (p === 'Alta') return (
      <svg className="notif-priority-icon Alta" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
      </svg>
    );
    if (p === 'Média') return (
      <svg className="notif-priority-icon Média" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
      </svg>
    );
    return (
      <svg className="notif-priority-icon Baixa" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/>
      </svg>
    );
  };

  return (
    <div className="notif-dropdown" ref={dropdownRef}>
      <div className="notif-header">
        <h3>Notificações {sortedNotifs.filter(n => !n.lida).length > 0 && <span style={{ fontSize: 12, fontWeight: 700, background: 'var(--color-accent)', color: 'var(--on-accent)', borderRadius: 99, padding: '1px 7px', marginLeft: 6 }}>{sortedNotifs.filter(n => !n.lida).length}</span>}</h3>
        <button className="btn-icon" aria-label="Fechar notificações" onClick={onClose} style={{ padding: 4 }}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 16, height: 16 }}>
            <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
          </svg>
        </button>
      </div>

      <div className="notif-list">
        {sortedNotifs.length === 0 ? (
          <div className="notif-empty">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 40, height: 40, opacity: 0.2, marginBottom: 12 }}>
              <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/>
            </svg>
            <p>Nenhuma notificação por aqui.</p>
          </div>
        ) : (
          sortedNotifs.map(n => (
            <div
              key={n.id}
              className={`notif-item ${!n.lida ? 'unread' : ''} ${n.priority || 'Baixa'}`}
              onClick={() => handleNotifClick(n)}
              style={{ cursor: n.action?.page ? 'pointer' : 'default' }}
            >
              <div className="notif-icon-wrap">
                <PriorityIcon priority={n.priority} />
              </div>
              <div className="notif-content" style={{ flex: 1, minWidth: 0 }}>
                <div className="notif-title">{n.title}</div>
                <div className="notif-msg">{n.message}</div>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginTop: 2 }}>
                  <div className="notif-time">{timeAgo(n.criadoEm)}</div>
                  {n.action?.page && (
                    <span style={{ fontSize: 10, color: 'var(--accent)', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 3, flexShrink: 0 }}>
                      {PAGE_LABELS[n.action.page] || n.action.page}
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 10, height: 10 }}>
                        <path d="M5 12h14M12 5l7 7-7 7"/>
                      </svg>
                    </span>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {sortedNotifs.length > 0 && (
        <div className="notif-footer">
          <button onClick={markAllAsRead}>Marcar todas como lidas</button>
          <button onClick={clearAllNotifications}>Limpar tudo</button>
        </div>
      )}
    </div>
  );
}

import html2pdf from 'html2pdf.js';
import { fmtBRL, fmtDate } from '../store/useStore';
import { formatMinutes } from '../utils/timeUtils';

const blobToDataUrl = (blob) => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result);
    reader.onerror = () => resolve(null);
    reader.readAsDataURL(blob);
  });
};

const imgToDataUrl = async (url) => {
  if (!url) return null;
  if (url.startsWith('data:')) return url;

  // 1. Tenta fetch direto com CORS
  try {
    const res = await fetch(url, { mode: 'cors' });
    if (res.ok) {
      const blob = await res.blob();
      const b64 = await blobToDataUrl(blob);
      if (b64) return b64;
    }
  } catch (e) {}

  // 2. Se for domínio de storage, tenta via proxy local do Vite (para desenvolvimento)
  if (url.includes('dashboard.thiagomaieski.com')) {
    try {
      const proxyUrl = url.replace('https://dashboard.thiagomaieski.com', '/api-storage');
      const res = await fetch(proxyUrl);
      if (res.ok) {
        const blob = await res.blob();
        const b64 = await blobToDataUrl(blob);
        if (b64) return b64;
      }
    } catch (e) {}
  }

  // 3. Tenta via proxy CORS seguro público
  try {
    const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
    const res = await fetch(proxyUrl);
    if (res.ok) {
      const blob = await res.blob();
      const b64 = await blobToDataUrl(blob);
      if (b64) return b64;
    }
  } catch (e) {}

  // 4. Fallback com Image + Canvas
  try {
    const b64 = await new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = 'Anonymous';
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0);
          resolve(canvas.toDataURL('image/png'));
        } catch (e) {
          resolve(null);
        }
      };
      img.onerror = () => resolve(null);
      img.src = url;
    });
    if (b64) return b64;
  } catch (e) {}

  // Se nenhum converter para DataURL, retorna a própria URL para usar diretamente na tag img
  return url;
};

const getLogoHtml = (configData, base64Logo) => {
  const logo = base64Logo || configData?.pdfLogoBase64 || configData?.pdfLogo;
  if (logo) {
    return `<img src="${logo}" style="max-height: 64px; max-width: 240px; object-fit: contain; margin: 0 auto; display: block;" />`;
  }
  return `<div style="font-size: 24px; font-weight: 800; color: #0f172a;">${configData?.nomeEmpresa || 'Minha Empresa'}</div>`;
};

const getEmpresaBlock = (cd) => {
