    cd.nomeEmpresa ? `<div style="font-weight:600;font-size:16px;margin-bottom:4px;">${cd.nomeEmpresa}</div>` : '',
    cd.cnpj ? `<div>CNPJ/CPF: ${cd.cnpj}</div>` : '',
