import { useEffect, useRef } from 'react';
import { useDash } from '../store/useStore';

// ── GLOBAL TOP BAR (vai-e-vem para ações internas) ──
export function GlobalLoader({ forced = false }) {
  const loadingState = useDash(s => s.loading);
  const show = forced || loadingState;
  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, right: 0, height: 2, zIndex: 9998,
      background: 'transparent', pointerEvents: 'none',
    }}>
      <div style={{
        height: '100%',
        background: 'var(--accent)',
        boxShadow: '0 0 8px var(--accent)',
        opacity: show ? 1 : 0,
        transition: show ? 'opacity .15s' : 'opacity .4s .2s',
        animation: show ? 'globalLoaderInd 1.1s ease-in-out infinite' : 'none',
        width: '40%',
      }} />
    </div>
  );
}

// ── TOAST NOTIFICATIONS ──
const ICONS = {
  success: (
    <svg viewBox="0 0 24 24" fill="none" strokeWidth="2.5" stroke="currentColor" style={{ width: 15, height: 15, flexShrink: 0 }}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  ),
  error: (
    <svg viewBox="0 0 24 24" fill="none" strokeWidth="2.5" stroke="currentColor" style={{ width: 15, height: 15, flexShrink: 0 }}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
    </svg>
  ),
  info: (
    <svg viewBox="0 0 24 24" fill="none" strokeWidth="2.5" stroke="currentColor" style={{ width: 15, height: 15, flexShrink: 0 }}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z" />
    </svg>
  ),
  warning: (
    <svg viewBox="0 0 24 24" fill="none" strokeWidth="2.5" stroke="currentColor" style={{ width: 15, height: 15, flexShrink: 0 }}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
    </svg>
  ),
};

const TOAST_STYLES = {
  success: {
    border: '1px solid rgba(34,197,94,.35)',
    background: 'rgba(34,197,94,.08)',
    accent: 'var(--green)',
    track: 'rgba(34,197,94,.25)',
  },
  error: {
    border: '1px solid rgba(239,68,68,.35)',
    background: 'rgba(239,68,68,.08)',
    accent: 'var(--red)',
    track: 'rgba(239,68,68,.25)',
  },
  warning: {
    border: '1px solid rgba(245,158,11,.35)',
    background: 'rgba(245,158,11,.08)',
    accent: 'var(--amber)',
    track: 'rgba(245,158,11,.25)',
  },
  info: {
    border: '1px solid rgba(59,130,246,.35)',
    background: 'rgba(59,130,246,.08)',
    accent: 'var(--blue)',
    track: 'rgba(59,130,246,.25)',
  },
};

function ToastItem({ msg, type = 'success', duration = 3400 }) {
  const ref = useRef(null);
  const style = TOAST_STYLES[type] || TOAST_STYLES.success;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    setTimeout(() => el.classList.add('show'), 10);
    const timer = setTimeout(() => el.classList.remove('show'), duration - 350);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div ref={ref} className="toast-item">
      <div className="toast-content">
        <div className="toast-icon" style={{ background: style.background, color: style.accent }}>
          {ICONS[type] || ICONS.success}
        </div>
        <span className="toast-msg">{msg}</span>
      </div>

      <div className="toast-progress-track" style={{ background: style.track }}>
        <div 
          className="toast-progress-fill" 
          style={{ background: style.accent, animation: `toastProg ${duration}ms linear forwards` }} 
        />
      </div>
    </div>
  );
}

export default function Toast() {
  const toasts = useDash(s => s.toasts);
  return (
    <div id="toast" role="status" aria-live="polite" aria-atomic="false">
      {toasts.map(t => <ToastItem key={t.id} msg={t.msg} type={t.type} duration={t.duration} />)}
    </div>
  );
}

import { useState } from 'react';
import { useDash } from '../../store/useStore';
import { auth } from '../../firebase';
import CustomSelect from '../CustomSelect';
import './ClienteForm.css';

export function isValidCpf(raw = '') {
  const cpf = (raw || '').replace(/\D/g, '');
  if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += parseInt(cpf[i], 10) * (10 - i);
  let d1 = (sum * 10) % 11;
  if (d1 === 10) d1 = 0;
  if (d1 !== parseInt(cpf[9], 10)) return false;
  sum = 0;
  for (let i = 0; i < 10; i++) sum += parseInt(cpf[i], 10) * (11 - i);
  let d2 = (sum * 10) % 11;
  if (d2 === 10) d2 = 0;
  return d2 === parseInt(cpf[10], 10);
}

export function isValidCnpj(raw = '') {
  const cnpj = (raw || '').replace(/\D/g, '');
  if (cnpj.length !== 14 || /^(\d)\1{13}$/.test(cnpj)) return false;
  const calc = (base, weights) => {
    let sum = 0;
    for (let i = 0; i < weights.length; i++) {
      sum += parseInt(base[i], 10) * weights[i];
    }
    const rem = sum % 11;
    return rem < 2 ? 0 : 11 - rem;
  };
  const w1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
  const w2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
  const d1 = calc(cnpj, w1);
  const d2 = calc(cnpj, w2);
  return d1 === parseInt(cnpj[12], 10) && d2 === parseInt(cnpj[13], 10);
}

export function maskCpfCnpjInput(val = '') {
  const raw = (val || '').replace(/\D/g, '').slice(0, 14);
  if (raw.length <= 11) {
    if (raw.length > 9) return raw.replace(/^(\d{3})(\d{3})(\d{3})(\d{1,2})$/, '$1.$2.$3-$4');
    if (raw.length > 6) return raw.replace(/^(\d{3})(\d{3})(\d{1,3})$/, '$1.$2.$3');
    if (raw.length > 3) return raw.replace(/^(\d{3})(\d{1,3})$/, '$1.$2');
    return raw;
  }
  if (raw.length > 12) return raw.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{1,2})$/, '$1.$2.$3/$4-$5');
  if (raw.length > 8) return raw.replace(/^(\d{2})(\d{3})(\d{3})(\d{1,4})$/, '$1.$2.$3/$4');
  if (raw.length > 5) return raw.replace(/^(\d{2})(\d{3})(\d{1,3})$/, '$1.$2.$3');
  if (raw.length > 2) return raw.replace(/^(\d{2})(\d{1,3})$/, '$1.$2');
  return raw;
}

function formatCnpjPhone(rawPhone = '') {
  const d = (rawPhone || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length === 11) return d.replace(/^(\d{2})(\d{5})(\d{4})$/, '($1) $2-$3');
  if (d.length === 10) return d.replace(/^(\d{2})(\d{4})(\d{4})$/, '($1) $2-$3');
  return rawPhone;
}

export async function fetchBrasilApiCnpj(cnpjDigits) {
  const directUrl = `https://brasilapi.com.br/api/cnpj/v1/${cnpjDigits}`;
  let data = null;

  try {
    const res = await fetch(directUrl, { method: 'GET', headers: { Accept: 'application/json' } });
    if (res.status === 404) {
      throw new Error('CNPJ não encontrado na base da Receita Federal.');
    }
    if (res.status === 429) {
      throw new Error('Limite de consultas atingido. Aguarde alguns instantes e tente novamente.');
    }
    if (!res.ok) {
      throw new Error(`HTTP_${res.status}`);
    }
    data = await res.json();
  } catch (err) {
    if (err.message.includes('CNPJ não encontrado') || err.message.includes('Limite de consultas')) {
      throw err;
    }
    // Fallback pelo proxy.php se houver bloqueio de CORS ou falha direta
    try {
      const token = auth.currentUser ? await auth.currentUser.getIdToken() : null;
      const domain = (import.meta.env.VITE_STORAGE_API_DOMAIN || window.location.origin).replace(/\/+$/, '');
      const proxyRes = await fetch(`${domain}/proxy.php?action=cnpj&cnpj=${cnpjDigits}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (proxyRes.status === 404) {
        throw new Error('CNPJ não encontrado na base da Receita Federal.');
      }
      if (proxyRes.status === 429) {
        throw new Error('Limite de consultas atingido. Aguarde alguns instantes e tente novamente.');
      }
      if (!proxyRes.ok) {
        throw new Error('Não foi possível consultar o CNPJ no momento. Verifique sua conexão.');
      }
      data = await proxyRes.json();
    } catch (fallbackErr) {
      throw new Error(fallbackErr.message || 'Falha ao consultar CNPJ. Preencha manualmente.');
    }
  }

  const razaoSocial = (data.razao_social || '').trim();
  const nomeFantasia = (data.nome_fantasia || '').trim();
  const nome = nomeFantasia || razaoSocial;
  const email = (data.email || '').trim().toLowerCase();
  const telefone = formatCnpjPhone(data.ddd_telefone_1 || data.ddd_telefone_2 || '');

  const tipoLogr = (data.descricao_tipo_de_logradouro || '').trim();
  const logr = (data.logradouro || '').trim();
  const rua = [tipoLogr, logr].filter(Boolean).join(' ').trim();
  const numero = (data.numero || '').trim();
  const compl = (data.complemento || '').trim();
  const bairro = (data.bairro || '').trim();
  const cidadeUf = [data.municipio, data.uf].filter(Boolean).join('/');
  const cep = data.cep ? String(data.cep).replace(/\D/g, '').replace(/^(\d{5})(\d{3})$/, '$1-$2') : '';
  const endereco = [
    rua ? `${rua}${numero ? `, ${numero}` : ''}` : '',
    compl,
    bairro,
    cidadeUf,
    cep ? `CEP ${cep}` : '',
  ].filter(Boolean).join(' - ');

  const situacao = (data.descricao_situacao_cadastral || '').trim();

  return {
    razaoSocial,
    nomeFantasia,
    nome,
    email,
    telefone,
    endereco,
    situacao,
  };
}

export default function ClienteForm({ item }) {
  const saveCliente = useDash(s => s.saveCliente);
  const closeModal = useDash(s => s.closeModal);
  const toast = useDash(s => s.toast);

  const [f, setF] = useState({
    nome: item?.nome || '',
    razaoSocial: item?.razaoSocial || '',
    nomeFantasia: item?.nomeFantasia || '',
    cpfCnpj: item?.cpfCnpj || '',
    email: item?.email || '',
    telefone: item?.telefone || '',
    conheceu: item?.conheceu || 'Instagram',
    segmento: item?.segmento || '',
    instagram: item?.instagram || '',
    facebook: item?.facebook || '',
    youtube: item?.youtube || '',
    site: item?.site || '',
    linkCustom: item?.linkCustom || '',
    endereco: item?.endereco || '',
    observacoes: item?.observacoes || '',
  });

  const [loadingCnpj, setLoadingCnpj] = useState(false);
  const [cnpjError, setCnpjError] = useState('');
  const [situacaoWarn, setSituacaoWarn] = useState('');
  const [pendingCnpjData, setPendingCnpjData] = useState(null);

  const u = (k) => (e) => setF(p => ({ ...p, [k]: e.target.value }));
  const CONH = ['Instagram', 'Meta ADS', 'Google', 'Google Maps', 'Facebook', 'Formação WEBP', 'Indicação', 'Outro'];

  const digits = (f.cpfCnpj || '').replace(/\D/g, '');
  const isCpfLen = digits.length === 11;
  const isCnpjLen = digits.length === 14;
  const cpfValid = isCpfLen ? isValidCpf(digits) : false;
  const cnpjValid = isCnpjLen ? isValidCnpj(digits) : false;

  const applyCnpjFields = (res) => {
    setF(prev => ({
      ...prev,
      razaoSocial: res.razaoSocial || prev.razaoSocial,
      nomeFantasia: res.nomeFantasia || prev.nomeFantasia,
      nome: res.nome || prev.nome,
      email: res.email || prev.email,
      telefone: res.telefone || prev.telefone,
      endereco: res.endereco || prev.endereco,
    }));
    setPendingCnpjData(null);
    toast('Dados do CNPJ preenchidos!', 'success');
  };

  const handleBuscarCnpj = async () => {
    if (!cnpjValid || loadingCnpj) return;
    setLoadingCnpj(true);
    setCnpjError('');
    setSituacaoWarn('');
    setPendingCnpjData(null);

    try {
      const res = await fetchBrasilApiCnpj(digits);
      if (res.situacao && res.situacao.toUpperCase() !== 'ATIVA') {
        setSituacaoWarn(`Atenção: Situação cadastral na Receita Federal consta como "${res.situacao}".`);
      }

      // Verifica se algum campo já preenchido seria sobrescrito
      const hasConflict =
        (f.nome.trim() && res.nome && f.nome.trim() !== res.nome) ||
        (f.email.trim() && res.email && f.email.trim() !== res.email) ||
        (f.telefone.trim() && res.telefone && f.telefone.trim() !== res.telefone) ||
        (f.endereco.trim() && res.endereco && f.endereco.trim() !== res.endereco);

      if (hasConflict) {
        setPendingCnpjData(res);
      } else {
        applyCnpjFields(res);
      }
    } catch (err) {
      setCnpjError(err.message || 'Erro ao buscar dados do CNPJ.');
    } finally {
      setLoadingCnpj(false);
    }
  };

  const handleSave = () => {
    if (!f.nome) return toast('O nome/empresa é obrigatório.', 'error');
    saveCliente(f);
  };

  return (
    <div className="form-grid cliente-form">
      <section className="cliente-form-section">
      <h3>Identificação</h3>
      <p className="cliente-form-hint">Dados do cliente e consulta de CNPJ. Nome / Empresa é obrigatório.</p>
      <div className="form-grid form-grid-2">
        <div className="form-group">
          <label className="form-label" htmlFor="cliente-nome">Nome / Empresa *</label>
          <input className="form-input" id="cliente-nome" value={f.nome} onChange={u('nome')} />
        </div>
        <div className="form-group">
          <label className="form-label" htmlFor="cliente-cpfCnpj">CNPJ / CPF</label>
          <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
            <input
              className="form-input"
              style={{ flex: 1 }}
              id="cliente-cpfCnpj" value={f.cpfCnpj}
              onChange={e => {
                const masked = maskCpfCnpjInput(e.target.value);
                setCnpjError('');
                setSituacaoWarn('');
                setPendingCnpjData(null);
                setF(p => ({ ...p, cpfCnpj: masked }));
              }}
              placeholder="000.000.000-00 ou 00.000.000/0000-00"
            />
            {isCnpjLen && cnpjValid && (
              <button
                type="button"
                className="btn btn-sm btn-secondary"
                onClick={handleBuscarCnpj}
                disabled={loadingCnpj}
                style={{ whiteSpace: 'nowrap', height: 36, padding: '0 12px', color: 'var(--accent)', borderColor: 'var(--accent)' }}
              >
                {loadingCnpj ? 'Buscando...' : 'Buscar dados'}
              </button>
            )}
          </div>
          {digits.length > 0 && ![11, 14].includes(digits.length) && (
            <div style={{ fontSize: 10, color: 'var(--red)', marginTop: 4 }}>
              Documento incompleto ({digits.length} dígitos — informe 11 para CPF ou 14 para CNPJ)
            </div>
          )}
          {isCpfLen && !cpfValid && (
            <div style={{ fontSize: 10, color: 'var(--red)', marginTop: 4 }}>
              CPF inválido (verifique os dígitos)
            </div>
          )}
          {isCnpjLen && !cnpjValid && (
            <div style={{ fontSize: 10, color: 'var(--red)', marginTop: 4 }}>
              CNPJ inválido (dígitos verificadores incorretos)
            </div>
          )}
          {cnpjError && (
            <div style={{ fontSize: 11, color: 'var(--red)', marginTop: 4 }}>
              {cnpjError}
            </div>
          )}
        </div>
      </div>

      {situacaoWarn && (
        <div
          style={{
            padding: '10px 12px',
            borderRadius: 'var(--r-sm, 6px)',
            background: 'rgba(245, 158, 11, 0.1)',
            border: '1px solid rgba(245, 158, 11, 0.3)',
            color: 'var(--amber)',
            fontSize: 12,
            fontWeight: 500,
          }}
        >
          {situacaoWarn}
        </div>
      )}

      {pendingCnpjData && (
        <div role="region" aria-label="Confirmar dados do CNPJ" aria-live="polite"
          style={{
            padding: '12px 14px',
            borderRadius: 'var(--r-md, 8px)',
            background: 'var(--bg3)',
            border: '1px solid var(--accent)',
            fontSize: 12,
            display: 'flex',
            flexDirection: 'column',
            gap: 8,
          }}
        >
          <div style={{ fontWeight: 600, color: 'var(--text)' }}>
            Preencher estes campos encontrados no CNPJ?
          </div>
          <div style={{ display: 'grid', gap: 4, color: 'var(--text2)', fontSize: 11 }}>
            {pendingCnpjData.nome && <div><strong>Nome:</strong> {pendingCnpjData.nome}</div>}
            {pendingCnpjData.razaoSocial && <div><strong>Razão Social:</strong> {pendingCnpjData.razaoSocial}</div>}
            {pendingCnpjData.email && <div><strong>E-mail:</strong> {pendingCnpjData.email}</div>}
            {pendingCnpjData.telefone && <div><strong>Telefone:</strong> {pendingCnpjData.telefone}</div>}
            {pendingCnpjData.endereco && <div><strong>Endereço:</strong> {pendingCnpjData.endereco}</div>}
          </div>
          <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 4 }}>
            <button type="button" className="btn btn-sm btn-secondary" onClick={() => setPendingCnpjData(null)}>
              Cancelar
            </button>
            <button type="button" className="btn btn-sm btn-primary" onClick={() => applyCnpjFields(pendingCnpjData)}>
              Aplicar
            </button>
          </div>
        </div>
      )}

      {(f.razaoSocial || f.nomeFantasia) && (
        <div className="form-grid form-grid-2">
          <div className="form-group">
            <label className="form-label" htmlFor="cliente-razaoSocial">Razão Social</label>
            <input className="form-input" id="cliente-razaoSocial" value={f.razaoSocial} onChange={u('razaoSocial')} />
          </div>
          <div className="form-group">
            <label className="form-label" htmlFor="cliente-nomeFantasia">Nome Fantasia</label>
            <input className="form-input" id="cliente-nomeFantasia" value={f.nomeFantasia} onChange={u('nomeFantasia')} />
          </div>
        </div>
      )}

      </section>
      <section className="cliente-form-section">
      <h3>Contato e cadastro</h3>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label" htmlFor="cliente-email">E-mail</label><input className="form-input" id="cliente-email" value={f.email} onChange={u('email')} /></div>
        <div className="form-group"><label className="form-label" htmlFor="cliente-telefone">Telefone</label><input className="form-input" id="cliente-telefone" value={f.telefone} onChange={u('telefone')} /></div>
      </div>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Como Conheceu</label>
          <CustomSelect variant="form" value={f.conheceu} onChange={u('conheceu')}>
            {CONH.map(s => <option key={s}>{s}</option>)}
          </CustomSelect>
        </div>
        <div className="form-group"><label className="form-label" htmlFor="cliente-segmento">Segmento</label><input className="form-input" id="cliente-segmento" value={f.segmento} onChange={u('segmento')} /></div>
      </div>
      <div className="form-group"><label className="form-label" htmlFor="cliente-endereco">Endereço Completo</label><input className="form-input" id="cliente-endereco" value={f.endereco} onChange={u('endereco')} /></div>
      <div className="form-group"><label className="form-label" htmlFor="cliente-observacoes">Observações</label><textarea className="form-textarea" style={{ minHeight: 60 }} id="cliente-observacoes" value={f.observacoes} onChange={u('observacoes')} /></div>
      
      </section>
      <section className="cliente-form-section">
      <div className="form-group" style={{ marginTop: 8 }}>
        <label className="form-label" style={{ marginBottom: 12 }}>Links e Redes Sociais</label>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
          {[
            { key: 'instagram', icon: 'IG', placeholder: '@usuario' },
            { key: 'facebook', icon: 'FB', placeholder: '/pagina' },
            { key: 'youtube', icon: 'YT', placeholder: '/canal' },
            { key: 'site', icon: 'Web', placeholder: 'site.com' },
          ].map(({ key, icon, placeholder }) => (
            <div key={key} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span style={{ width: 36, height: 36, borderRadius: 6, background: 'var(--bg4)', border: '1px solid var(--border2)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontSize: 12, fontWeight: 600 }}>{icon}</span>
              <input aria-label={key} className="form-input" placeholder={placeholder} value={f[key]} onChange={u(key)} style={{ flex: 1 }} />
            </div>
          ))}
        </div>
      </div>
      </section>
      <div className="form-actions" style={{ marginTop: 8 }}>
        <button className="btn btn-secondary" onClick={closeModal}>Cancelar</button>
        <button className="btn btn-primary" onClick={handleSave}>Salvar</button>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo, useRef } from 'react';
import { useDash, getWaLink } from '../../store/useStore';
import { INTERACAO_TIPO_LABELS, INTERACAO_TIPOS, LEAD_STATUSES, QUAL_CHIPS, generatePitchMessage } from '../../utils/crmAnalyticsUtils';
import { qualifyLeadWithAi, generateLeadMessageWithAi } from '../../utils/aiApi';
import CustomSelect from '../CustomSelect';
import Drawer from '../ui/Drawer';
import Modal from '../ui/Modal';
import Button from '../ui/Button';
import Badge from '../ui/Badge';
import './LeadDrawer.css';
import { PageSpeedScore } from './LeadForm';
import { navToConfigTab } from './shared';

const STEP_ORDER_DRAWER = ['pagespeed', 'instagram', 'screenshot'];
const STEP_LABELS_DRAWER = { pagespeed: 'PageSpeed', instagram: 'Instagram', screenshot: 'Screenshot' };

function resizeImageToMax1600(file) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const objectUrl = URL.createObjectURL(file);
    img.onload = () => {
      URL.revokeObjectURL(objectUrl);
      const maxDim = 1600;
      const scale = Math.min(1, maxDim / Math.max(img.width || 1, img.height || 1));
      const width = Math.max(1, Math.round(img.width * scale));
      const height = Math.max(1, Math.round(img.height * scale));
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, width, height);
      canvas.toBlob(
        (blob) => {
          if (!blob) return reject(new Error('Falha ao comprimir imagem'));
          resolve(new File([blob], `screenshot_${Date.now()}.jpg`, { type: 'image/jpeg' }));
        },
        'image/jpeg',
        0.85
      );
    };
    img.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      reject(new Error('Imagem inválida'));
    };
    img.src = objectUrl;
  });
}

export default function LeadDrawer({ isOpen, onClose, item }) {
  const data = useDash(s => s.data);
  const configData = useDash(s => s.configData);
  const saveLead = useDash(s => s.saveLead);
  const saveLeadNotes = useDash(s => s.saveLeadNotes);
  const openModal = useDash(s => s.openModal);
  const goTo = useDash(s => s.goTo);
  const setConfigTab = useDash(s => s.setConfigTab);
  const runPreQualification = useDash(s => s.runPreQualification);
  const deleteLeadScreenshot = useDash(s => s.deleteLeadScreenshot);
  const uploadManualScreenshot = useDash(s => s.uploadManualScreenshot);
  const saveLeadAiQualification = useDash(s => s.saveLeadAiQualification);
  const aiUsage = useDash(s => s.aiUsage);
  const setAiUsage = useDash(s => s.setAiUsage);
  const refreshAiUsage = useDash(s => s.refreshAiUsage);
  const filteredLeadIds = useDash(s => s.filteredLeadIds);

  const [activeSection, setActiveSection] = useState('resumo');
  const identityRef = useRef(null);

  const navTo = (tab) => navToConfigTab(onClose, setConfigTab, goTo, tab);

  const navListIds = useMemo(() => {
    if (Array.isArray(filteredLeadIds) && filteredLeadIds.length > 0) return filteredLeadIds;
    return (data?.leads || []).map(l => l.id);
  }, [filteredLeadIds, data?.leads]);

  const currentIdx = item?.id ? navListIds.indexOf(item.id) : -1;
  const prevLeadId = currentIdx > 0 ? navListIds[currentIdx - 1] : null;
  const nextLeadId = currentIdx >= 0 && currentIdx < navListIds.length - 1 ? navListIds[currentIdx + 1] : null;

  const existingCidades = useMemo(() => {
    const set = new Set();
    (data?.leads || []).forEach(l => {
      if (l.cidade && l.cidade.trim()) set.add(l.cidade.trim());
    });
    return Array.from(set).sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [data?.leads]);

  const existingLotes = useMemo(() => {
    const set = new Set();
    (data?.leads || []).forEach(l => {
      if (l.lote && l.lote.trim()) set.add(l.lote.trim());
    });
    return Array.from(set).sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [data?.leads]);

  const [intText, setIntText] = useState('');
  const [intTipo, setIntTipo] = useState('outro');
  const [f, setF] = useState({
    nome: '', telefone: '', cidade: '', lote: '', email: '', origem: '',
    valorEstimado: '', ultimoContato: '', proximoContato: '',
    nicho: configData.nichos[0] || '',
    status: 'Novo', site: '', observacoes: '',
    interacoes: [],
    botBarreira: false,
    qualChips: [],
  });

  // Sincroniza estado do formulário quando muda o lead selecionado (ex: setas ↑/↓)
  useEffect(() => {
    setF({
      nome: item?.nome || '',
      telefone: item?.telefone || '',
      cidade: item?.cidade || '',
      lote: item?.lote || '',
      email: item?.email || '',
      origem: item?.origem || '',
      valorEstimado: item?.valorEstimado || '',
      ultimoContato: item?.ultimoContato || '',
      proximoContato: item?.proximoContato || '',
      nicho: item?.nicho || configData.nichos[0] || '',
      status: item?.status || 'Novo',
      site: item?.site || '',
      observacoes: item?.observacoes || '',
      interacoes: item?.interacoes || [],
      botBarreira: !!item?.botBarreira,
      qualChips: Array.isArray(item?.qualChips) ? item.qualChips : [],
    });
    setActiveSection('resumo');
    setIntText('');
    setSingleProgress(null);
    setAiDraft(null);
    setAiError(null);
    setMsgDraft('');
    setMsgError(null);
    setMsgTipo((item?.status && item.status !== 'Novo') ? 'follow_up' : 'abordagem_inicial');
    setLightboxOpen(false);
  }, [item?.id, isOpen]);

  const u = (k) => (e) => {
    // Radix can emit an empty native-select event during form initialization.
    // Status and niche have no empty option: keep their populated values.
    if ((k === 'status' || k === 'nicho') && e.target.value === '') return;
    setF(p => ({ ...p, [k]: e.target.value }));
  };

  const [isPrequaling, setIsPrequaling] = useState(false);
  const [isAiQualifying, setIsAiQualifying] = useState(false);
  const [aiDraft, setAiDraft] = useState(null); // { chips, resumo, prioridade } aguardando confirmação
  const [aiError, setAiError] = useState(null);
  const [msgTipo, setMsgTipo] = useState('abordagem_inicial');
  const [isGeneratingMsg, setIsGeneratingMsg] = useState(false);
  const [msgDraft, setMsgDraft] = useState('');
  const [msgError, setMsgError] = useState(null);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxNotes, setLightboxNotes] = useState('');
  const [singleProgress, setSingleProgress] = useState(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploadingPrint, setIsUploadingPrint] = useState(false);

  // T3.5: Colar print da área de transferência (Ctrl+V) reduzindo para no máx 1600px
  useEffect(() => {
    if (!isOpen || !item?.id) return;
    const handlePaste = async (e) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      for (const clipItem of items) {
        if (clipItem.type && clipItem.type.startsWith('image/')) {
          e.preventDefault();
          const rawFile = clipItem.getAsFile();
          if (!rawFile || isUploadingPrint) return;
          setIsUploadingPrint(true);
          try {
            const resized = await resizeImageToMax1600(rawFile);
            await uploadManualScreenshot(item.id, resized);
          } catch (err) {
            useDash.getState().toast('Erro ao colar print: ' + (err.message || 'Falha'), 'error');
          } finally {
            setIsUploadingPrint(false);
          }
          break;
        }
      }
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [isOpen, item?.id, isUploadingPrint, uploadManualScreenshot]);

  const prequalData = item?.prequalData || null;
  const screenshotUrlWithCacheBuster = prequalData?.screenshotUrl
    ? `${prequalData.screenshotUrl}${prequalData.screenshotUrl.includes('?') ? '&' : '?'}t=${prequalData.prequalizedAt ? new Date(prequalData.prequalizedAt).getTime() : Date.now()}`
    : null;

  const handleSinglePreQual = () => {
    if (!item?.id || isPrequaling) return;
    setIsPrequaling(true);
    setSingleProgress({ status: 'processing', steps: {}, message: null });

    const onProgress = (event) => {
      setSingleProgress(prev => {
        if (!prev) return prev;
        if (event.type === 'step') {
          return {
            ...prev,
            steps: {
              ...prev.steps,
              [event.step]: { status: event.status, count: event.count, mobile: event.mobile, desktop: event.desktop, followers: event.followers, error: event.error },
            },
          };
        }
        if (event.type === 'success') return { ...prev, status: 'success' };
        if (event.type === 'error')   return { ...prev, status: 'error', message: event.error || 'Erro desconhecido' };
        if (event.type === 'skipped') return { ...prev, status: 'skipped', message: event.reason };
        return prev;
      });
    };

    runPreQualification([item.id], onProgress).finally(() => {
      setIsPrequaling(false);
      setTimeout(() => {
        setSingleProgress(p => p?.status === 'success' ? null : p);
      }, 6000);
    });
  };

  const handleQualifyWithAi = async () => {
    if (!item?.id || isAiQualifying) return;
    setIsAiQualifying(true);
    setAiError(null);
    try {
      const mergedLead = { ...item, ...f };
      const res = await qualifyLeadWithAi(mergedLead, {
        aiProvider: configData.aiProvider || 'gemini',
        ollamaModel: configData.ollamaModel || 'llama3.2',
      });
      if (res.usage) setAiUsage(res.usage);
      if (!res.ok) {
        setAiError(res.error || 'Falha ao qualificar com IA.');
        return;
      }
      const mergedChips = Array.from(new Set([...(f.qualChips || []), ...(res.chips || [])]));
      setF(p => ({
        ...p,
        qualChips: mergedChips,
        observacoes: p.observacoes?.trim() ? p.observacoes : (res.resumo || ''),
      }));
      setAiDraft({
        chips: mergedChips,
        resumo: res.resumo || '',
        prioridade: res.prioridade || 'media',
      });
    } finally {
      setIsAiQualifying(false);
    }
  };

  const handleConfirmAiDraft = async () => {
    if (!item?.id || !aiDraft) return;
    await saveLeadAiQualification(item.id, {
      chips: f.qualChips,
      resumo: aiDraft.resumo,
      prioridade: aiDraft.prioridade,
      observacoes: f.observacoes,
    });
    setAiDraft(null);
  };

  const handleGenerateAiMessage = async () => {
    if (isGeneratingMsg) return;
    setIsGeneratingMsg(true);
    setMsgError(null);
    try {
      const mergedLead = { ...item, ...f };
      const res = await generateLeadMessageWithAi(mergedLead, {
        tipo: msgTipo,
        instrucoes: configData.aiInstrucoes || '',
        aiProvider: configData.aiProvider || 'gemini',
        ollamaModel: configData.ollamaModel || 'llama3.2',
      });
      if (res.usage) setAiUsage(res.usage);
      if (!res.ok) {
        setMsgError(res.error || 'Falha ao gerar mensagem com IA.');
        return;
      }
      setMsgDraft(res.mensagem || '');
    } finally {
      setIsGeneratingMsg(false);
    }
  };

  const handleGenerateOfflineMessage = () => {
    setMsgError(null);
    const mergedLead = { ...item, ...f };
    const text = generatePitchMessage(mergedLead, msgTipo);
    setMsgDraft(text || '');
  };

  const handleCopyMessage = async () => {
    if (!msgDraft.trim()) return;
    try {
      await navigator.clipboard.writeText(msgDraft);
      useDash.getState().toast('Mensagem copiada para a área de transferência!');
    } catch {
      useDash.getState().toast('Falha ao copiar mensagem.', 'error');
    }
  };

  const handleOpenWhatsAppWithText = () => {
    const waBase = getWaLink(f.telefone);
    if (!waBase) {
      useDash.getState().toast('Informe um telefone válido antes de abrir o WhatsApp.', 'error');
      return;
    }
    const url = msgDraft.trim()
      ? `${waBase}?text=${encodeURIComponent(msgDraft.trim())}`
      : waBase;
    if (item?.id) {
      window.dispatchEvent(new CustomEvent('msk:wa-clicked', {
        detail: { id: item.id, nome: f.nome || item.nome || 'Lead', status: f.status || item.status || 'Novo' }
      }));
    }
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  const handleSave = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (isSaving) return;
    if (!f.nome || !f.nome.trim()) {
      return useDash.getState().toast('O Nome/Empresa é obrigatório.', 'error');
    }
    setIsSaving(true);
    try {
      await saveLead({ ...f, id: item?.id });
    } finally {
      setIsSaving(false);
    }
  };

  // Atalhos: Ctrl+S (salvar) e ↑ / ↓ (navegar entre leads quando fora de campos de texto)
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e) => {
      if (lightboxOpen || e.defaultPrevented || document.querySelector('.custom-select-content')) return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
        e.preventDefault();
        handleSave();
        return;
      }
      const tag = (e.target?.tagName || '').toLowerCase();
      const isEditable = tag === 'input' || tag === 'textarea' || tag === 'select' || e.target?.isContentEditable;
      if (isEditable || lightboxOpen) return;

      if (e.key === 'ArrowUp' && prevLeadId) {
        e.preventDefault();
        openModal('lead', prevLeadId);
      } else if (e.key === 'ArrowDown' && nextLeadId) {
        e.preventDefault();
        openModal('lead', nextLeadId);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, f, item?.id, isSaving, prevLeadId, nextLeadId, lightboxOpen]);

  const titleNode = (
    <span className="lead-drawer-title">
      <span>{item ? 'Detalhes do lead' : 'Novo Lead'}</span>
      {item && currentIdx !== -1 && (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
          <button
            type="button"
            className="btn btn-sm btn-secondary"
            disabled={!prevLeadId}
            onClick={() => prevLeadId && openModal('lead', prevLeadId)}
            title="Lead anterior na lista (Seta ↑)"
            aria-label="Lead anterior"
          >
            ↑
          </button>
          <span style={{ fontSize: 11, color: 'var(--text3)', fontWeight: 500 }}>
            {currentIdx + 1}/{navListIds.length}
          </span>
          <button
            type="button"
            className="btn btn-sm btn-secondary"
            disabled={!nextLeadId}
            onClick={() => nextLeadId && openModal('lead', nextLeadId)}
            title="Próximo lead na lista (Seta ↓)"
            aria-label="Próximo lead"
          >
            ↓
          </button>
        </span>
      )}
    </span>
  );

  const footerNode = (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%', gap: 10, flexWrap: 'wrap' }}>
      <div>
        {item && (
          <Button
            type="button"
            variant="secondary"
            style={{ color: 'var(--green)', gap: 6, fontSize: 12 }}
            onClick={() => useDash.getState().convertLeadToCliente(item.id)}
            title="Converter lead em cliente cadastrado"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
              <path d="M16 21v-2a4 4 0 0 0-4-4H5c-1.1 0-2 .9-2 2v2"/>
              <circle cx="8.5" cy="7" r="4"/>
              <polyline points="17 11 19 13 23 9"/>
            </svg>
            <span>Converter em Cliente</span>
          </Button>
        )}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span className="desktop-only" style={{ fontSize: 11, color: 'var(--text3)' }}>
          <kbd>Ctrl</kbd>+<kbd>S</kbd>
        </span>
        <Button type="button" variant="secondary" onClick={onClose}>
          Cancelar
        </Button>
        <Button
          type="button"
          variant="primary"
          disabled={isSaving}
          onClick={handleSave}
        >
          {isSaving ? 'Salvando...' : (item ? 'Salvar Alterações' : 'Salvar Lead')}
        </Button>
      </div>
    </div>
  );

  return (
    <Drawer
      isOpen={isOpen}
      onClose={onClose}
      title={titleNode}
      description={item ? 'Carteira comercial / Leads' : 'Cadastre uma nova oportunidade comercial'}
      footer={footerNode}
      width={760}
      className="lead-drawer"
      navigation={
        <nav className="lead-drawer-nav" aria-label="Seções do lead">
          {[["resumo", "01", "Resumo"], ["qualificacao", "02", "Qualificação"], ["historico", "03", "Histórico"]].map(([id, number, label]) => (
            <button type="button" key={id} id={`lead-nav-${id}`} aria-controls={`lead-panel-${id}`}
              aria-current={activeSection === id ? 'step' : undefined}
              onClick={() => {
                setActiveSection(id);
                identityRef.current?.parentElement.scrollTo({ top: 0 });
              }}>
              <span>{number}</span>{label}
            </button>
          ))}
        </nav>
      }
    >
      <div ref={identityRef} className="lead-drawer-identity">
        <span className="lead-drawer-avatar" aria-hidden="true">{(f.nome || 'Novo lead').split(' ').filter(Boolean).slice(0, 2).map(n => n[0]).join('').toUpperCase()}</span>
        <div><span className="lead-drawer-eyebrow">{item ? 'Oportunidade comercial' : 'Novo cadastro'}</span>
          <h3>{f.nome || 'Nome / Empresa'}</h3>
          <p>{[f.nicho, f.cidade].filter(Boolean).join(' • ') || 'Complete os dados abaixo'}</p>
        </div>
        <Badge status={f.status} />
      </div>
      <form id="lead-drawer-form" onSubmit={handleSave}>
        {/* ─── SEÇÃO 1: RESUMO ───────────────────────────────────────────── */}
        <section className="lead-drawer-section" id="lead-panel-resumo" aria-labelledby="lead-nav-resumo" hidden={activeSection !== 'resumo'}>
          <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--accent)', marginBottom: 12 }}>
            Cadastro e contato
          </div>
          <div className="form-grid lead-drawer-card">
            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Nome / Empresa *</label>
                <input className="form-input" aria-label="Nome / Empresa" value={f.nome} onChange={u('nome')} />
              </div>
              <div className="form-group">
                <label className="form-label" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span>Telefone / WhatsApp</span>
                  {f.telefone && f.telefone.replace(/\D/g, '').length >= 8 && (
                    <a
                      href={getWaLink(f.telefone)}
                      target="_blank"
                      rel="noreferrer"
                      style={{ color: 'var(--green)', fontSize: 11, fontWeight: 600, textDecoration: 'none' }}
                    >
                      Abrir WhatsApp ↗
                    </a>
                  )}
                </label>
                <input className="form-input" aria-label="Telefone / WhatsApp" value={f.telefone} onChange={u('telefone')} />
              </div>
            </div>

            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Status</label>
                <CustomSelect variant="form" ariaLabel="Status" value={f.status} onChange={u('status')}>
                  {LEAD_STATUSES.map(s => <option key={s}>{s}</option>)}
                </CustomSelect>
              </div>
              <div className="form-group">
                <label className="form-label" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span>Nicho</span>
                  <button type="button"
                    className="lead-drawer-text-action"
                    style={{ fontSize: 10, color: 'var(--text3)', cursor: 'pointer' }}
                    onClick={() => navTo('cfg-negocios')}
                  >
                    Gerenciar →
                  </button>
                </label>
                <CustomSelect variant="form" ariaLabel="Nicho" value={f.nicho} onChange={u('nicho')}>
                  {configData.nichos.map(n => <option key={n}>{n}</option>)}
                </CustomSelect>
              </div>
            </div>

            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Cidade / Localização</label>
                <input
                  className="form-input"
                  aria-label="Cidade / Localização" value={f.cidade}
                  onChange={u('cidade')}
                  list="existing-cidades-drawer"
                  placeholder="Ex: Curitiba - PR"
                />
                <datalist id="existing-cidades-drawer">
                  {existingCidades.map(c => <option key={c} value={c} />)}
                </datalist>
              </div>
              <div className="form-group">
                <label className="form-label">Lote</label>
                <input
                  className="form-input"
                  aria-label="Lote" value={f.lote}
                  onChange={u('lote')}
                  list="existing-lotes-drawer"
                  placeholder="Ex: Curitiba 11/2026"
                />
                <datalist id="existing-lotes-drawer">
                  {existingLotes.map(l => <option key={l} value={l} />)}
                </datalist>
              </div>
            </div>

            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span>Site / Instagram</span>
                  {f.site && (f.site.includes('.') || f.site.startsWith('http')) && (
                    <a
                      href={f.site.trim().startsWith('http') ? f.site.trim() : `https://${f.site.trim()}`}
                      target="_blank"
                      rel="noreferrer"
                      style={{ color: 'var(--accent)', fontSize: 11, fontWeight: 600, textDecoration: 'none' }}
                    >
                      Abrir ↗
                    </a>
                  )}
                </label>
                <input className="form-input" aria-label="Site / Instagram" value={f.site} onChange={u('site')} />
              </div>
              <div className="form-group">
                <label className="form-label">E-mail</label>
                <input className="form-input" type="email" aria-label="E-mail" value={f.email} onChange={u('email')} placeholder="email@exemplo.com" />
              </div>
            </div>

          </div>
          <details className="lead-drawer-card lead-drawer-details">
            <summary>Informações complementares <span>Valor, origem e acompanhamento</span></summary>
            <div className="form-grid">
            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Valor Estimado (R$)</label>
                <input className="form-input" type="number" min="0" aria-label="Valor Estimado (R$)" value={f.valorEstimado} onChange={u('valorEstimado')} placeholder="0,00" />
              </div>
              <div className="form-group">
                <label className="form-label">Origem do Lead</label>
                <CustomSelect variant="form" ariaLabel="Origem do Lead" value={f.origem} onChange={u('origem')} placeholder="-- Selecione --">
                  {['', 'Instagram', 'Google', 'Indicação', 'LinkedIn', 'WhatsApp', 'Facebook', 'Site', 'Evento', 'Outro'].map(o => <option key={o} value={o}>{o || '-- Selecione --'}</option>)}
                </CustomSelect>
              </div>
            </div>

            <div className="form-grid form-grid-2">
              <div className="form-group">
                <label className="form-label">Último Contato</label>
                <input className="form-input" type="date" aria-label="Último Contato" value={f.ultimoContato} onChange={u('ultimoContato')} />
              </div>
              <div className="form-group">
                <label className="form-label">Próximo Contato</label>
                <input className="form-input" type="date" aria-label="Próximo Contato" value={f.proximoContato} onChange={u('proximoContato')} />
              </div>
            </div>
          </div>
          </details>
          <div className="lead-drawer-card lead-drawer-notes">
          {/* Observações */}
          <div className="form-group" style={{ marginBottom: 0 }}>
            <label className="form-label">Observações de Qualificação</label>
            <textarea
              className="form-textarea"
              style={{ minHeight: 75 }}
              placeholder="Anotações sobre problemas no site, oportunidades ou pontos fortes..."
              aria-label="Observações de Qualificação" value={f.observacoes}
              onChange={u('observacoes')}
            />
          </div>

          </div>
        </section>

        {/* ─── SEÇÃO 2: QUALIFICAÇÃO ────────────────────────────────────── */}
        <section className="lead-drawer-section lead-drawer-card" id="lead-panel-qualificacao" aria-labelledby="lead-nav-qualificacao" hidden={activeSection !== 'qualificacao'}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--accent)' }}>
                Análise e presença digital
              </div>
              <span
                title="Chamadas de IA utilizadas hoje pelo seu usuário"
                style={{
                  fontSize: 10,
                  fontWeight: 600,
                  padding: '2px 8px',
                  borderRadius: 99,
                  border: `1px solid ${(aiUsage?.used || 0) >= (aiUsage?.limit || 60) ? 'rgba(239,68,68,0.4)' : 'var(--border)'}`,
                  background: (aiUsage?.used || 0) >= (aiUsage?.limit || 60) ? 'var(--red-bg)' : 'var(--bg2)',
                  color: (aiUsage?.used || 0) >= (aiUsage?.limit || 60) ? 'var(--red)' : (aiUsage?.used || 0) >= (aiUsage?.limit || 60) * 0.8 ? 'var(--amber)' : 'var(--text3)',
                }}
              >
                IA hoje: {aiUsage?.used ?? 0}/{aiUsage?.limit ?? 60}
              </span>
              <Button size="sm" variant="ghost" onClick={refreshAiUsage} title="Consultar utilização atual de IA">Atualizar cota</Button>
            </div>
            {item?.id && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
                <button
                  type="button"
                  className="btn btn-sm btn-secondary"
                  onClick={handleSinglePreQual}
                  disabled={isPrequaling}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 5, fontSize: 11,
                    background: 'var(--color-accent)',
                    color: 'var(--on-accent)', border: 'none',
                  }}
                >
                  {isPrequaling ? 'Analisando...' : (prequalData ? 'Re-qualificar Site' : 'Qualificar Agora')}
                </button>
                <button
                  type="button"
                  className="btn btn-sm btn-secondary"
                  onClick={handleQualifyWithAi}
                  disabled={isAiQualifying}
                  title="Analisar dados e print com IA para sugerir chips, resumo e prioridade"
                  style={{
                    display: 'flex', alignItems: 'center', gap: 5, fontSize: 11,
                    borderColor: 'rgba(16,185,129,0.45)',
                    background: isAiQualifying ? 'var(--bg2)' : 'rgba(16,185,129,0.14)',
                    color: 'var(--green)',
                    fontWeight: 600,
                  }}
                >
                  <span>✨ {isAiQualifying ? 'Analisando com IA...' : (item?.aiQualificacao ? 'Refazer IA' : 'Qualificar com IA')}</span>
                </button>
              </div>
            )}
          </div>

          {aiError && (
            <div style={{ background: 'var(--red-bg)', border: '1px solid rgba(239,68,68,0.35)', borderRadius: 8, padding: '8px 12px', fontSize: 12, color: 'var(--red)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8 }}>
              <span>{aiError}</span>
              <button type="button" onClick={() => setAiError(null)} style={{ background: 'transparent', border: 'none', color: 'var(--red)', cursor: 'pointer', fontSize: 14 }}>×</button>
            </div>
          )}

          {/* Sugestão da IA aguardando confirmação humana */}
          {aiDraft && (
            <div style={{ background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.35)', borderRadius: 8, padding: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--green)' }}>
                  ✨ Sugestão da IA (confirme ou ajuste os chips abaixo)
                </span>
                <span
                  style={{
                    fontSize: 10,
                    fontWeight: 700,
                    textTransform: 'uppercase',
                    padding: '2px 8px',
                    borderRadius: 99,
                    background: aiDraft.prioridade === 'alta' ? 'var(--red-bg)' : aiDraft.prioridade === 'media' ? 'rgba(245,158,11,0.15)' : 'var(--bg2)',
                    color: aiDraft.prioridade === 'alta' ? 'var(--red)' : aiDraft.prioridade === 'media' ? 'var(--amber)' : 'var(--text2)',
                  }}
                >
                  Prioridade {aiDraft.prioridade}
                </span>
              </div>
              <div style={{ fontSize: 12, color: 'var(--text)', lineHeight: 1.45 }}>
                {aiDraft.resumo}
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <button type="button" className="btn btn-sm btn-secondary" onClick={() => setAiDraft(null)}>
                  Descartar
                </button>
                <button
                  type="button"
                  className="btn btn-sm btn-primary"
                  style={{ background: 'var(--color-accent)', borderColor: 'var(--color-accent)', color: 'var(--on-accent)' }}
                  onClick={handleConfirmAiDraft}
                >
                  Confirmar e Salvar
                </button>
              </div>
            </div>
          )}

          {/* Qualificação de IA já salva no lead */}
          {!aiDraft && item?.aiQualificacao?.resumo && (
            <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8, padding: '8px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--text3)', textTransform: 'uppercase' }}>
                  ✨ Resumo IA
                </span>
                {item.aiQualificacao.prioridade && (
                  <span style={{ fontSize: 10, fontWeight: 700, color: item.aiQualificacao.prioridade === 'alta' ? 'var(--red)' : item.aiQualificacao.prioridade === 'media' ? 'var(--amber)' : 'var(--text3)', textTransform: 'uppercase' }}>
                    Prioridade {item.aiQualificacao.prioridade}
                  </span>
                )}
              </div>
              <div style={{ fontSize: 12, color: 'var(--text2)', lineHeight: 1.4 }}>
                {item.aiQualificacao.resumo}
              </div>
            </div>
          )}

          {/* Chips de Qualificação Rápida + Bot no WhatsApp */}
          <div>
            <label className="form-label" style={{ fontSize: 11 }}>Diagnóstico Rápido</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {QUAL_CHIPS.map(chip => {
                const active = (f.qualChips || []).includes(chip.id);
                return (
                  <button
                    key={chip.id}
                    aria-pressed={active}
                    type="button"
                    onClick={() => setF(p => {
                      const curr = Array.isArray(p.qualChips) ? p.qualChips : [];
                      return {
                        ...p,
                        qualChips: curr.includes(chip.id) ? curr.filter(c => c !== chip.id) : [...curr, chip.id],
                      };
                    })}
                    style={{
                      fontSize: 11,
                      padding: '4px 10px',
                      borderRadius: 99,
                      cursor: 'pointer',
                      fontWeight: active ? 600 : 500,
                      border: `1px solid ${active ? 'var(--accent)' : 'var(--border)'}`,
                      background: active ? 'rgba(99,102,241,0.16)' : 'var(--bg2)',
                      color: active ? 'var(--accent)' : 'var(--text2)',
                    }}
                  >
                    {active ? '✓ ' : '+ '}{chip.label}
                  </button>
                );
              })}
              <button
                type="button"
                aria-pressed={f.botBarreira}
                onClick={() => setF(p => ({ ...p, botBarreira: !p.botBarreira }))}
                style={{
                  fontSize: 11,
                  padding: '4px 10px',
                  borderRadius: 99,
                  cursor: 'pointer',
                  fontWeight: f.botBarreira ? 600 : 500,
                  border: `1px solid ${f.botBarreira ? 'rgba(245,158,11,0.5)' : 'var(--border)'}`,
                  background: f.botBarreira ? 'rgba(245,158,11,0.14)' : 'var(--bg2)',
                  color: f.botBarreira ? 'var(--amber)' : 'var(--text2)',
                }}
              >
                🤖 Bot no WhatsApp {f.botBarreira ? '✓' : ''}
              </button>
            </div>
          </div>

          {/* Log inline da pré-qualificação */}
          {singleProgress && (
            <div className={"prequal-single-log prequal-single-log--" + singleProgress.status}>
              <div className="prequal-single-log-header">
                <span>
                  {singleProgress.status === 'processing' && 'Analisando site e redes...'}
                  {singleProgress.status === 'success'    && 'Qualificação concluída!'}
                  {singleProgress.status === 'error'      && (singleProgress.message || 'Erro na qualificação')}
                  {singleProgress.status === 'skipped'    && (singleProgress.message || 'Lead ignorado')}
                </span>
                {(singleProgress.status === 'error' || singleProgress.status === 'skipped') && (
                  <button type="button" className="prequal-single-log-close" onClick={() => setSingleProgress(null)}>×</button>
                )}
              </div>
              {Object.keys(singleProgress.steps || {}).length > 0 && (
                <div className="prequal-single-log-steps">
                  {STEP_ORDER_DRAWER.map(key => {
                    const step = singleProgress.steps[key];
                    if (!step) return null;
                    return (
                      <div key={key} className={"prequal-single-step prequal-single-step--" + step.status}>
                        <span className="prequal-step-label">{STEP_LABELS_DRAWER[key]}: {step.status}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {!prequalData && !singleProgress && (
            <p className="lead-drawer-empty">Nenhuma análise técnica registrada. {item?.id ? 'Use Qualificar Agora para iniciar a análise.' : 'Salve o lead para disponibilizar a análise.'}</p>
          )}
          {/* Notas PageSpeed & Instagram */}
          {prequalData && (prequalData.pagespeed?.mobile != null || prequalData.pagespeed?.desktop != null) && (
            <div className="prequal-speed-row">
              <PageSpeedScore
                label="Mobile"
                value={prequalData.pagespeed.mobile}
                icon={<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>}
              />
              <PageSpeedScore
                label="Desktop"
                value={prequalData.pagespeed.desktop}
                icon={<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><path d="M8 21h8"/><path d="M12 17v4"/></svg>}
              />
            </div>
          )}

          {prequalData?.instagramData && (prequalData.instagramData.followers != null || prequalData.instagramData.bio) && (
            <div className="prequal-insta-box">
              {prequalData.instagramData.followers != null && (
                <div className="prequal-insta-stat">
                  <span className="prequal-insta-val">{prequalData.instagramData.followers.toLocaleString('pt-BR')}</span>
                  <span className="prequal-insta-lbl">Seguidores no Instagram</span>
                </div>
              )}
              {prequalData.instagramData.bio && (
                <div className="prequal-insta-bio" style={{ marginTop: 4 }}>{prequalData.instagramData.bio}</div>
              )}
            </div>
          )}

          {/* Print com Lightbox e Colar Ctrl+V */}
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
              <label className="form-label" style={{ marginBottom: 0, fontSize: 11 }}>
                Print / Screenshot do Site
                {item?.screenshotManual && (
                  <span style={{ marginLeft: 6, fontSize: 10, color: 'var(--accent)', fontWeight: 600 }}>• Manual</span>
                )}
                {isUploadingPrint && (
                  <span style={{ marginLeft: 8, fontSize: 10, color: 'var(--amber)' }}>Enviando print...</span>
                )}
              </label>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                {item?.id && (
                  <span style={{ fontSize: 10, color: 'var(--text3)' }}>
                    Cole com <kbd>Ctrl</kbd>+<kbd>V</kbd>
                  </span>
                )}
                {prequalData?.screenshotUrl && item?.id && (
                  <button
                    type="button"
                    className="btn btn-sm btn-secondary"
                    style={{ fontSize: 10, padding: '2px 8px', color: 'var(--red)' }}
                    onClick={() => deleteLeadScreenshot(item.id)}
                  >
                    Remover print
                  </button>
                )}
              </div>
            </div>
            {screenshotUrlWithCacheBuster ? (
              <button
                type="button"
                aria-label="Ampliar screenshot"
                className="prequal-screenshot-wrap"
                onClick={() => { setLightboxNotes(f.observacoes || ''); setLightboxOpen(true); }}
                title="Clique para ampliar no Lightbox (ou cole outro print com Ctrl+V para substituir)"
                style={{ maxHeight: 220, overflow: 'hidden', borderRadius: 8, cursor: 'pointer', border: '1px solid var(--border)' }}
              >
                <img src={screenshotUrlWithCacheBuster} alt="Screenshot do site" className="prequal-screenshot-img" />
              </button>
            ) : (
              <div
                className="prequal-screenshot-placeholder"
                style={{ padding: '18px 12px', borderRadius: 8, border: '1px dashed var(--border)', textAlign: 'center', color: 'var(--text3)', fontSize: 12 }}
              >
                {item?.id
                  ? 'Nenhum print capturado. Pressione Ctrl+V para colar um print da área de transferência (máx. 1600px).'
                  : 'Salve o lead primeiro para poder colar um print com Ctrl+V.'}
              </div>
            )}
          </div>


        </section>

        {/* ─── SEÇÃO 3: HISTÓRICO ───────────────────────────────────────── */}
        <section className="lead-drawer-section lead-drawer-card" id="lead-panel-historico" aria-labelledby="lead-nav-historico" hidden={activeSection !== 'historico'}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 6 }}>
            <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--accent)' }}>
              Histórico de interações
            </div>
            <button
              type="button"
              className="btn btn-sm btn-secondary"
              style={{
                fontSize: 11,
                padding: '3px 10px',
                color: (f.interacoes || []).some(i => i.tipo === 'resposta_recebida') ? 'var(--green)' : 'var(--text2)',
                borderColor: (f.interacoes || []).some(i => i.tipo === 'resposta_recebida') ? 'rgba(16,185,129,0.4)' : undefined,
              }}
              onClick={() => {
                const nowISO = new Date().toISOString();
                const newInt = { data: nowISO, texto: 'Resposta recebida', tipo: 'resposta_recebida', criadoEm: nowISO };
                setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
              }}
            >
              ✓ Marcar resposta
            </button>
          </div>

          {(f.interacoes || []).length === 0 ? (
            <div style={{ fontSize: 12, color: 'var(--text3)', fontStyle: 'italic' }}>Nenhuma interação registrada.</div>
          ) : (
            <div className="lead-drawer-timeline">
              {(f.interacoes || []).map((int, i) => ({ int, i })).sort((a, b) => (Date.parse(b.int.data || b.int.criadoEm) || 0) - (Date.parse(a.int.data || a.int.criadoEm) || 0)).map(({ int, i }) => (
                <div className="lead-drawer-event" key={i} style={{ fontSize: 12, display: 'flex', gap: 8, paddingBottom: 4, borderBottom: '1px solid var(--border2)', alignItems: 'flex-start' }}>
                  <span style={{ color: 'var(--text3)', whiteSpace: 'nowrap', flexShrink: 0 }}>
                    {(int.data || int.criadoEm || '').split('T')[0].split('-').reverse().join('/')}
                    <small>{(int.data || int.criadoEm || '').includes('T') ? new Date(int.data || int.criadoEm).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : ''}</small>
                  </span>
                  {int.tipo && int.tipo !== 'outro' && (
                    <span style={{ fontSize: 10, background: 'var(--bg4)', border: '1px solid var(--border)', borderRadius: 4, padding: '1px 5px', color: 'var(--text3)', flexShrink: 0, whiteSpace: 'nowrap' }}>
                      {INTERACAO_TIPO_LABELS[int.tipo] || int.tipo}
                    </span>
                  )}
                  <span className="lead-drawer-event-text" style={{ color: 'var(--text)', flex: 1 }}>{int.texto}</span>
                  <button
                    type="button"
                    className="row-btn del"
                    aria-label="Remover interação"
                    style={{ marginLeft: 'auto', padding: 0, flexShrink: 0 }}
                    onClick={() => setF(p => ({ ...p, interacoes: p.interacoes.filter((_, idx) => idx !== i) }))}
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          )}

          <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
            {INTERACAO_TIPOS.map(t => (
              <button
                key={t}
                type="button"
                className={`btn btn-sm ${intTipo === t ? 'btn-primary' : 'btn-secondary'}`}
                style={{ fontSize: 10, padding: '3px 8px' }}
                onClick={() => setIntTipo(t)}
              >
                {INTERACAO_TIPO_LABELS[t] || t}
              </button>
            ))}
          </div>

          <div style={{ display: 'flex', gap: 6 }}>
            <input
              className="form-input"
              style={{ flex: 1, fontSize: 12, padding: '6px 8px' }}
              placeholder="Adicionar interação (Enter para incluir)..."
              value={intText}
              onChange={e => setIntText(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  if (!intText) return;
                  const nowISO = new Date().toISOString();
                  const newInt = { data: nowISO, texto: intText, tipo: intTipo, criadoEm: nowISO };
                  setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
                  setIntText('');
                }
              }}
            />
            <button
              type="button"
              className="btn btn-sm btn-secondary"
              onClick={() => {
                if (!intText) return;
                const nowISO = new Date().toISOString();
                const newInt = { data: nowISO, texto: intText, tipo: intTipo, criadoEm: nowISO };
                setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
                setIntText('');
              }}
            >
              Adicionar
            </button>
          </div>
          {/* T4.3: Gerar mensagem com IA ou Modelo Offline */}
          <div style={{ borderTop: '1px solid var(--border)', paddingTop: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 6 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '0.04em' }}>
                  Mensagem de Abordagem
                </span>
                <button type="button" className="lead-drawer-text-action"
                  style={{ fontSize: 10, color: 'var(--text3)', cursor: 'pointer' }}
                  onClick={() => navTo('cfg-sistema')}
                  title="Personalizar tom de voz e instruções da IA em Configurações > Sistema"
                >
                  Instruções da IA →
                </button>
              </div>
              <div style={{ display: 'inline-flex', gap: 4 }}>
                <button
                  type="button"
                  className={`btn btn-sm ${msgTipo === 'abordagem_inicial' ? 'btn-primary' : 'btn-secondary'}`}
                  style={{ fontSize: 10, padding: '2px 8px' }}
                  onClick={() => setMsgTipo('abordagem_inicial')}
                >
                  Abordagem inicial
                </button>
                <button
                  type="button"
                  className={`btn btn-sm ${msgTipo === 'follow_up' ? 'btn-primary' : 'btn-secondary'}`}
                  style={{ fontSize: 10, padding: '2px 8px' }}
                  onClick={() => setMsgTipo('follow_up')}
                >
                  Follow-up
                </button>
              </div>
            </div>

            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              <button
                type="button"
                className="btn btn-sm btn-secondary"
                onClick={handleGenerateAiMessage}
                disabled={isGeneratingMsg}
                style={{
                  fontSize: 11,
                  borderColor: 'rgba(99,102,241,0.45)',
                  background: isGeneratingMsg ? 'var(--bg2)' : 'rgba(99,102,241,0.14)',
                  color: 'var(--accent)',
                  fontWeight: 600,
                }}
              >
                ✨ {isGeneratingMsg ? 'Gerando mensagem...' : 'Gerar mensagem com IA'}
              </button>
              <button
                type="button"
                className="btn btn-sm btn-secondary"
                onClick={handleGenerateOfflineMessage}
                style={{ fontSize: 11 }}
                title="Gerar mensagem usando o modelo local sem consumir cota de IA"
              >
                ⚡ Modelo rápido (offline)
              </button>
            </div>

            {msgError && (
              <div style={{ background: 'var(--red-bg)', border: '1px solid rgba(239,68,68,0.35)', borderRadius: 8, padding: '6px 10px', fontSize: 11, color: 'var(--red)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8 }}>
                <span>{msgError}</span>
                <button type="button" onClick={() => setMsgError(null)} style={{ background: 'transparent', border: 'none', color: 'var(--red)', cursor: 'pointer', fontSize: 13 }}>×</button>
              </div>
            )}

            {msgDraft !== '' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                <textarea
                  className="form-textarea"
                  style={{ minHeight: 88, fontSize: 12 }}
                  value={msgDraft}
                  onChange={e => setMsgDraft(e.target.value)}
                  placeholder="Edite a mensagem antes de copiar ou abrir no WhatsApp..."
                />
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 6, flexWrap: 'wrap' }}>
                  <button
                    type="button"
                    className="btn btn-sm btn-secondary"
                    onClick={handleCopyMessage}
                    style={{ fontSize: 11 }}
                  >
                    📋 Copiar
                  </button>
                  <button
                    type="button"
                    className="btn btn-sm btn-primary"
                    onClick={handleOpenWhatsAppWithText}
                    style={{
                      fontSize: 11,
                      background: 'var(--color-accent)',
                      borderColor: 'var(--color-accent)',
                      color: 'var(--on-accent)',
                      fontWeight: 600,
                    }}
                  >
                    💬 Abrir WhatsApp com o texto ↗
                  </button>
                </div>
              </div>
            )}
          </div>
        </section>
      </form>

      {/* Lightbox para o print */}
      {lightboxOpen && screenshotUrlWithCacheBuster && (
        <Modal isOpen={lightboxOpen} onClose={() => setLightboxOpen(false)} title="Screenshot do site" description={item?.nome || 'Lead'} className="lead-lightbox" size="lg">
          <div className="lead-lightbox-layout">
          <div className="lightbox-split-left">
            <div className="lightbox-split-img-container">
              <img src={screenshotUrlWithCacheBuster} alt="Screenshot do site" className="lightbox-split-img" />
            </div>
          </div>
          <div className="lightbox-split-right" onClick={e => e.stopPropagation()}>
            <div className="lightbox-split-header">
              <h3>Qualificação do Lead</h3>
              <p className="lead-name">{item?.nome || 'Lead'}</p>
            </div>
            <div className="lightbox-split-body">
              <label className="lightbox-sidebar-label">Anotações / Pontos de Qualificação</label>
              <textarea
                className="lightbox-sidebar-textarea"
                aria-label="Anotações do screenshot"
                placeholder="Escreva os pontos de qualificação observados no site..."
                value={lightboxNotes}
                onChange={(e) => setLightboxNotes(e.target.value)}
              />
            </div>
            <div className="lightbox-split-footer">
              <button type="button" className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setLightboxOpen(false)}>Fechar</button>
              <button
                type="button"
                className="btn btn-primary"
                style={{ flex: 1 }}
                onClick={async () => {
                  setF(prev => ({ ...prev, observacoes: lightboxNotes }));
                  if (item?.id) await saveLeadNotes(item.id, lightboxNotes);
                  setLightboxOpen(false);
                }}
              >
                Salvar
              </button>
            </div>
          </div>
          </div>
        </Modal>
      )}
    </Drawer>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useDash } from '../../store/useStore';
import { INTERACAO_TIPO_LABELS, INTERACAO_TIPOS, LEAD_STATUSES, QUAL_CHIPS } from '../../utils/crmAnalyticsUtils';
import CustomSelect from '../CustomSelect';
import { navToConfigTab } from './shared';

export function PageSpeedScore({ label, value, icon }) {
  if (value == null) return null;
  const n = Math.round(value);
  const color = n >= 90 ? 'var(--green)' : n >= 50 ? 'var(--amber)' : 'var(--red)';
  const bg = n >= 90 ? 'var(--green-bg)' : n >= 50 ? 'rgba(245,158,11,.1)' : 'var(--red-bg)';
  const label2 = n >= 90 ? 'Bom' : n >= 50 ? 'Médio' : 'Ruim';
  return (
    <div className="prequal-speed-card" style={{ border: `1px solid ${color}40`, background: bg }}>
      <span style={{ fontSize: 11 }}>{icon}</span>
      <div className="prequal-speed-score" style={{ color }}>{n}</div>
      <div className="prequal-speed-label">{label}</div>
      <div className="prequal-speed-grade" style={{ color, background: color + '22', borderRadius: 4, padding: '1px 6px', fontSize: 10, fontWeight: 700 }}>{label2}</div>
    </div>
  );
}

export default function LeadForm({ item }) {
  const data = useDash(s => s.data);
  const configData = useDash(s => s.configData);
  const saveLead = useDash(s => s.saveLead);
  const saveLeadNotes = useDash(s => s.saveLeadNotes);
  const closeModal = useDash(s => s.closeModal);
  const goTo = useDash(s => s.goTo);
  const setConfigTab = useDash(s => s.setConfigTab);
  const runPreQualification = useDash(s => s.runPreQualification);
  const deleteLeadScreenshot = useDash(s => s.deleteLeadScreenshot);

  const navTo = (tab) => navToConfigTab(closeModal, setConfigTab, goTo, tab);

  const existingCidades = useMemo(() => {
    const set = new Set();
    (data?.leads || []).forEach(l => {
      if (l.cidade && l.cidade.trim()) set.add(l.cidade.trim());
    });
    return Array.from(set).sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [data?.leads]);

  const existingLotes = useMemo(() => {
    const set = new Set();
    (data?.leads || []).forEach(l => {
      if (l.lote && l.lote.trim()) set.add(l.lote.trim());
    });
    return Array.from(set).sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [data?.leads]);

  const [intText, setIntText] = useState('');
  const [intTipo, setIntTipo] = useState('outro');
  const [f, setF] = useState({
    nome: item?.nome || '', telefone: item?.telefone || '',
    cidade: item?.cidade || '',
    lote: item?.lote || '',
    email: item?.email || '', origem: item?.origem || '',
    valorEstimado: item?.valorEstimado || '', proximoContato: item?.proximoContato || '',
    nicho: item?.nicho || configData.nichos[0] || '',
    status: item?.status || 'Novo', site: item?.site || '', observacoes: item?.observacoes || '',
    interacoes: item?.interacoes || [],
    botBarreira: !!item?.botBarreira,
    qualChips: Array.isArray(item?.qualChips) ? item.qualChips : [],
  });

  const u = (k) => (e) => setF(p => ({ ...p, [k]: e.target.value }));

  const [isPrequaling, setIsPrequaling] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxNotes, setLightboxNotes] = useState('');
  // singleProgress: null | { status: 'processing'|'success'|'error'|'skipped', message?: string }
  const [singleProgress, setSingleProgress] = useState(null);
  const prequalData = item?.prequalData || null;
  const screenshotUrlWithCacheBuster = prequalData?.screenshotUrl
    ? `${prequalData.screenshotUrl}${prequalData.screenshotUrl.includes('?') ? '&' : '?'}t=${prequalData.prequalizedAt ? new Date(prequalData.prequalizedAt).getTime() : Date.now()}`
    : null;

  const STEP_ORDER_MODAL = ['pagespeed', 'instagram', 'screenshot'];
  const STEP_LABELS_MODAL = { pagespeed: 'PageSpeed', instagram: 'Instagram', screenshot: 'Screenshot' };

  const handleSinglePreQual = () => {
    if (!item?.id || isPrequaling) return;
    setIsPrequaling(true);
    setSingleProgress({ status: 'processing', steps: {}, message: null });

    const onProgress = (event) => {
      setSingleProgress(prev => {
        if (!prev) return prev;
        if (event.type === 'step') {
          return {
            ...prev,
            steps: {
              ...prev.steps,
              [event.step]: { status: event.status, count: event.count, mobile: event.mobile, desktop: event.desktop, followers: event.followers, error: event.error },
            },
          };
        }
        if (event.type === 'success') return { ...prev, status: 'success' };
        if (event.type === 'error')   return { ...prev, status: 'error', message: event.error || 'Erro desconhecido' };
        if (event.type === 'skipped') return { ...prev, status: 'skipped', message: event.reason };
        return prev;
      });
    };

    runPreQualification([item.id], onProgress).finally(() => {
      setIsPrequaling(false);
      // Auto-clear sucesso após 6 segundos; erro/skip ficam até o usuário fechar
      setTimeout(() => {
        setSingleProgress(p => p?.status === 'success' ? null : p);
      }, 6000);
    });
  };

  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (isSaving) return;
    if (!f.nome || !f.nome.trim()) {
      return useDash.getState().toast('O Nome/Empresa é obrigatório.', 'error');
    }
    setIsSaving(true);
    try {
      await saveLead({ ...f, id: item?.id });
    } finally {
      setIsSaving(false);
    }
  };

  // Suporte a atalho de teclado global Ctrl+S / Cmd+S para salvar rapidamente
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
        e.preventDefault();
        handleSave();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [f, item, isSaving]);

  return (
    <form id="lead-modal-form" onSubmit={handleSave} className="lead-modal-form-wrap">
      <div className="lead-modal-scrollable">
        <div className="lead-modal-grid">
        {/* COLUNA ESQUERDA: formulário original */}
        <div className="form-grid" style={{ flex: 1, minWidth: 0 }}>
          <div className="form-grid form-grid-2">
            <div className="form-group"><label className="form-label">Nome / Empresa *</label><input className="form-input" value={f.nome} onChange={u('nome')} /></div>
            <div className="form-group"><label className="form-label">Telefone / WhatsApp</label><input className="form-input" value={f.telefone} onChange={u('telefone')} /></div>
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group">
              <label className="form-label">Cidade / Localização</label>
              <input 
                className="form-input" 
                value={f.cidade} 
                onChange={u('cidade')} 
                list="existing-cidades-lead" 
                placeholder="Ex: São Paulo - SP" 
              />
              <datalist id="existing-cidades-lead">
                {existingCidades.map(c => <option key={c} value={c} />)}
              </datalist>
            </div>
            <div className="form-group"><label className="form-label">Origem do Lead</label>
              <CustomSelect variant="form" value={f.origem} onChange={u('origem')} placeholder="-- Selecione --">
                {['', 'Instagram', 'Google', 'Indicação', 'LinkedIn', 'WhatsApp', 'Facebook', 'Site', 'Evento', 'Outro'].map(o => <option key={o} value={o}>{o || '-- Selecione --'}</option>)}
              </CustomSelect>
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Lote</label>
            <input
              className="form-input"
              value={f.lote}
              onChange={u('lote')}
              list="existing-lotes-lead"
              placeholder="Ex: Curitiba 11/2026"
            />
            <datalist id="existing-lotes-lead">
              {existingLotes.map(l => <option key={l} value={l} />)}
            </datalist>
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group"><label className="form-label">E-mail</label><input className="form-input" type="email" value={f.email} onChange={u('email')} placeholder="email@exemplo.com" /></div>
            <div className="form-group"><label className="form-label">Site / Instagram</label><input className="form-input" value={f.site} onChange={u('site')} /></div>
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group"><label className="form-label">Nicho</label>
              <CustomSelect variant="form" value={f.nicho} onChange={u('nicho')}>
                {configData.nichos.map(n => <option key={n}>{n}</option>)}
              </CustomSelect>
              <div style={{ fontSize: 11, color: 'var(--text3)', marginTop: 4, cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: 4 }} onClick={() => navTo('cfg-negocios')}>
                Gerenciar nichos
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10 }}><path d="M5 12h14M12 5l7 7-7 7"/></svg>
              </div>
            </div>
            <div className="form-group"><label className="form-label">Status</label>
              <CustomSelect variant="form" value={f.status} onChange={u('status')}>
                {LEAD_STATUSES.map(s => <option key={s}>{s}</option>)}
              </CustomSelect>
            </div>
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group"><label className="form-label">Valor Estimado (R$)</label><input className="form-input" type="number" min="0" value={f.valorEstimado} onChange={u('valorEstimado')} placeholder="0,00" /></div>
            <div className="form-group"><label className="form-label">Último Contato</label><input className="form-input" type="date" value={f.ultimoContato} onChange={u('ultimoContato')} /></div>
          </div>
          <div className="form-group"><label className="form-label">Próximo Contato (Agendamento)</label><input className="form-input" type="date" value={f.proximoContato} onChange={u('proximoContato')} /></div>
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6, flexWrap: 'wrap', gap: 6 }}>
              <label className="form-label" style={{ marginBottom: 0 }}>Histórico de Interações</label>
              <div style={{ display: 'flex', gap: 6 }}>
                <button
                  type="button"
                  className="btn btn-sm btn-secondary"
                  style={{
                    fontSize: 11,
                    padding: '3px 8px',
                    color: (f.interacoes || []).some(i => i.tipo === 'resposta_recebida') ? 'var(--green)' : 'var(--text2)',
                    borderColor: (f.interacoes || []).some(i => i.tipo === 'resposta_recebida') ? 'rgba(16,185,129,0.4)' : undefined,
                  }}
                  onClick={() => {
                    const nowISO = new Date().toISOString();
                    const newInt = { data: nowISO, texto: 'Resposta recebida', tipo: 'resposta_recebida', criadoEm: nowISO };
                    setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
                  }}
                >
                  ✓ Marcar resposta
                </button>
                <button
                  type="button"
                  className="btn btn-sm btn-secondary"
                  style={{
                    fontSize: 11,
                    padding: '3px 8px',
                    color: f.botBarreira ? 'var(--amber)' : 'var(--text2)',
                    borderColor: f.botBarreira ? 'rgba(245,158,11,0.4)' : undefined,
                    background: f.botBarreira ? 'rgba(245,158,11,0.12)' : undefined,
                  }}
                  onClick={() => setF(p => ({ ...p, botBarreira: !p.botBarreira }))}
                >
                  🤖 Bot no WhatsApp {f.botBarreira ? '• Ativo' : ''}
                </button>
              </div>
            </div>
            <div style={{ background: 'var(--bg3)', borderRadius: 'var(--radius-sm)', padding: 10, display: 'flex', flexDirection: 'column', gap: 8, border: '1px solid var(--border)' }}>
              {(f.interacoes || []).length === 0 ? (
                <div style={{ fontSize: 12, color: 'var(--text3)', fontStyle: 'italic' }}>Nenhuma interação registrada.</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6, maxHeight: 120, overflowY: 'auto' }}>
                  {(f.interacoes || []).map((int, i) => (
                    <div key={i} style={{ fontSize: 12, display: 'flex', gap: 8, paddingBottom: 4, borderBottom: '1px solid var(--border2)', alignItems: 'flex-start' }}>
                      <span style={{ color: 'var(--text3)', whiteSpace: 'nowrap', flexShrink: 0 }}>{(int.data || int.criadoEm || '').split('T')[0].split('-').reverse().join('/')}</span>
                      {int.tipo && int.tipo !== 'outro' && (
                        <span style={{ fontSize: 10, background: 'var(--bg4)', border: '1px solid var(--border)', borderRadius: 4, padding: '1px 5px', color: 'var(--text3)', flexShrink: 0, whiteSpace: 'nowrap' }}>
                          {INTERACAO_TIPO_LABELS[int.tipo] || int.tipo}
                        </span>
                      )}
                      <span style={{ color: 'var(--text)', flex: 1 }}>{int.texto}</span>
                      <button type="button" className="row-btn del" style={{ marginLeft: 'auto', padding: 0, flexShrink: 0 }} onClick={() => setF(p => ({ ...p, interacoes: p.interacoes.filter((_, idx) => idx !== i) }))}>×</button>
                    </div>
                  ))}
                </div>
              )}
              {/* Tags rápidas de tipo de interação */}
              <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginTop: 4 }}>
                {INTERACAO_TIPOS.map(t => (
                  <button
                    key={t}
                    type="button"
                    className={`btn btn-sm ${intTipo === t ? 'btn-primary' : 'btn-secondary'}`}
                    style={{ fontSize: 10, padding: '3px 8px' }}
                    onClick={() => setIntTipo(t)}
                  >
                    {INTERACAO_TIPO_LABELS[t] || t}
                  </button>
                ))}
              </div>
              <div style={{ display: 'flex', gap: 6, marginTop: 2 }}>
                <input
                  className="form-input"
                  style={{ flex: 1, fontSize: 12, padding: '6px 8px' }}
                  placeholder="Ex: Reunião de alinhamento..."
                  id="lead-int-text"
                  value={intText}
                  onChange={e => setIntText(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      if (!intText) return;
                      const nowISO = new Date().toISOString();
                      const newInt = { data: nowISO, texto: intText, tipo: intTipo, criadoEm: nowISO };
                      setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
                      setIntText('');
                    }
                  }}
                />
                <button
                  type="button"
                  id="lead-int-btn"
                  className="btn btn-sm btn-secondary"
                  onClick={() => {
                    if (!intText) return;
                    const nowISO = new Date().toISOString();
                    const newInt = { data: nowISO, texto: intText, tipo: intTipo, criadoEm: nowISO };
                    setF(p => ({ ...p, interacoes: [...(p.interacoes || []), newInt], ultimoContato: nowISO.split('T')[0] }));
                    setIntText('');
                  }}
                >Adicionar</button>
              </div>
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Chips de Qualificação Rápida</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
              {QUAL_CHIPS.map(chip => {
                const active = (f.qualChips || []).includes(chip.id);
                return (
                  <button
                    key={chip.id}
                    type="button"
                    onClick={() => setF(p => {
                      const curr = Array.isArray(p.qualChips) ? p.qualChips : [];
                      return {
                        ...p,
                        qualChips: curr.includes(chip.id) ? curr.filter(c => c !== chip.id) : [...curr, chip.id],
                      };
                    })}
                    style={{
                      fontSize: 11,
                      padding: '4px 10px',
                      borderRadius: 99,
                      cursor: 'pointer',
                      fontWeight: active ? 600 : 500,
                      border: `1px solid ${active ? 'var(--accent)' : 'var(--border)'}`,
                      background: active ? 'rgba(99,102,241,0.16)' : 'var(--bg3)',
                      color: active ? 'var(--accent)' : 'var(--text2)',
                      transition: 'all 0.15s',
                    }}
                  >
                    {active ? '✓ ' : '+ '}{chip.label}
                  </button>
                );
              })}
            </div>
            <label className="form-label">Qualificação / Observações Gerais</label>
            <textarea className="form-textarea" style={{ minHeight: 60 }} value={f.observacoes} onChange={u('observacoes')} />
          </div>
        </div>

        {/* DIVISOR */}
        <div className="lead-modal-divider" />

        {/* COLUNA DIREITA: painel de Pré-Qualificação */}
        <div className="prequal-panel">
          <div className="prequal-panel-header">
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 15, height: 15, color: '#8b5cf6' }}><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/><path d="M11 8v3l2 2"/></svg>
              <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text)' }}>Pré-Qualificação</span>
            </div>
            {item?.id && (
              <button
                type="button"
                className="btn btn-sm btn-secondary"
                onClick={handleSinglePreQual}
                disabled={isPrequaling}
                style={{
                  display: 'flex', alignItems: 'center', gap: 5, fontSize: 11,
                  background: isPrequaling ? 'var(--bg3)' : 'linear-gradient(135deg, #6366f1, #8b5cf6)',
                  color: '#fff', border: 'none',
                  boxShadow: isPrequaling ? 'none' : '0 1px 8px rgba(99,102,241,.3)',
                }}
              >
                {isPrequaling
                  ? <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 11, height: 11, animation: 'spin 1s linear infinite' }}><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>
                  : <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 11, height: 11 }}><path d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                }
                {isPrequaling ? 'Analisando...' : (prequalData ? 'Re-qualificar' : 'Qualificar Agora')}
              </button>
            )}
          </div>

          {/* Log de progresso inline da re-qualificação */}
          {singleProgress && (
            <div className={"prequal-single-log prequal-single-log--" + singleProgress.status}>
              {/* Cabeçalho do log */}
              <div className="prequal-single-log-header">
                {singleProgress.status === 'processing' && (
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 12, height: 12, animation: 'spin 1s linear infinite', flexShrink: 0 }}>
                    <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
                  </svg>
                )}
                {singleProgress.status === 'success' && (
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 12, height: 12, flexShrink: 0 }}>
                    <path d="M20 6 9 17l-5-5"/>
                  </svg>
                )}
                {(singleProgress.status === 'error' || singleProgress.status === 'skipped') && (
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 12, height: 12, flexShrink: 0 }}>
                    <path d="M18 6 6 18M6 6l12 12"/>
                  </svg>
                )}
                <span>
                  {singleProgress.status === 'processing' && 'Analisando...'}
                  {singleProgress.status === 'success'    && 'Concluído!'}
                  {singleProgress.status === 'error'      && (singleProgress.message || 'Erro na qualificação')}
                  {singleProgress.status === 'skipped'    && (singleProgress.message || 'Lead ignorado')}
                </span>
                {(singleProgress.status === 'error' || singleProgress.status === 'skipped') && (
                  <button type="button" className="prequal-single-log-close" onClick={() => setSingleProgress(null)}>×</button>
                )}
              </div>

              {/* Steps individuais */}
              {Object.keys(singleProgress.steps || {}).length > 0 && (
                <div className="prequal-single-log-steps">
                  {STEP_ORDER_MODAL.map(key => {
                    const step = singleProgress.steps[key];
                    if (!step) return null;
                    const label = STEP_LABELS_MODAL[key];
                    let detail = null;
                    if (step.status === 'done') {
                      if (key === 'pagespeed') {
                        detail = (
                          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                            {step.mobile != null && (
                              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 2 }}>
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10 }}><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>
                                {step.mobile}
                              </span>
                            )}
                            {step.desktop != null && (
                              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 2 }}>
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10 }}><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><path d="M8 21h8"/><path d="M12 17v4"/></svg>
                                {step.desktop}
                              </span>
                            )}
                          </span>
                        );
                      }
                      if (key === 'instagram')  detail = step.followers != null ? (step.followers >= 1000 ? (step.followers/1000).toFixed(1)+'k' : step.followers) + ' seg.' : '';
                      if (key === 'screenshot') detail = 'capturado';
                    }
                    if (step.status === 'error' || step.status === 'skipped') detail = step.error || '';
                    return (
                      <div key={key} className={"prequal-single-step prequal-single-step--" + step.status}>
                        <div className="prequal-step-icon">
                          {step.status === 'running'  && <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10, animation: 'spin 1s linear infinite' }}><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>}
                          {step.status === 'done'     && <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 10, height: 10 }}><path d="M20 6 9 17l-5-5"/></svg>}
                          {step.status === 'error'    && <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 10, height: 10 }}><path d="M18 6 6 18M6 6l12 12"/></svg>}
                          {step.status === 'skipped'  && <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10 }}><path d="M5 12h14"/></svg>}
                        </div>
                        <span className="prequal-step-label">{label}</span>
                        {detail && <span className="prequal-step-detail">{detail}</span>}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {!prequalData ? (
            <div className="prequal-empty">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 40, height: 40, color: 'var(--text3)', marginBottom: 10 }}><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/><path d="M11 8v3l2 2"/></svg>
              <p style={{ margin: 0, fontSize: 13, color: 'var(--text3)', textAlign: 'center', lineHeight: 1.5 }}>
                {item?.id
                  ? 'Nenhuma pré-qualificação ainda.\nClique em "Qualificar Agora" ou selecione na lista.'
                  : 'Salve o lead primeiro para poder pré-qualificá-lo.'}
              </p>
            </div>
          ) : (
            <div className="prequal-content">
              {(prequalData.pagespeed?.mobile != null || prequalData.pagespeed?.desktop != null) && (
                <div className="prequal-section">
                  <div className="prequal-section-label">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 12, height: 12 }}><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg>
                    Google PageSpeed
                  </div>
                  <div className="prequal-speed-row">
                    <PageSpeedScore 
                      label="Mobile" 
                      value={prequalData.pagespeed.mobile} 
                      icon={<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>} 
                    />
                    <PageSpeedScore 
                      label="Desktop" 
                      value={prequalData.pagespeed.desktop} 
                      icon={<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><path d="M8 21h8"/><path d="M12 17v4"/></svg>} 
                    />
                  </div>
                </div>
              )}

              {prequalData.instagramData && (prequalData.instagramData.followers != null || prequalData.instagramData.bio || prequalData.instagramData.lastPost) && (
                <div className="prequal-section">
                  <div className="prequal-section-label">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 12, height: 12 }}><rect x="2" y="2" width="20" height="20" rx="5" ry="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg>
                    Instagram
                  </div>
                  <div className="prequal-insta-box">
                    {prequalData.instagramData.followers != null && (
                      <div className="prequal-insta-stat">
                        <span className="prequal-insta-val">{prequalData.instagramData.followers.toLocaleString('pt-BR')}</span>
                        <span className="prequal-insta-lbl">Seguidores</span>
                      </div>
                    )}
                    {prequalData.instagramData.lastPost && (
                      <div className="prequal-insta-stat">
                        <span className="prequal-insta-val" style={{ fontSize: 12 }}>{new Date(prequalData.instagramData.lastPost).toLocaleDateString('pt-BR')}</span>
                        <span className="prequal-insta-lbl">Último post</span>
                      </div>
                    )}
                    {prequalData.instagram && (
                      <a href={prequalData.instagram} target="_blank" rel="noreferrer" className="prequal-insta-link" style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                        Ver perfil
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 10, height: 10 }}><path d="M5 12h14M12 5l7 7-7 7"/></svg>
                      </a>
                    )}
                  </div>
                  {prequalData.instagramData.bio && (
                    <div className="prequal-insta-bio">{prequalData.instagramData.bio}</div>
                  )}
                  {prequalData.instagramData.bioLink && (
                    <div style={{ marginTop: 8 }}>
                      <a
                        href={prequalData.instagramData.bioLink.startsWith('http') ? prequalData.instagramData.bioLink : `https://${prequalData.instagramData.bioLink}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="prequal-bio-link"
                        title="Link da Bio do Instagram"
                      >
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 11, height: 11 }}><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>
                        {prequalData.instagramData.bioLink.replace(/^https?:\/\/(www\.)?/, '')}
                      </a>
                    </div>
                  )}
                </div>
              )}

              <div className="prequal-section prequal-screenshot-section">
                <div className="prequal-section-label" style={{ marginBottom: 8 }}>
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 12, height: 12 }}><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
                  Screenshot do Site
                  {prequalData.screenshotUrl && (
                    <button
                      type="button"
                      className="btn btn-sm btn-secondary"
                      style={{ marginLeft: 'auto', fontSize: 10, padding: '2px 8px', color: 'var(--red)' }}
                      onClick={() => deleteLeadScreenshot(item.id)}
                      title="Remover screenshot"
                    >Remover</button>
                  )}
                </div>
                {screenshotUrlWithCacheBuster ? (
                  <div className="prequal-screenshot-wrap" onClick={() => { setLightboxNotes(f.observacoes || ''); setLightboxOpen(true); }} title="Clique para ampliar">
                    <img src={screenshotUrlWithCacheBuster} alt="Screenshot do site" className="prequal-screenshot-img" />
                    <div className="prequal-screenshot-zoom-hint">
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 20, height: 20 }}><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/><path d="M11 8v6M8 11h6"/></svg>
                      Ampliar
                    </div>
                  </div>
                ) : (
                  <div className="prequal-screenshot-placeholder">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 30, height: 30, color: 'var(--text3)' }}><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
                    <span style={{ fontSize: 12, color: 'var(--text3)', marginTop: 6 }}>Screenshot não disponível</span>
                  </div>
                )}
              </div>

              {prequalData.prequalizedAt && (
                <div style={{ fontSize: 10, color: 'var(--text3)', textAlign: 'right', marginTop: 4 }}>
                  Qualificado em {new Date(prequalData.prequalizedAt).toLocaleString('pt-BR')}
                </div>
              )}
            </div>
          )}

          {lightboxOpen && screenshotUrlWithCacheBuster && (
            <div className="lightbox-overlay" onClick={() => setLightboxOpen(false)}>
              <div className="lightbox-split-left">
                <div className="lightbox-split-img-container">
                  <img src={screenshotUrlWithCacheBuster} alt="Screenshot do site" className="lightbox-split-img" />
                </div>
              </div>
              <div className="lightbox-split-right" onClick={e => e.stopPropagation()}>
                <div className="lightbox-split-header">
                  <h3>Qualificação do Lead</h3>
                  <p className="lead-name">{item?.nome || 'Lead'}</p>
                  <div style={{ display: 'flex', gap: 8, marginTop: 8, flexWrap: 'wrap' }}>
                    <a href={screenshotUrlWithCacheBuster} target="_blank" rel="noreferrer" className="btn btn-sm btn-secondary" style={{ fontSize: 11, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                      Abrir imagem
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 11, height: 11 }}><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
                    </a>
                    {prequalData?.site && (
                      <a href={prequalData.site.startsWith('http') ? prequalData.site : `https://${prequalData.site}`} target="_blank" rel="noreferrer" className="btn btn-sm btn-primary" style={{ fontSize: 11, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                        Visualizar Site Ao vivo
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 11, height: 11 }}><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
                      </a>
                    )}
                  </div>
                </div>
                <div className="lightbox-split-body">
                  <label className="lightbox-sidebar-label">Anotações / Pontos de Qualificação</label>
                  <textarea
                    className="lightbox-sidebar-textarea"
                    placeholder="Escreva os pontos de qualificação observados no site..."
                    value={lightboxNotes}
                    onChange={(e) => setLightboxNotes(e.target.value)}
                  />
                </div>
                <div className="lightbox-split-footer">
                  <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setLightboxOpen(false)}>Fechar</button>
                  <button className="btn btn-primary" style={{ flex: 1 }} onClick={async () => {
                    setF(prev => ({ ...prev, observacoes: lightboxNotes }));
                    await saveLeadNotes(item.id, lightboxNotes);
                    setLightboxOpen(false);
                  }}>Salvar</button>
                </div>
              </div>
            </div>
          )}
          </div>
        </div>
      </div>

      {/* ── FOOTER FIXO / STICKY - 100% VISÍVEL A TODO MOMENTO ── */}
      <div className="lead-modal-footer">
        <div className="lead-modal-footer-left">
          {item && (
            <button
              type="button"
              className="btn btn-secondary lead-btn-convert"
              style={{ color: 'var(--green)', gap: 6, fontSize: 12 }}
              onClick={() => {
                useDash.getState().convertLeadToCliente(item.id);
              }}
              title="Converter lead em cliente cadastrado"
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
                <path d="M16 21v-2a4 4 0 0 0-4-4H5c-1.1 0-2 .9-2 2v2"/>
                <circle cx="8.5" cy="7" r="4"/>
                <polyline points="17 11 19 13 23 9"/>
              </svg>
              <span>Converter em Cliente</span>
            </button>
          )}
          {item?.status && (
            <span className="lead-modal-status-badge desktop-only">
              Status: <strong>{item.status}</strong>
            </span>
          )}
        </div>

        <div className="lead-modal-footer-right">
          <span className="lead-modal-shortcut-hint desktop-only" title="Pressione Ctrl+S a qualquer momento para salvar">
            <kbd>Ctrl</kbd> + <kbd>S</kbd>
          </span>
          <button type="button" className="btn btn-secondary" onClick={closeModal}>
            Cancelar
          </button>
          <button
            type="submit"
            className="btn btn-primary lead-btn-save"
            disabled={isSaving}
            title="Salvar alterações (Ctrl+S)"
          >
            {isSaving ? (
              <>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14, animation: 'spin 1s linear infinite' }}>
                  <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
                </svg>
                <span>Salvando...</span>
              </>
            ) : (
              <>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 14, height: 14 }}>
                  <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/>
                  <polyline points="17 21 17 13 7 13 7 21"/>
                  <polyline points="7 3 7 8 15 8"/>
                </svg>
                <span>{item ? 'Salvar Alterações' : 'Salvar Lead'}</span>
              </>
            )}
          </button>
        </div>
      </div>
    </form>
  );
}

import { useState } from 'react';
import { useDash } from '../../store/useStore';
import CustomSelect from '../CustomSelect';
import { NumberStepper } from '../shared';
import { navToConfigTab } from './shared';

export default function ProjetoForm({ item }) {
  const data = useDash(s => s.data);
  const configData = useDash(s => s.configData);
  const saveProjeto = useDash(s => s.saveProjeto);
  const closeModal = useDash(s => s.closeModal);
  const goTo = useDash(s => s.goTo);
  const setConfigTab = useDash(s => s.setConfigTab);

  const navTo = (tab) => navToConfigTab(closeModal, setConfigTab, goTo, tab);

  const todayStr = new Date().toISOString().split('T')[0];
  const initialFechadoEm = item
    ? (item.fechadoEm || (typeof item.criadoEm === 'string' && item.criadoEm.includes('-') ? item.criadoEm.split('T')[0] : ''))
    : todayStr;

  const [f, setF] = useState({
    cliente: item?.cliente || '', valor: item?.valor || '',
    descricao: item?.descricao || '', status: item?.status || 'Em andamento',
    pagamento: item?.pagamento || 'Pendente', prazo: item?.prazo || '',
    dataInicio: item?.dataInicio || '',
    tipo: item?.tipo || item?.tipoProjeto || '',
    origem: item?.origem || '',
    siteUrl: item?.siteUrl || '',
    fechadoEm: initialFechadoEm,
    nf: item?.nf || 'nao', anotacoes: item?.anotacoes || '',
  });
  const u = (k) => (e) => setF(p => ({ ...p, [k]: e.target.value }));
  const noCli = !data.clientes.length && (
    <div style={{ 
      fontSize: 12, 
      color: 'var(--amber)', 
      marginTop: 10, 
      padding: '10px 12px', 
      background: 'rgba(245, 158, 11, 0.08)', 
      border: '1px solid rgba(245, 158, 11, 0.2)', 
      borderRadius: 'var(--radius-sm)',
      display: 'flex',
      alignItems: 'center',
      gap: 8,
      lineHeight: 1.4
    }}>
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 16, height: 16, flexShrink: 0 }}>
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>
      </svg>
      <span>
        Cadastre clientes em <span 
          style={{ textDecoration: 'underline', cursor: 'pointer', color: 'inherit', fontWeight: 600, transition: 'opacity 0.2s' }} 
          onMouseEnter={e => e.currentTarget.style.opacity = '0.8'}
          onMouseLeave={e => e.currentTarget.style.opacity = '1'}
          onClick={() => { closeModal(); goTo('clientes'); }}
        >Negócio &rarr; Clientes</span> antes de criar projetos.
      </span>
    </div>
  );

  const tipoOptions = Array.from(new Set(['', 'Site', 'Landing page', 'Loja virtual', 'Sistema', 'Manutenção', 'Outro', ...(f.tipo ? [f.tipo] : [])]));
  const origemOptions = Array.from(new Set(['', 'Lead (prospecção)', 'Cliente antigo', 'Indicação', 'Outro', ...(f.origem ? [f.origem] : [])]));

  return (
    <div className="form-grid">
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Cliente</label>
          <CustomSelect variant="form" value={f.cliente} onChange={u('cliente')} placeholder="-- Selecione um cliente --">
            <option value="">-- Selecione um cliente --</option>
            {data.clientes.map(c => <option key={c.id} value={c.nome}>{c.nome}</option>)}
          </CustomSelect>
          {noCli}
        </div>
        <div className="form-group"><label className="form-label">Valor</label><NumberStepper mode="currency" value={f.valor} onChange={(value) => setF(p => ({ ...p, valor: value }))} min={0} className="form-input" /></div>
      </div>
      <div className="form-group"><label className="form-label">Nome do Projeto</label><input className="form-input" value={f.descricao} onChange={u('descricao')} placeholder="Ex: Landing Page para Advogados" /></div>
      <div className="form-group">
        <label className="form-label">Anotações do Projeto</label>
        <textarea
          className="form-textarea"
          placeholder="Anote aqui a estrutura do projeto, acessos, observações importantes..."
          style={{ minHeight: 100, fontSize: 13, lineHeight: 1.5 }}
          value={f.anotacoes}
          onChange={u('anotacoes')}
        />
      </div>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Tipo de Projeto</label>
          <CustomSelect variant="form" value={f.tipo} onChange={u('tipo')} placeholder="Não informado">
            {tipoOptions.map(t => <option key={t} value={t}>{t || 'Não informado'}</option>)}
          </CustomSelect>
        </div>
        <div className="form-group"><label className="form-label">Origem</label>
          <CustomSelect variant="form" value={f.origem} onChange={u('origem')} placeholder="Não informado">
            {origemOptions.map(o => <option key={o} value={o}>{o || 'Não informado'}</option>)}
          </CustomSelect>
        </div>
      </div>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Status do Projeto</label>
          <CustomSelect variant="form" value={f.status} onChange={u('status')}>
            {['Em andamento', 'Aguardando cliente', 'Aguardando Aprovação', 'Concluído', 'Pausado', 'Cancelado'].map(s => <option key={s}>{s}</option>)}
          </CustomSelect>
        </div>
        <div className="form-group"><label className="form-label">Site (URL)</label>
          <input className="form-input" type="url" value={f.siteUrl} onChange={u('siteUrl')} placeholder="https://exemplo.com.br" />
        </div>
      </div>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Status do Pagamento</label>
          <CustomSelect variant="form" value={f.pagamento} onChange={u('pagamento')}>
            {['Pendente', 'Parcial (50%)', 'Pago'].map(p => <option key={p}>{p}</option>)}
          </CustomSelect>
        </div>
        <div className="form-group"><label className="form-label">Nota Fiscal</label>
          <CustomSelect variant="form" value={f.nf} onChange={u('nf')}>
            <option value="nao">Não emitida</option>
            <option value="sim">Emitida</option>
            <option value="pendente">Pendente</option>
          </CustomSelect>
        </div>
      </div>
      <div className="form-grid form-grid-2">
        <div className="form-group"><label className="form-label">Fechado em</label><input className="form-input" type="date" value={f.fechadoEm} onChange={u('fechadoEm')} /></div>
        <div className="form-group"><label className="form-label">Prazo / Entrega</label><input className="form-input" type="date" value={f.prazo} onChange={u('prazo')} /></div>
      </div>
      <div className="form-actions">
        <button className="btn btn-secondary" onClick={closeModal}>Cancelar</button>
        <button className="btn btn-primary" onClick={() => {
          if (!f.cliente || !f.descricao) return useDash.getState().toast('Cliente e Nome do Projeto são obrigatórios.', 'error');
          saveProjeto({ ...f, tipoProjeto: f.tipo, valor: parseFloat(f.valor) || 0 });
        }}>Salvar</button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useDash } from '../../store/useStore';
import CustomSelect from '../CustomSelect';
import { NumberStepper } from '../shared';
import { formatMinutes, getMesAtualKey, formatMesAnoLabel, navegarMes, getAtividadesDomes, calcularConsumoMes } from '../../utils/timeUtils';
import { generateManutencaoPDF } from '../PDFGenerator';
import { navToConfigTab } from './shared';

export default function RecorrenciaForm({ item }) {
  const data = useDash(s => s.data);
  const saveRecorrencia = useDash(s => s.saveRecorrencia);
  const closeModal = useDash(s => s.closeModal);
  const goTo = useDash(s => s.goTo);
  const setConfigTab = useDash(s => s.setConfigTab);
  const openModal = useDash(s => s.openModal);
  const deleteAtividadeManutencao = useDash(s => s.deleteAtividadeManutencao);

  const navTo = (tab) => navToConfigTab(closeModal, setConfigTab, goTo, tab);

  const today = new Date().toISOString().split('T')[0];
  const mesAtual = getMesAtualKey();
  const [mesSelecionado, setMesSelecionado] = useState(mesAtual);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  const configData = useDash(s => s.configData);
  const [f, setF] = useState({
    cliente: item?.cliente || '', valor: item?.valor || '',
    plano: item?.plano || '', periodicidade: item?.periodicidade || 'Mensal',
    status: item?.status || 'Ativo', vencimento: item?.vencimento || '',
    renovacao: item?.renovacao || '', dataInicio: item?.dataInicio || '',
    reajusteEm: item?.reajusteEm || '',
    metodoPagamento: item?.metodoPagamento || 'PIX', observacoes: item?.observacoes || '',
    limiteHoras: item?.limiteHoras || '',
    codigoServicoNf: item?.codigoServicoNf || '',
    descricaoNf: item?.descricaoNf || '',
  });
  const u = (k) => (e) => setF(p => ({ ...p, [k]: e.target.value }));
  const isFixedDate = f.periodicidade === 'Anual' || f.periodicidade === 'Semestral';
  const noCli = !data.clientes.length && (
    <div style={{ 
      fontSize: 12, 
      color: 'var(--amber)', 
      marginTop: 10, 
      padding: '10px 12px', 
      background: 'rgba(245, 158, 11, 0.08)', 
      border: '1px solid rgba(245, 158, 11, 0.2)', 
      borderRadius: 'var(--radius-sm)',
      display: 'flex',
      alignItems: 'center',
      gap: 8,
      lineHeight: 1.4
    }}>
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 16, height: 16, flexShrink: 0 }}>
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>
      </svg>
      <span>
        Cadastre clientes em <span 
          style={{ textDecoration: 'underline', cursor: 'pointer', color: 'inherit', fontWeight: 600, transition: 'opacity 0.2s' }} 
          onMouseEnter={e => e.currentTarget.style.opacity = '0.8'}
          onMouseLeave={e => e.currentTarget.style.opacity = '1'}
          onClick={() => { closeModal(); goTo('clientes'); }}
        >Negócio &rarr; Clientes</span> antes de criar recorrências.
      </span>
    </div>
  );

  // ── Atividades de Manutenção: cálculo do mês selecionado ──
  const atividades = item?.atividades || [];
  const consumo = calcularConsumoMes(atividades, mesSelecionado, f.limiteHoras);
  const atividadesMes = getAtividadesDomes(atividades, mesSelecionado);
  const atividadesOrdenadas = [...atividadesMes].sort((a, b) => (b.data || '').localeCompare(a.data || ''));

  const handleExportPDF = async () => {
    if (atividadesMes.length === 0) {
      useDash.getState().toast(`Nenhuma atividade registrada em ${formatMesAnoLabel(mesSelecionado)} para exportar.`, 'warning');
      return;
    }
    const configData = useDash.getState().configData;
    setGeneratingPdf(true);
    try {
      useDash.getState().toast('Gerando relatório em PDF...', 'info');
      await generateManutencaoPDF({
        cliente: f.cliente || item?.cliente || 'Cliente',
        plano: f.plano || item?.plano || 'Manutenção',
        mesKey: mesSelecionado,
        mesLabel: formatMesAnoLabel(mesSelecionado),
        atividades: atividadesOrdenadas,
        consumo,
      }, configData);
      useDash.getState().toast('Relatório exportado com sucesso!', 'success');
    } catch (err) {
      console.error('Erro ao exportar PDF:', err);
      useDash.getState().toast('Erro ao gerar relatório em PDF.', 'error');
    } finally {
      setGeneratingPdf(false);
    }
  };

  // Cor da barra de progresso de horas
  const progressColor = consumo.percentual == null ? 'var(--accent)'
    : consumo.excedeu ? 'var(--red)'
    : consumo.percentual >= 80 ? '#f59e0b'
    : 'var(--green)';

  return (
    <div className={item?.id ? 'rec-modal-split' : 'form-grid'}>
      {/* ── COLUNA ESQUERDA: formulário de dados do cliente ── */}
      <div className="form-grid rec-modal-left">
        <div className="form-grid form-grid-2">
          <div className="form-group"><label className="form-label">Cliente</label>
            <CustomSelect variant="form" value={f.cliente} onChange={u('cliente')} placeholder="-- Selecione um cliente --">
              <option value="">-- Selecione um cliente --</option>
              {data.clientes.map(c => <option key={c.id} value={c.nome}>{c.nome}</option>)}
            </CustomSelect>
            {noCli}
          </div>
          <div className="form-group"><label className="form-label">Valor</label><NumberStepper mode="currency" value={f.valor} onChange={(value) => setF(p => ({ ...p, valor: value }))} min={0} className="form-input" /></div>
        </div>
        <div className="form-group"><label className="form-label">Plano / Descrição</label><input className="form-input" value={f.plano} onChange={u('plano')} /></div>
        <div className="form-grid form-grid-2">
          <div className="form-group"><label className="form-label">Periodicidade</label>
            <CustomSelect variant="form" value={f.periodicidade} onChange={u('periodicidade')}>
              <option>Mensal</option><option>Semestral</option><option>Anual</option>
            </CustomSelect>
          </div>
          <div className="form-group"><label className="form-label">Status</label>
            <CustomSelect variant="form" value={f.status} onChange={u('status')}>
              <option>Ativo</option><option>Inativo</option>
            </CustomSelect>
          </div>
        </div>
        <div className="form-grid form-grid-2">
          {!isFixedDate && (
            <div className="form-group"><label className="form-label">Dia de Vencimento</label><NumberStepper value={f.vencimento} onChange={(value) => setF(p => ({ ...p, vencimento: value }))} min={1} max={31} className="form-input" /></div>
          )}
          {isFixedDate && (
            <div className="form-group"><label className="form-label">Data de Renovação</label><input className="form-input" type="date" value={f.renovacao} onChange={u('renovacao')} /></div>
          )}
          <div className="form-group"><label className="form-label">Método de Cobrança</label>
            <CustomSelect variant="form" value={f.metodoPagamento} onChange={u('metodoPagamento')}>
              {['PIX', 'Boleto', 'Cartão', 'Transferência', 'Dinheiro'].map(m => <option key={m}>{m}</option>)}
            </CustomSelect>
          </div>
        </div>
        <div className="form-grid form-grid-2">
          <div className="form-group"><label className="form-label">Data de Início</label><input className="form-input" type="date" value={f.dataInicio} onChange={u('dataInicio')} /></div>
          <div className="form-group">
            <label className="form-label">
              Próximo Reajuste / Renovação
              <span style={{ fontWeight: 400, color: 'var(--text3)', marginLeft: 4 }}>(opcional)</span>
            </label>
            <input className="form-input" type="date" value={f.reajusteEm} onChange={u('reajusteEm')} />
          </div>
        </div>
        <div className="form-group">
          <label className="form-label">
            Limite Mensal de Manutenção
            <span style={{ fontWeight: 400, color: 'var(--text3)', marginLeft: 4 }}>(horas)</span>
          </label>
          <input
            className="form-input"
            type="number"
            min="0"
            step="0.5"
            placeholder="Ex: 4  (vazio = sem limite)"
            value={f.limiteHoras}
            onChange={u('limiteHoras')}
          />
        </div>
        <div className="form-grid form-grid-2">
          <div className="form-group">
            <label className="form-label">Código do serviço (NFS-e)</label>
            <input
              className="form-input"
              placeholder={configData?.codigoServicoNfPadrao ? `Padrão: ${configData.codigoServicoNfPadrao}` : 'Ex: 01.03.01'}
              value={f.codigoServicoNf}
              onChange={u('codigoServicoNf')}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Descrição padrão da NF</label>
            <input
              className="form-input"
              placeholder={f.plano ? `${f.plano} — {competencia}` : '{plano} — {competencia}'}
              value={f.descricaoNf}
              onChange={u('descricaoNf')}
            />
            <div style={{ fontSize: 11, color: 'var(--text3)', marginTop: 4 }}>
              Variáveis: <code>{'{mes}'}</code>, <code>{'{ano}'}</code>, <code>{'{competencia}'}</code>, <code>{'{plano}'}</code>
            </div>
          </div>
        </div>
        <div className="form-group"><label className="form-label">Observações</label><textarea className="form-textarea" style={{ minHeight: 50 }} value={f.observacoes} onChange={u('observacoes')} /></div>
        <div className="form-actions">
          <button className="btn btn-secondary" onClick={closeModal}>Cancelar</button>
          <button className="btn btn-primary" onClick={() => {
            if (!f.cliente || !f.plano) return useDash.getState().toast('Cliente e Plano/Descrição são obrigatórios.', 'error');
            const limiteHorasNum = f.limiteHoras !== '' && f.limiteHoras !== null ? parseFloat(f.limiteHoras) || null : null;
            const matchedCli = data.clientes.find(c => c.nome === f.cliente);
            saveRecorrencia({
              ...f,
              clienteId: item?.clienteId || matchedCli?.id || '',
              valor: parseFloat(f.valor) || 0,
              limiteHoras: limiteHorasNum,
              vencimento: !isFixedDate ? (parseInt(f.vencimento) || 1) : null,
              renovacao: isFixedDate ? f.renovacao : null,
              reajusteEm: f.reajusteEm || '',
              codigoServicoNf: (f.codigoServicoNf || '').trim(),
              descricaoNf: (f.descricaoNf || '').trim(),
              competencias: item?.competencias || {},
              // Preserva o array de atividades existente intacto (não sobrescreve)
              atividades: item?.atividades || [],
            });
          }}>Salvar</button>
        </div>
      </div>

      {/* ── COLUNA DIREITA: Atividades de Manutenção (apenas edição) ── */}
      {item?.id && (
        <div className="rec-modal-right">
          {/* Divisor vertical */}
          <div className="rec-modal-divider" />

          {/* Painel de manutenção */}
          <div className="manutencao-panel">
            {/* Cabeçalho da seção */}
            <div className="manutencao-header">
              <div className="manutencao-title">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 15, height: 15 }}>
                  <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
                </svg>
                Atividades de Manutenção
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <button
                  type="button"
                  className="btn btn-sm btn-secondary"
                  style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12, padding: '5px 10px' }}
                  onClick={handleExportPDF}
                  disabled={generatingPdf}
                  title={`Exportar Relatório PDF (${formatMesAnoLabel(mesSelecionado)})`}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13, color: 'var(--red)' }}>
                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                    <polyline points="14 2 14 8 20 8"/>
                    <line x1="12" y1="18" x2="12" y2="12"/>
                    <polyline points="9 15 12 18 15 15"/>
                  </svg>
                  {generatingPdf ? 'Gerando...' : 'Exportar PDF'}
                </button>
                <button
                  type="button"
                  className="btn btn-sm btn-primary manutencao-add-btn"
                  onClick={() => openModal('atividadeManutencao', item.id)}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 12, height: 12 }}>
                    <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
                  </svg>
                  Registrar atividade
                </button>
              </div>
            </div>

            {/* Navegador de mês */}
            <div className="manutencao-mes-nav">
              <button
                type="button"
                className="mes-nav-btn"
                onClick={() => setMesSelecionado(prev => navegarMes(prev, -1))}
                title="Mês anterior"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}><path d="M15 18l-6-6 6-6"/></svg>
              </button>
              <span className="mes-nav-label">{formatMesAnoLabel(mesSelecionado)}</span>
              <button
                type="button"
                className="mes-nav-btn"
                onClick={() => setMesSelecionado(prev => navegarMes(prev, 1))}
                title="Próximo mês"
                disabled={mesSelecionado >= mesAtual}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}><path d="M9 18l6-6-6-6"/></svg>
              </button>
              {mesSelecionado !== mesAtual && (
                <button
                  type="button"
                  className="mes-nav-hoje"
                  onClick={() => setMesSelecionado(mesAtual)}
                >Mês atual</button>
              )}
            </div>

            {/* KPIs de consumo */}
            <div className="manutencao-kpis">
              {consumo.limiteMinutos != null ? (
                <>
                  <div className="manutencao-kpi">
                    <span className="manutencao-kpi-label">Contratado</span>
                    <span className="manutencao-kpi-value">{formatMinutes(consumo.limiteMinutos)}</span>
                  </div>
                  <div className="manutencao-kpi">
                    <span className="manutencao-kpi-label">Utilizado</span>
                    <span className="manutencao-kpi-value" style={{ color: consumo.excedeu ? 'var(--red)' : consumo.totalMinutos > 0 ? 'var(--text)' : 'var(--text3)' }}>
                      {formatMinutes(consumo.totalMinutos)}
                    </span>
                  </div>
                  <div className="manutencao-kpi">
                    <span className="manutencao-kpi-label">Disponível</span>
                    <span className="manutencao-kpi-value" style={{ color: consumo.excedeu ? 'var(--red)' : 'var(--green)' }}>
                      {consumo.excedeu
                        ? `+${formatMinutes(consumo.totalMinutos - consumo.limiteMinutos)} excedido`
                        : formatMinutes(consumo.disponivelMinutos)
                      }
                    </span>
                  </div>
                </>
              ) : (
                <div className="manutencao-kpi" style={{ flex: 'none' }}>
                  <span className="manutencao-kpi-label">Utilizado no mês</span>
                  <span className="manutencao-kpi-value" style={{ color: consumo.totalMinutos > 0 ? 'var(--text)' : 'var(--text3)' }}>
                    {consumo.totalMinutos > 0 ? formatMinutes(consumo.totalMinutos) : 'Nenhum registro'}
                  </span>
                </div>
              )}
            </div>

            {/* Barra de progresso (apenas com limite) */}
            {consumo.limiteMinutos != null && (
              <div className="manutencao-progress-wrap">
                <div className="manutencao-progress-track">
                  <div
                    className="manutencao-progress-fill"
                    style={{
                      width: `${Math.min(consumo.percentual, 100)}%`,
                      background: progressColor,
                    }}
                  />
                </div>
                <span className="manutencao-progress-pct" style={{ color: progressColor }}>
                  {consumo.percentual}%
                </span>
              </div>
            )}

            {/* Lista de atividades do mês */}
            <div className="manutencao-list">
              {atividadesOrdenadas.length === 0 ? (
                <div className="manutencao-empty">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 28, height: 28, opacity: 0.3 }}>
                    <rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>
                  </svg>
                  <span>Nenhuma atividade registrada em {formatMesAnoLabel(mesSelecionado)}.</span>
                </div>
              ) : (
                atividadesOrdenadas.map(a => (
                  <div key={a.id} className="manutencao-item">
                    <div className="manutencao-item-meta">
                      <span className="manutencao-item-data">
                        {(a.data || '').split('-').reverse().join('/')}
                      </span>
                      <span className="manutencao-item-tempo">{formatMinutes(a.minutos)}</span>
                    </div>
                    <div className="manutencao-item-desc">{a.descricao}</div>
                    <div className="manutencao-item-actions">
                      <button
                        type="button"
                        className="row-btn"
                        title="Editar atividade"
                        onClick={() => openModal('atividadeManutencao', item.id, { atividadeId: a.id })}
                      >
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                          <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
                          <path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4z"/>
                        </svg>
                      </button>
                      <button
                        type="button"
                        className="row-btn del"
                        title="Excluir atividade"
                        onClick={() => deleteAtividadeManutencao(item.id, a.id)}
                      >
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                          <polyline points="3 6 5 6 21 6"/>
                          <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
                        </svg>
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useId, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useDialogFocus } from './useDialogFocus';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';

export function Drawer({
  isOpen,
  onClose,
  title,
  description,
  children,
  footer,
  navigation,
  width = 460,
  className = '',
}) {
  const reducedMotion = useReducedMotion();
  const drawerRef = useRef(null);

  const titleId = useId();
  const restoreFocus = useDialogFocus(isOpen, drawerRef, onClose);

  return createPortal(
    <AnimatePresence onExitComplete={restoreFocus}>
      {isOpen && (
        <div
          className="ui-drawer-portal"
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 'var(--z-drawer, 60)',
            display: 'flex',
            justifyContent: 'flex-end',
          }}
        >
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: reducedMotion ? 0 : 0.18 }}
            onClick={onClose}
            style={{
              position: 'fixed',
              inset: 0,
              background: 'var(--scrim)',
              backdropFilter: 'blur(8px)',
            }}
          />

          {/* Drawer Panel */}
          <motion.div
            ref={drawerRef}
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'tween', duration: reducedMotion ? 0 : 0.24, ease: [0.16, 1, 0.3, 1] }}
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            tabIndex={-1}
            className={`ui-drawer-panel ${className}`}
            style={{
              position: 'relative',
              width: '100%',
              maxWidth: width,
              height: 'calc(100dvh - 24px)',
              margin: 12,
              background: 'var(--surface-floating)',
              border: '1px solid var(--border-light)',
              borderRadius: 'var(--radius-drawer)',
              boxShadow: 'var(--shadow-3)',
              display: 'flex',
              flexDirection: 'column',
              zIndex: 1,
              overflow: 'hidden',
            }}
          >
            {/* Header */}
            <div
              style={{
                padding: '20px 24px',
                borderBottom: '1px solid var(--border)',
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'space-between',
                gap: 16,
              }}
            >
              <div>
                <h2
                  id={titleId}
                  style={{
                    fontSize: 22,
                    fontWeight: 600,
                    color: 'var(--text)',
                    margin: 0,
                  }}
                >
                  {title}
                </h2>
                {description && (
                  <p
                    style={{
                      fontSize: 'var(--font-meta, 12px)',
                      color: 'var(--text3)',
                      margin: '4px 0 0 0',
                    }}
                  >
                    {description}
                  </p>
                )}
              </div>
              <button
                type="button"
                onClick={onClose}
                aria-label="Fechar drawer"
                style={{
                  width: 40,
                  height: 40,
                  borderRadius: 'var(--radius-pill)',
                  border: 'none',
                  background: 'var(--bg3)',
                  color: 'var(--text3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer',
                  flexShrink: 0,
                  transition: 'background var(--t-fast, 120ms) ease',
                }}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 16, height: 16 }}>
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>

            {navigation}

            {/* Content Body */}
            <div
              style={{
                flex: 1,
                minHeight: 0,
                overflowY: 'auto',
                padding: '24px',
                display: 'flex',
                flexDirection: 'column',
                gap: 20,
              }}
            >
              {children}
            </div>

            {/* Footer */}
            {footer && (
              <div
                style={{
                  padding: '16px 24px',
                  borderTop: '1px solid var(--border)',
                  background: 'var(--bg3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'flex-end',
                  gap: 10,
                }}
              >
                {footer}
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>,
    document.body
  );
}

export default Drawer;

import { useId, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useDialogFocus } from './useDialogFocus';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';

export function Modal({
  isOpen,
  onClose,
  title,
  description,
  children,
  footer,
  size = 'md',
  className = '',
}) {
  const reducedMotion = useReducedMotion();
  const overlayClickRef = useRef(false);

  const titleId = useId();
  const panelRef = useRef(null);
  const restoreFocus = useDialogFocus(isOpen, panelRef, onClose);

  const sizeWidths = {
    sm: 420,
    md: 560,
    lg: 760,
  };

  const maxWidth = sizeWidths[size] || sizeWidths.md;

  return createPortal(
    <AnimatePresence onExitComplete={restoreFocus}>
      {isOpen && (
        <div
          className="ui-modal-portal"
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 'var(--z-modal, 70)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 16,
          }}
          onMouseDown={(e) => { overlayClickRef.current = e.target === e.currentTarget; }}
          onMouseUp={(e) => {
            if (e.target === e.currentTarget && overlayClickRef.current) {
              onClose?.();
            }
            overlayClickRef.current = false;
          }}
        >
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: reducedMotion ? 0 : 0.18 }}
            style={{
              position: 'fixed',
              inset: 0,
              background: 'var(--scrim)',
              backdropFilter: 'blur(8px)',
              pointerEvents: 'none',
            }}
          />

          {/* Modal Container */}
          <motion.div
            initial={{ opacity: 0, scale: 0.96, y: 8 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.96, y: 8 }}
            transition={{ duration: reducedMotion ? 0 : 0.18, ease: [0.16, 1, 0.3, 1] }}
            ref={panelRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            tabIndex={-1}
            className={`ui-modal-container ${className}`}
            style={{
              position: 'relative',
              width: '100%',
              maxWidth,
              maxHeight: 'calc(100dvh - 32px)',
              background: 'var(--surface-floating)',
              border: '1px solid var(--border-light)',
              borderRadius: 'var(--radius-modal)',
              boxShadow: 'var(--shadow-3)',
              display: 'flex',
              flexDirection: 'column',
              zIndex: 1,
              overflow: 'hidden',
            }}
          >
            {/* Header */}
            <div
              style={{
                padding: '18px 22px',
                borderBottom: '1px solid var(--border)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 12,
              }}
            >
              <div>
                <h3
                  id={titleId}
                  style={{
                    fontSize: 20,
                    fontWeight: 600,
                    color: 'var(--text)',
                    margin: 0,
                  }}
                >
                  {title}
                </h3>
                {description && (
                  <p
                    style={{
                      fontSize: 'var(--font-meta, 12px)',
                      color: 'var(--text3)',
                      margin: '2px 0 0 0',
                    }}
                  >
                    {description}
                  </p>
                )}
              </div>
              <button
                type="button"
                onClick={onClose}
                aria-label="Fechar"
                style={{
                  width: 40,
                  height: 40,
                  borderRadius: 'var(--radius-pill)',
                  border: 'none',
                  background: 'var(--bg3)',
                  color: 'var(--text3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer',
                  flexShrink: 0,
                }}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Body */}
            <div
              style={{
                padding: '22px',
                overflowY: 'auto',
                display: 'flex',
                flexDirection: 'column',
                gap: 16,
              }}
            >
              {children}
            </div>

            {/* Footer */}
            {footer && (
              <div
                style={{
                  padding: '14px 22px',
                  borderTop: '1px solid var(--border)',
                  background: 'var(--bg3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'flex-end',
                  gap: 10,
                }}
              >
                {footer}
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>,
    document.body
  );
}

export default Modal;

import ToastComponent, { GlobalLoader } from '../Toast';
import { useDash } from '../../store/useStore';

/**
 * Toast Component & Helper
 * Reaproveita o sistema de Toast atual com suporte a ação opcional (Desfazer)
 */
export { GlobalLoader };
export const Toast = ToastComponent;

export function useToast() {
  const toast = useDash(s => s.toast);
  return {
    toast,
    success: (msg, duration) => toast(msg, 'success', duration),
    error: (msg, duration) => toast(msg, 'error', duration),
    info: (msg, duration) => toast(msg, 'info', duration),
    warning: (msg, duration) => toast(msg, 'warning', duration),
  };
}

export default Toast;

