    { id: 'broadcast', label: 'Broadcast', icon: ICONS.broadcast },
    { id: 'health', label: 'Suporte & Saúde', icon: "M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" },
    { id: 'notifications', label: 'Testes', icon: ICONS.testing },
