    return () => {
      window.removeEventListener('focus', checkReturn);
      document.removeEventListener('visibilitychange', onVisChange);
    };
  }, [pendingWaLead]);

  const handleWaClick = (lead, e) => {
    if (e) e.stopPropagation();
