                      <span>Copiar dados</span></button>
                      <button type="button" role="menuitem" className="row-btn" onClick={() => openModal('lead', l.id)} title="Editar">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4z"/></svg>
                      <span>Editar</span></button>
                      <button type="button" role="menuitem" className="row-btn del" onClick={() => deleteItem('leads', l.id, l.nome)} title="Excluir">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
                      <span>Excluir</span></button>
                    </LeadActionsMenu>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
        </div>
      </section>
      )}

      {effectiveViewMode === 'list' && (
        <div className="leads-pagination-bar">
          <div className="leads-pagination-info-group">
            <span className="leads-pagination-count">
              {totalItems === 0 ? (
                'Nenhum lead encontrado'
              ) : (
                <>
                  Mostrando <strong>{((safePage - 1) * resolvedPageSize) + 1}–{Math.min(safePage * resolvedPageSize, totalItems)}</strong> de <strong>{totalItems.toLocaleString('pt-BR')}</strong> leads
                </>
              )}
            </span>

            {totalItems > 0 && (
              <div className="leads-pagination-footer-size">
                <span>Por página:</span>
                <div className="leads-page-size-custom-box" style={{ height: 26, padding: '0 6px' }}>
                  <input
                    type="number"
                    min="1"
                    max="1000"
                    className="leads-page-size-custom-input" aria-label="Leads por página"
                    style={{ width: 34, fontSize: 11 }}
                    value={pageSize}
                    onChange={(e) => {
                      const raw = e.target.value;
                      if (raw === '') setPageSize('');
                      else {
                        const num = parseInt(raw, 10);
                        setPageSize(isNaN(num) ? 30 : Math.max(1, Math.min(1000, num)));
                      }
                      setPage(1);
                    }}
                    onBlur={() => {
                      if (!pageSize || Number(pageSize) < 1) setPageSize(30);
                    }}
                  />
                  <span className="leads-page-size-custom-unit" style={{ fontSize: 10 }}>itens</span>
                </div>
              </div>
            )}
          </div>

          {totalPages > 1 && (
            <div className="leads-pagination-controls">
              <button
                className="leads-pagination-btn"
                disabled={safePage === 1}
                onClick={() => setPage(1)}
                title="Primeira página"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                  <polyline points="11 17 6 12 11 7"/><polyline points="18 17 13 12 18 7"/>
                </svg>
              </button>

              <button
                className="leads-pagination-btn"
                disabled={safePage === 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                title="Página anterior"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                  <polyline points="15 18 9 12 15 6"/>
                </svg>
                <span className="leads-pagination-nav-text">Anterior</span>
              </button>

              {getPaginationItems(safePage, totalPages).map((item, idx) => {
                if (item === '...') {
                  return (
                    <span key={`ellipsis-${idx}`} className="leads-pagination-ellipsis">
                      …
                    </span>
                  );
                }
                const pageNum = Number(item);
                const isCurrent = pageNum === safePage;
                return (
                  <button
                    key={pageNum}
                    className={`leads-pagination-btn ${isCurrent ? 'active' : ''}`}
                    onClick={() => setPage(pageNum)}
                    title={`Ir para a página ${pageNum}`}
                    aria-current={isCurrent ? 'page' : undefined}
                  >
                    {pageNum}
                  </button>
                );
              })}

              <button
                className="leads-pagination-btn"
                disabled={safePage === totalPages}
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                title="Próxima página"
              >
                <span className="leads-pagination-nav-text">Próxima</span>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                  <polyline points="9 18 15 12 9 6"/>
                </svg>
              </button>

              <button
                className="leads-pagination-btn"
                disabled={safePage === totalPages}
                onClick={() => setPage(totalPages)}
                title="Última página"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13 }}>
                  <polyline points="13 17 18 12 13 7"/><polyline points="6 17 11 12 6 7"/>
                </svg>
              </button>
            </div>
          )}
        </div>
      )}

      {undoAction && (
        <div
          style={{
            position: 'fixed',
            bottom: 24,
            left: '50%',
            transform: 'translateX(-50%)',
            zIndex: 999,
            background: 'var(--bg2)',
            border: '1px solid var(--accent)',
            borderRadius: 10,
            padding: '10px 16px',
            boxShadow: '0 10px 30px rgba(0,0,0,0.45)',
            display: 'flex',
            alignItems: 'center',
            gap: 12,
            fontSize: 13,
            color: 'var(--text)',
          }}
        >
          <span>{undoAction.label}</span>
          <button
            type="button"
            className="btn btn-sm btn-primary"
            style={{ padding: '4px 10px', fontSize: 12 }}
            onClick={async () => {
              const fn = undoAction.onUndo;
              setUndoAction(null);
              if (fn) await fn();
              useDash.getState().toast('Alteração desfeita.');
            }}
          >
            Desfazer
          </button>
          <button
            type="button"
            onClick={() => setUndoAction(null)}
            style={{ background: 'transparent', border: 'none', color: 'var(--text3)', cursor: 'pointer', fontSize: 16, lineHeight: 1 }}
            title="Fechar"
          >
            ×
          </button>
        </div>
      )}

      <PreQualProgressModal modal={prequalModal} onClose={() => setPrequalModal(null)} />
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useDash, uCol } from '../store/useStore';
import { getDocs } from 'firebase/firestore';

const TRASH_COLS = ['leads', 'projetos', 'recorrencia', 'negocio', 'pessoal', 'clientes', 'despesasFixas'];
const TRASH_LABELS = {
  leads: 'Lead',
  projetos: 'Projeto',
  recorrencia: 'Recorrência',
  negocio: 'Finança (PJ)',
  pessoal: 'Finança (PF)',
  clientes: 'Cliente',
  despesasFixas: 'Despesa Fixa'
};
const TRASH_DAYS = 15;

const TRASH_COLORS = {
  leads: { bg: 'rgba(56, 189, 248, 0.12)', color: '#38bdf8' },
  projetos: { bg: 'rgba(99, 102, 241, 0.12)', color: '#6366f1' },
  recorrencia: { bg: 'rgba(168, 85, 247, 0.12)', color: '#a855f7' },
  negocio: { bg: 'rgba(34, 197, 94, 0.12)', color: '#22c55e' },
  pessoal: { bg: 'rgba(34, 197, 94, 0.12)', color: '#22c55e' },
  clientes: { bg: 'rgba(245, 158, 11, 0.12)', color: '#f59e0b' },
  despesasFixas: { bg: 'rgba(239, 68, 68, 0.12)', color: '#ef4444' }
};

const IcoTrash = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 44, height: 44, opacity: .4, display: 'block', margin: '0 auto 12px' }}>
    <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>
  </svg>
);

const IcoRefresh = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}>
    <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.67"/>
  </svg>
);

export default function LixeiraPage() {
  const currentUser = useDash(s => s.currentUser);
  const restoreItem = useDash(s => s.restoreItem);
  const hardDeleteItem = useDash(s => s.hardDeleteItem);
  const emptyTrash = useDash(s => s.emptyTrash);
  const setLoading = useDash(s => s.setLoading);
  const activePage = useDash(s => s.activePage);
  const toast = useDash(s => s.toast);
  const showConfirm = useDash(s => s.showConfirm);

  const [rawItems, setRawItems] = useState(null); // null = loading
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCol, setSelectedCol] = useState('all');
  const [selectedIds, setSelectedIds] = useState([]);

  const load = async () => {
    setRawItems(null);
    setLoading(true);
    setSelectedIds([]);
    const result = [];
    try {
      for (const colName of TRASH_COLS) {
        const snap = await getDocs(uCol(colName));
        const trashed = snap.docs
          .map(d => ({ id: d.id, colName, ...d.data() }))
          .filter(x => x.deletadoEm);
        if (trashed.length) result.push({ colName, items: trashed });
      }
      setRawItems(result);
    } catch (err) {
      console.error('Erro ao carregar lixeira:', err);
      toast('Erro ao carregar lixeira.', 'error');
      setRawItems([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { 
    if (activePage === 'lixeira') {
      load(); 
    } 
  }, [activePage]);

  // Flattened and filtered list
  const filteredList = useMemo(() => {
    if (!rawItems) return [];
    const list = [];
    for (const group of rawItems) {
      for (const item of group.items) {
        list.push({
          ...item,
          displayName: item.nome || item.cliente || item.descricao || item.titulo || 'Sem nome'
        });
      }
    }

    let result = list;
    if (selectedCol !== 'all') {
      result = result.filter(x => x.colName === selectedCol);
    }
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      result = result.filter(x =>
        x.displayName.toLowerCase().includes(q) ||
        (x.cliente || '').toLowerCase().includes(q) ||
        (x.descricao || '').toLowerCase().includes(q)
      );
    }

    return result.sort((a, b) => new Date(b.deletadoEm).getTime() - new Date(a.deletadoEm).getTime());
  }, [rawItems, selectedCol, searchTerm]);

  const toggleSelect = (colName, id) => {
    const key = `${colName}::${id}`;
    setSelectedIds(prev =>
      prev.includes(key) ? prev.filter(k => k !== key) : [...prev, key]
    );
  };

  const handleSelectAll = () => {
    const visibleKeys = filteredList.map(x => `${x.colName}::${x.id}`);
    const allSelected = visibleKeys.every(k => selectedIds.includes(k));
    if (allSelected) {
      setSelectedIds(prev => prev.filter(k => !visibleKeys.includes(k)));
    } else {
      setSelectedIds(prev => Array.from(new Set([...prev, ...visibleKeys])));
    }
  };

  const handleRestore = async (colName, id) => {
    setLoading(true);
    await restoreItem(colName, id);
    await load();
  };

  const handleHardDelete = async (colName, id) => {
    if (await hardDeleteItem(colName, id)) {
      load();
    }
  };

  const handleEmpty = async () => {
    if (await emptyTrash()) {
      load();
    }
  };

  const handleBulkRestore = async () => {
    if (selectedIds.length === 0) return;
    setLoading(true);
    try {
      for (const itemKey of selectedIds) {
        const [colName, id] = itemKey.split('::');
        await restoreItem(colName, id);
      }
      toast(`${selectedIds.length} item(ns) restaurado(s) com sucesso!`, 'success');
      setSelectedIds([]);
      await load();
    } catch (err) {
      console.error(err);
      toast('Erro ao restaurar itens', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleBulkDelete = async () => {
    if (selectedIds.length === 0) return;
    const confirm = await showConfirm(
      `Apagar permanentemente ${selectedIds.length} item(ns)?`,
      'Esta ação é irreversível e os itens selecionados não poderão ser recuperados de forma alguma.',
      true
    );
    if (!confirm) return;

    setLoading(true);
    try {
      const { deleteDoc, doc, db } = await import('../firebase');
      const uid = currentUser?.uid;

      for (const itemKey of selectedIds) {
        const [colName, id] = itemKey.split('::');
        if (colName === 'leads') {
          const lead = filteredList.find(x => x.colName === 'leads' && x.id === id);
          const path = lead?.prequalData?.screenshotPath;
          if (path) {
            await useDash.getState().deleteFile(path).catch(e => console.warn('[hardDeleteItem] Falha ao deletar screenshot:', e));
          }
        }
        if (uid) {
          await deleteDoc(doc(db, 'users', uid, colName, id));
        }
      }
      toast(`${selectedIds.length} item(ns) apagado(s) definitivamente`, 'success');
      setSelectedIds([]);
      await load();
    } catch (err) {
      console.error(err);
      toast('Erro ao excluir itens permanentemente', 'error');
    } finally {
      setLoading(false);
    }
  };

  // Group counts for tabs
  const groupCounts = useMemo(() => {
    if (!rawItems) return {};
    const counts = {};
    let total = 0;
    for (const colName of TRASH_COLS) {
      const found = rawItems.find(x => x.colName === colName);
      const count = found ? found.items.length : 0;
      counts[colName] = count;
      total += count;
    }
    counts.all = total;
    return counts;
  }, [rawItems]);

  const hasItems = groupCounts.all > 0;

  return (
    <div>
      {/* Title */}
      <div className="page-header" style={{ marginBottom: 14 }}>
        <div className="page-title">Lixeira</div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn btn-secondary" style={{ padding: '6px 12px', fontSize: 12 }} onClick={load} title="Atualizar lixeira">
            <IcoRefresh /> Atualizar
          </button>
          {hasItems && selectedIds.length === 0 && (
            <button className="btn btn-danger" style={{ padding: '6px 12px', fontSize: 12 }} onClick={handleEmpty}>
              Esvaziar Lixeira
            </button>
          )}
        </div>
      </div>
      <p style={{ fontSize: 13, color: 'var(--text3)', marginBottom: 20 }}>
        Itens excluídos permanecem salvos por <strong style={{ color: 'var(--amber)' }}>{TRASH_DAYS} dias</strong> antes de serem apagados permanentemente.
      </p>

      {/* Top Filter and Search Toolbar */}
      {rawItems && hasItems && (
        <div style={{ background: 'var(--bg2)', padding: '16px 20px', borderRadius: 12, border: '1px solid var(--border)', marginBottom: 20, display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center', justifyContent: 'space-between' }}>
            {/* Search Input */}
            <div className="search-wrap" style={{ flex: 1, minWidth: 260, maxWidth: 400 }}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
              </svg>
              <input className="filter-input" placeholder="Buscar por nome ou descrição..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>

            {/* Bulk actions display */}
            {selectedIds.length > 0 && (
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', background: 'var(--accent-bg)', padding: '6px 14px', borderRadius: 8, border: '1px solid var(--accent)' }}>
                <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--accent)' }}>
                  {selectedIds.length} selecionado(s)
                </span>
                <button className="btn btn-sm btn-secondary" style={{ color: 'var(--accent)', borderColor: 'var(--accent)' }} onClick={handleBulkRestore}>
                  Restaurar Selecionados
                </button>
                <button className="btn btn-sm btn-danger" onClick={handleBulkDelete}>
                  Apagar Definitivamente
                </button>
              </div>
            )}
          </div>

          {/* Categories Tab Row */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, borderTop: '1px solid var(--border)', paddingTop: 12 }}>
            <button 
              onClick={() => setSelectedCol('all')} 
              style={{
                background: selectedCol === 'all' ? 'var(--accent-bg)' : 'var(--bg3)',
                color: selectedCol === 'all' ? 'var(--accent)' : 'var(--text2)',
                border: `1px solid ${selectedCol === 'all' ? 'var(--accent)' : 'var(--border)'}`,
                padding: '6px 12px',
                borderRadius: 20,
                fontSize: 12,
                fontWeight: 600,
                cursor: 'pointer',
                transition: 'all 0.2s'
              }}
            >
              Todos ({groupCounts.all || 0})
            </button>
            {TRASH_COLS.map(col => {
              const count = groupCounts[col] || 0;
              if (count === 0 && selectedCol !== col) return null;
              return (
                <button 
                  key={col}
                  onClick={() => setSelectedCol(col)} 
                  style={{
                    background: selectedCol === col ? 'var(--accent-bg)' : 'var(--bg3)',
                    color: selectedCol === col ? 'var(--accent)' : 'var(--text2)',
                    border: `1px solid ${selectedCol === col ? 'var(--accent)' : 'var(--border)'}`,
                    padding: '6px 12px',
                    borderRadius: 20,
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: 'pointer',
                    transition: 'all 0.2s'
                  }}
                >
                  {TRASH_LABELS[col]} ({count})
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Main List Area */}
      {rawItems === null ? null : !hasItems ? (
        <div className="trash-empty" style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 12, padding: '48px 24px', textAlign: 'center' }}>
          <IcoTrash />
          <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--text)', marginBottom: 6 }}>Lixeira vazia</div>
          <div style={{ fontSize: 13, color: 'var(--text3)' }}>Nenhum item excluído recentemente.</div>
        </div>
      ) : filteredList.length === 0 ? (
        <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 12, padding: '48px 24px', textAlign: 'center', color: 'var(--text3)' }}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{ width: 36, height: 36, margin: '0 auto 12px', opacity: .4 }}>
            <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
          </svg>
          <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 4 }}>Nenhum resultado encontrado</div>
          <div style={{ fontSize: 12 }}>Tente alterar o filtro de categoria ou termo de busca.</div>
        </div>
      ) : (
        <div className="table-wrap" style={{ border: '1px solid var(--border)', borderRadius: 12, overflow: 'hidden' }}>
          <table style={{ margin: 0 }}>
            <thead>
              <tr>
                <th style={{ width: 44, textAlign: 'center' }}>
                  <input 
                    type="checkbox" 
                    onChange={handleSelectAll}
                    checked={filteredList.length > 0 && filteredList.every(x => selectedIds.includes(`${x.colName}::${x.id}`))} 
                  />
                </th>
                <th style={{ width: 140 }}>Categoria</th>
                <th>Nome / Descrição</th>
                <th style={{ width: 130 }}>Excluído em</th>
                <th style={{ width: 140 }}>Prazo Limite</th>
                <th style={{ width: 160, textAlign: 'right' }}></th>
              </tr>
            </thead>
            <tbody>
              {filteredList.map(item => {
                const colors = TRASH_COLORS[item.colName] || { bg: 'var(--bg3)', color: 'var(--text2)' };
                const dt = item.deletadoEm ? new Date(item.deletadoEm).toLocaleDateString('pt-BR') : '-';
                const expiresMs = new Date(item.deletadoEm).getTime() + TRASH_DAYS * 86400000;
                const expiresIn = Math.max(0, Math.ceil((expiresMs - Date.now()) / 86400000));

                // Color code days remaining
                let expColor = 'var(--green)';
                let expBg = 'var(--green-bg)';
                if (expiresIn <= 3) {
                  expColor = 'var(--red)';
                  expBg = 'var(--red-bg)';
                } else if (expiresIn <= 8) {
                  expColor = '#f59e0b';
                  expBg = 'rgba(245, 158, 11, 0.12)';
                }

                const isChecked = selectedIds.includes(`${item.colName}::${item.id}`);

                return (
                  <tr key={`${item.colName}::${item.id}`} className={isChecked ? 'row-selected' : ''} style={{ background: isChecked ? 'rgba(var(--accent-rgb), 0.04)' : 'transparent' }}>
                    <td style={{ textAlign: 'center' }}>
                      <input 
                        type="checkbox" 
                        checked={isChecked} 
                        onChange={() => toggleSelect(item.colName, item.id)} 
                      />
                    </td>
                    <td>
                      <span style={{ 
                        fontSize: 10, 
                        fontWeight: 700, 
                        background: colors.bg, 
                        color: colors.color, 
                        padding: '2px 8px', 
                        borderRadius: 6,
                        textTransform: 'uppercase',
                        letterSpacing: '.04em'
                      }}>
                        {TRASH_LABELS[item.colName]}
                      </span>
                    </td>
                    <td>
                      <div style={{ fontWeight: 600, fontSize: 13, color: 'var(--text)' }}>
                        {item.displayName}
                      </div>
                      {item.cliente && item.cliente !== item.displayName && (
                        <div style={{ fontSize: 11, color: 'var(--text3)', marginTop: 2 }}>
                          Cliente: {item.cliente}
                        </div>
                      )}
                    </td>
                    <td style={{ fontSize: 12, color: 'var(--text2)' }}>{dt}</td>
                    <td>
                      <span style={{ 
                        fontSize: 11, 
                        fontWeight: 700, 
                        color: expColor, 
                        background: expBg, 
                        padding: '2px 8px', 
                        borderRadius: 6,
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: 4
                      }}>
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 10, height: 10 }}><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                        {expiresIn === 0 ? 'Expira hoje' : `${expiresIn} dia${expiresIn > 1 ? 's' : ''}`}
                      </span>
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <div style={{ display: 'flex', gap: 6, justifyContent: 'flex-end' }}>
                        <button 
                          className="btn btn-sm btn-secondary" 
                          style={{ color: 'var(--green)', borderColor: 'var(--green-bg)', fontSize: 11, padding: '4px 8px' }}
                          onClick={() => handleRestore(item.colName, item.id)}
                          title="Restaurar este item"
                        >
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 11, height: 11 }}><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
                          Restaurar
                        </button>
                        <button 
                          className="btn btn-sm btn-secondary" 
                          style={{ color: 'var(--red)', borderColor: 'var(--red-bg)', fontSize: 11, padding: '4px 8px' }}
                          onClick={() => handleHardDelete(item.colName, item.id)}
                          title="Excluir definitivamente"
                        >
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 11, height: 11 }}><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                          Excluir
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useState, useRef } from 'react';
import { useDash, fmtBRL, fmtDate } from '../store/useStore';
import { Badge } from '../components/shared';
import { FEATURES } from '../config/features';

export default function ProjectView() {
  const data = useDash(s => s.data);
  const activeProjectView = useDash(s => s.activeProjectView);
  const closeProjectView = useDash(s => s.closeProjectView);
  const updateProjectTarefas = useDash(s => s.updateProjectTarefas);
  const addArquivo = useDash(s => s.addArquivo);
  const delArquivo = useDash(s => s.delArquivo);
  const openModal = useDash(s => s.openModal);
  const updateProjectField = useDash(s => s.updateProjectField);

  const [activeTab, setActiveTab] = useState('detalhes');
  const overlayClickRef = useRef(false);

  const availableTabs = [
    'detalhes',
    ...(FEATURES.PROJECT_FILES ? ['arquivos'] : []),
    ...(FEATURES.PROJECT_TASKS ? ['tarefas'] : []),
  ];
  const currentTab = availableTabs.includes(activeTab) ? activeTab : 'detalhes';

  if (!activeProjectView) return null;
  const p = data.projetos.find(x => x.id === activeProjectView);
  if (!p) return null;

  const handleClose = () => { closeProjectView(); setActiveTab('detalhes'); };

  const handleMouseDown = (e) => {
    overlayClickRef.current = e.target === e.currentTarget;
  };

  const handleMouseUp = (e) => {
    if (e.target === e.currentTarget && overlayClickRef.current) {
      handleClose();
    }
    overlayClickRef.current = false;
  };

  return (
    <div 
      className="pv-overlay open" 
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
    >
      <div className="pv-modal">
        <div className="pv-head">
          <div className="pv-head-info">
            <div className="pv-title">{p.descricao || 'Projeto'}</div>
            <div className="pv-subtitle">{p.cliente || ''}</div>
          </div>
          {availableTabs.length > 1 && (
            <div className="pv-tabs">
              {availableTabs.map(tab => (
                <button key={tab} className={`pv-tab ${currentTab === tab ? 'active' : ''}`} onClick={() => setActiveTab(tab)}>
                  {tab.charAt(0).toUpperCase() + tab.slice(1)}
                </button>
              ))}
            </div>
          )}
          <button className="pv-close-btn" onClick={handleClose}>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12" /></svg>
          </button>
        </div>
        <div className="pv-body">
          {currentTab === 'detalhes' && <PVDetalhes p={p} onEdit={() => { openModal('projeto', p.id); handleClose(); }} updateField={updateProjectField} />}
          {FEATURES.PROJECT_TASKS && currentTab === 'tarefas' && <PVTarefas p={p} onUpdate={updateProjectTarefas} />}
          {FEATURES.PROJECT_FILES && currentTab === 'arquivos' && <PVArquivos p={p} onAdd={addArquivo} onDel={delArquivo} />}
        </div>
      </div>
    </div>
  );
}

function PVDetalhes({ p, onEdit, updateField }) {
  const [notes, setNotes] = useState(p.anotacoes || '');
  const [saving, setSaving] = useState(false);
  const data = useDash(s => s.data);
  const recsProjeto = data.negocio.filter(n => n.tipo === 'Receita' && n.projetoId === p.id);
  const sc = { 'Em andamento': 'var(--blue)', 'Aguardando cliente': 'var(--amber)', 'Aguardando Aprovação': 'var(--purple)', 'Concluído': 'var(--green)', 'Pausado': 'var(--text3)', 'Cancelado': 'var(--red)' }[p.status] || 'var(--text3)';
  const pc = { 'Pago': 'var(--green)', 'Parcial (50%)': 'var(--amber)', 'Pendente': 'var(--amber)' }[p.pagamento] || 'var(--text3)';

  const tipoLabel = p.tipo || p.tipoProjeto || 'Não informado';
  const origemLabel = p.origem || 'Não informado';
  const fechadoEmStr = p.fechadoEm || (typeof p.criadoEm === 'string' && p.criadoEm.includes('-') ? p.criadoEm.split('T')[0] : '');
  const siteHref = p.siteUrl ? (/^https?:\/\//i.test(p.siteUrl) ? p.siteUrl : `https://${p.siteUrl}`) : '';
  
  const handleSaveNotes = async () => {
    if (notes === p.anotacoes) return;
    setSaving(true);
    await updateField(p.id, 'anotacoes', notes);
    setSaving(false);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 12 }}>
        <div className="summary-card">
          <div className="summary-card-label">Valor do Projeto</div>
          <div className="summary-card-val" style={{ fontFamily: 'var(--sans)' }}>{fmtBRL(p.valor)}</div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Fechado em</div>
          <div style={{ fontSize: 16, fontWeight: 500 }}>{fechadoEmStr ? fmtDate(fechadoEmStr) : '—'}</div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Prazo</div>
          <div style={{ fontSize: 16, fontWeight: 500 }}>{p.prazo ? fmtDate(p.prazo) : '—'}</div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Status</div>
          <div style={{ fontSize: 15, fontWeight: 500, color: sc }}>{p.status || '—'}</div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Pagamento</div>
          <div style={{ fontSize: 15, fontWeight: 500, color: pc }}>{p.pagamento || '—'}</div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 12 }}>
        <div className="summary-card">
          <div className="summary-card-label">Tipo</div>
          <div style={{ fontSize: 14, fontWeight: 500, color: p.tipo || p.tipoProjeto ? 'var(--text)' : 'var(--text3)' }}>{tipoLabel}</div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Origem</div>
          <div style={{ fontSize: 14, fontWeight: 500, color: p.origem ? 'var(--text)' : 'var(--text3)' }}>{origemLabel}</div>
        </div>
        <div className="summary-card" style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <svg viewBox="0 0 24 24" fill="none" stroke={p.nf === 'sim' ? 'var(--accent)' : p.nf === 'pendente' ? 'var(--amber)' : 'var(--text3)'} strokeWidth="2" style={{ width: 18, height: 18, flexShrink: 0 }}>
            <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/>
          </svg>
          <div>
            <div className="summary-card-label">Nota Fiscal</div>
            <div style={{ fontWeight: 500, fontSize: 14, color: p.nf === 'sim' ? 'var(--accent)' : p.nf === 'pendente' ? 'var(--amber)' : 'var(--text3)' }}>
              {p.nf === 'sim' ? 'Emitida' : p.nf === 'pendente' ? 'Pendente' : 'Não emitida'}
            </div>
          </div>
        </div>
        <div className="summary-card">
          <div className="summary-card-label">Site</div>
          {siteHref ? (
            <a
              href={siteHref}
              target="_blank"
              rel="noreferrer"
              style={{ fontSize: 13, fontWeight: 500, color: 'var(--accent)', textDecoration: 'none', display: 'inline-flex', alignItems: 'center', gap: 4, wordBreak: 'break-all' }}
            >
              <span>{p.siteUrl.replace(/^https?:\/\//i, '').replace(/\/$/, '')}</span>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 13, height: 13, flexShrink: 0 }}>
                <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/>
              </svg>
            </a>
          ) : (
            <div style={{ fontSize: 14, color: 'var(--text3)' }}>—</div>
          )}
        </div>
      </div>

      <div className="summary-card" style={{ display: 'block' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
          <div className="summary-card-label" style={{ marginBottom: 0 }}>Receitas Vinculadas (Módulo Financeiro)</div>
        </div>
        {recsProjeto.length === 0 ? (
          <div style={{ fontSize: 13, color: 'var(--text3)', fontStyle: 'italic' }}>Nenhuma receita vinculada.</div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {recsProjeto.map(r => (
              <div key={r.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--bg1)', padding: '6px 10px', borderRadius: 4, border: '1px solid var(--border)' }}>
                <span style={{ fontSize: 13, color: 'var(--text2)' }}>{r.descricao || 'Receita'} - <span style={{ color: 'var(--text3)' }}>{fmtDate(r.data)}</span></span>
                <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--green)' }}>{fmtBRL(r.valor)}</span>
              </div>
            ))}
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4, paddingTop: 4, borderTop: '1px solid var(--border)' }}>
              <span style={{ fontSize: 12, fontWeight: 500, color: 'var(--text2)' }}>Total Vinculado:</span>
              <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text)' }}>{fmtBRL(recsProjeto.reduce((a,b)=>a+(b.valor||0),0))}</span>
            </div>
          </div>
        )}
      </div>

      <div className="summary-card" style={{ display: 'block' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
          <div className="summary-card-label" style={{ marginBottom: 0 }}>Anotações e Estrutura</div>
          {notes !== p.anotacoes && (
            <button 
              className="btn btn-sm btn-primary" 
              onClick={handleSaveNotes}
              disabled={saving}
              style={{ padding: '2px 8px', fontSize: 11 }}
            >
              {saving ? 'Salvando...' : 'Salvar Alterações'}
            </button>
          )}
        </div>
        <textarea 
          style={{ 
            width: '100%',
            minHeight: 120,
            fontSize: 13, 
            color: 'var(--text2)', 
            lineHeight: 1.6, 
            background: 'var(--bg3)', 
            padding: 12, 
            borderRadius: 'var(--radius-sm)', 
            border: '1px solid var(--border)',
            fontFamily: 'inherit',
            resize: 'vertical',
            outline: 'none',
            transition: 'border-color 0.2s'
          }}
          value={notes}
          onChange={e => setNotes(e.target.value)}
          placeholder="Adicione anotações sobre o projeto..."
          onBlur={handleSaveNotes}
        />
      </div>

      <div style={{ display: 'flex', justifyContent: 'flex-start', gap: 10 }}>
        <button className="btn btn-secondary" style={{ padding: '8px 24px' }} onClick={onEdit}>Editar Projeto</button>
      </div>
    </div>
  );
}

function PVTarefas({ p, onUpdate }) {
  const [tarefas, setTarefas] = useState(p.tarefas || []);
  const [newTask, setNewTask] = useState({ col: null, titulo: '', prio: 'Baixa' });
  const [draggedIdx, setDraggedIdx] = useState(null);
  const [dropTargetCol, setDropTargetCol] = useState(null);
  
  const [editingIdx, setEditingIdx] = useState(null);
  const [editingTitle, setEditingTitle] = useState('');

  const saveEditTask = async (idx) => {
    if (editingTitle.trim()) {
      const newTs = tarefas.map((t, i) => i === idx ? { ...t, titulo: editingTitle.trim() } : t);
      await save(newTs);
    }
    setEditingIdx(null);
  };

  const save = async (newTs) => {
    setTarefas(newTs);
    await onUpdate(newTs);
  };

  const addTask = async () => {
    if (!newTask.titulo || !newTask.col) return;
    const t = { titulo: newTask.titulo, prio: newTask.prio, col: newTask.col, criadoEm: new Date().toISOString() };
    setNewTask({ col: null, titulo: '', prio: 'Baixa' });
    await save([...tarefas, t]);
  };

  const delTask = async (idx) => {
    await save(tarefas.filter((_, i) => i !== idx));
  };

  const handleDragStart = (e, idx) => {
    setDraggedIdx(idx);
    e.dataTransfer.effectAllowed = 'move';
    setTimeout(() => {
      e.target.classList.add('dragging');
    }, 0);
  };

  const handleDragEnd = (e) => {
    setDraggedIdx(null);
    setDropTargetCol(null);
    e.target.classList.remove('dragging');
  };

  const handleDragOver = (e, colKey) => {
    e.preventDefault();
    setDropTargetCol(colKey);
  };

  const handleDrop = async (e, colKey) => {
    e.preventDefault();
    if (draggedIdx === null) return;
    
    const newTs = tarefas.map((t, i) => i === draggedIdx ? { ...t, col: colKey } : t);
    setDraggedIdx(null);
    setDropTargetCol(null);
    await save(newTs);
  };

  const COLS = [
    { key: 'afazer', label: 'A Fazer' },
    { key: 'andamento', label: 'Em Andamento' },
    { key: 'feito', label: 'Concluído' },
  ];

  return (
    <div className="kanban">
      {COLS.map(({ key, label }) => {
        const colItems = tarefas.map((t, i) => ({ t, i })).filter(({ t }) => t.col === key);
        const isOver = dropTargetCol === key;

        return (
          <div 
            key={key} 
            className={`kanban-col ${isOver ? 'drag-over' : ''}`}
            onDragOver={(e) => handleDragOver(e, key)}
            onDragLeave={() => setDropTargetCol(null)}
            onDrop={(e) => handleDrop(e, key)}
          >
            <div className="kanban-col-head">
              <span className="kanban-col-label">{label}</span>
              <span className="kanban-count">{colItems.length}</span>
            </div>
            {colItems.map(({ t, i }) => (
              <div 
                key={i} 
                className="kanban-card card-in"
                draggable={editingIdx !== i ? "true" : "false"}
                onDragStart={(e) => handleDragStart(e, i)}
                onDragEnd={handleDragEnd}
              >
                {editingIdx === i ? (
                  <input
                    autoFocus
                    style={{ width: '100%', marginBottom: 8, padding: '4px 6px', borderRadius: 4, border: '1px solid var(--accent)', outline: 'none', background: 'var(--bg1)', color: 'var(--text)' }}
                    value={editingTitle}
                    onChange={e => setEditingTitle(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') saveEditTask(i); if (e.key === 'Escape') setEditingIdx(null); }}
                    onBlur={() => saveEditTask(i)}
                  />
                ) : (
                  <div className="kanban-card-title" style={{ cursor: 'text' }} onClick={() => { setEditingIdx(i); setEditingTitle(t.titulo); }} title="Clique para editar">{t.titulo}</div>
                )}
                <div className="kanban-card-foot">
                  <Badge status={t.prio || 'Baixa'} />
                  <div className="kanban-card-acts" style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
                    {editingIdx === i ? (
                      <button className="row-btn" style={{ color: 'var(--green)' }} onClick={() => saveEditTask(i)} title="Salvar">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 14, height: 14 }}><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                    ) : (
                      <>
                        <button className="row-btn mobile-only" onClick={() => {
                           const target = key === 'afazer' ? 'andamento' : key === 'andamento' ? 'feito' : 'andamento';
                           const newTs = tarefas.map((task, idx) => idx === i ? { ...task, col: target } : task);
                           save(newTs);
                        }} title="Mover">
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}><path d="M5 12h14M12 5l7 7-7 7"/></svg>
                        </button>
                        <button className="row-btn del" onClick={() => delTask(i)} title="Remover">✕</button>
                      </>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {newTask.col === key ? (
              <div className="kanban-new-form" style={{ display: 'flex' }}>
                <input
                  autoFocus type="text" placeholder="Título da tarefa..."
                  value={newTask.titulo}
                  onChange={e => setNewTask(prev => ({ ...prev, titulo: e.target.value }))}
                  onKeyDown={e => { if (e.key === 'Enter') addTask(); if (e.key === 'Escape') setNewTask({ col: null, titulo: '', prio: 'Baixa' }); }}
                />
                <select value={newTask.prio} onChange={e => setNewTask(prev => ({ ...prev, prio: e.target.value }))}>
                  <option value="Baixa">Prioridade: Baixa</option>
                  <option value="Média">Prioridade: Média</option>
                  <option value="Alta">Prioridade: Alta</option>
                </select>
                <div className="kanban-new-btns">
                  <button className="btn btn-sm btn-primary" style={{ flex: 1 }} onClick={addTask}>Salvar</button>
                  <button className="btn btn-sm btn-secondary" onClick={() => setNewTask({ col: null, titulo: '', prio: 'Baixa' })}>X</button>
                </div>
              </div>
            ) : (
              <button className="kanban-add" onClick={() => setNewTask({ col: key, titulo: '', prio: 'Baixa' })}>+ Adicionar Tarefa</button>
            )}
          </div>
        );
      })}
    </div>
  );
}

function PVArquivos({ p, onAdd, onDel }) {
  const toast = useDash(s => s.toast);
  const [nome, setNome] = useState('');
  const [tipo, setTipo] = useState('Identidade Visual');
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const fileRef = useRef(null);

  const arquivos = p.arquivos || [];

  const handleUpload = async () => {
    if (!nome || !selectedFile) return toast('Preencha um nome e selecione o arquivo!', 'error');
    setUploading(true);
    setProgress('Preparando envio...');
    try {
      await onAdd(selectedFile, tipo, p.id);
      setNome(''); setSelectedFile(null); setProgress('');
      if (fileRef.current) fileRef.current.value = '';
    } catch (e) {
      setProgress('');
    } finally { setUploading(false); }
  };

  const getIcon = (url) => {
    const u = url || '';
    if (/\.(png|jpe?g|webp|svg|gif)/i.test(u)) return 'img';
    if (/\.(mp4|avi|mov|webm)/i.test(u)) return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:40,height:40,color:'var(--blue)'}}><rect x="2" y="2" width="20" height="20" rx="2.18" ry="2.18"/><line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="2" y1="7" x2="7" y2="7"/><line x1="2" y1="17" x2="7" y2="17"/><line x1="17" y1="17" x2="22" y2="17"/><line x1="17" y1="7" x2="22" y2="7"/></svg>;
    if (/\.(zip|rar|7z)/i.test(u)) return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:40,height:40,color:'var(--amber)'}}><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>;
    if (/\.pdf/i.test(u)) return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:40,height:40,color:'var(--red)'}}><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>;
    return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:40,height:40,color:'var(--text3)'}}><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/></svg>;
  };

  return (
    <div>
      <div className="file-upload-form">
        <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 8 }}>Upload Direto para Servidor (Hospedagem)</div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 10 }}>
          <input className="form-input" placeholder="Nome (Ex: Logo Final)" value={nome} onChange={e => setNome(e.target.value)} />
          <select className="form-select" value={tipo} onChange={e => setTipo(e.target.value)}>
            {['Identidade Visual', 'Copy / Textos', 'Fotos', 'Contrato', 'Outros'].map(t => <option key={t}>{t}</option>)}
          </select>
        </div>
        <label className="custom-file-label" style={{ marginTop: 10, cursor: 'pointer' }}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
          <span>{selectedFile ? selectedFile.name : 'Clique para selecionar o arquivo...'}</span>
          <input ref={fileRef} type="file" style={{ display: 'none' }} onChange={e => setSelectedFile(e.target.files[0] || null)} />
        </label>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 10 }}>
          <div style={{ fontSize: 12, color: 'var(--accent)', fontWeight: 500 }}>{progress}</div>
          <button className="btn btn-sm btn-primary" disabled={uploading} onClick={handleUpload}>{uploading ? 'Enviando...' : 'Upload Arquivo'}</button>
        </div>
      </div>
      <div className="files-grid">
        {!arquivos.length && <div className="dash-empty" style={{ gridColumn: '1/-1' }}>Nenhum arquivo encontrado.</div>}
        {arquivos.map((a, i) => {
          const ico = getIcon(a.url);
          return (
            <div key={i} className="file-card card-in" style={{ padding: 0, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
              {ico === 'img' ? (
                <img src={a.url} alt={a.nome} style={{ width: '100%', height: 140, objectFit: 'cover', borderRadius: 'var(--radius-sm) var(--radius-sm) 0 0', background: 'var(--bg3)', display: 'block' }} />
              ) : (
                <div style={{ marginTop: 24, marginBottom: 8, display: 'flex', justifyContent: 'center' }}>{ico}</div>
              )}
              <div style={{ padding: 16, flex: 1, display: 'flex', flexDirection: 'column' }}>
                <div className="file-card-name" style={{ marginBottom: 8 }}>
                  <a href={a.url} target="_blank" rel="noreferrer" style={{ color: 'var(--text)', textDecoration: 'none' }}>{a.nome}</a>
                </div>
                <div className="file-card-tipo" style={{ marginBottom: 'auto' }}>
                  {a.tipo} &bull; <a href={a.url} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>Baixar</a>
                </div>
                <div style={{ marginTop: 12 }}>
                  <button className="row-btn del" onClick={() => onDel(i)}>Excluir</button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useDash, sortData, fmtBRL, fmtDate } from '../store/useStore';
import { EmptyDiv } from '../components/shared';
import CustomSelect from '../components/CustomSelect';
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '../components/ui/Table';
import { FEATURES } from '../config/features';

const DEFAULT_TIPOS = ['Site', 'Landing page', 'Loja virtual', 'Sistema', 'Manutenção', 'Outro'];
const DEFAULT_ORIGENS = ['Lead (prospecção)', 'Cliente antigo', 'Indicação', 'Outro'];

function getProjetoTipo(p) {
  return (p?.tipo || p?.tipoProjeto || '').trim();
}

function getProjetoOrigem(p) {
  return (p?.origem || '').trim();
}

function getProjetoFechadoEm(p) {
  if (p?.fechadoEm) return p.fechadoEm;
  if (typeof p?.criadoEm === 'string' && p.criadoEm.includes('-')) {
    return p.criadoEm.split('T')[0];
  }
  if (p?.criadoEm?.seconds) {
    return new Date(p.criadoEm.seconds * 1000).toISOString().split('T')[0];
  }
  return '';
}

export default function ProjetosPage() {
  const data = useDash(s => s.data);
  const openModal = useDash(s => s.openModal);
  const deleteItem = useDash(s => s.deleteItem);
  const openProjectView = useDash(s => s.openProjectView);
  const selectedItems = useDash(s => s.selectedItems);
  const toggleSelect = useDash(s => s.toggleSelect);
  const selectAll = useDash(s => s.selectAll);
  const clearBulk = useDash(s => s.clearBulk);
  const bulkDelete = useDash(s => s.bulkDelete);
  const currentBulkCol = useDash(s => s.currentBulkCol);

  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('');
  const [pag, setPag] = useState('');
  const [tipoFilter, setTipoFilter] = useState('');
  const [origemFilter, setOrigemFilter] = useState('');
  const [sort, setSort] = useState('criadoDesc');
  const [colSort, setColSort] = useState(null); // { key, dir: 'asc' | 'desc' }
  const [hoveredId, setHoveredId] = useState(null);

  const tipoOptions = useMemo(() => {
    const dynamic = data.projetos.map(getProjetoTipo).filter(Boolean);
    const unique = Array.from(new Set([...DEFAULT_TIPOS, ...dynamic]));
    return [
      { value: '', label: 'Todos os tipos' },
      ...unique.map(t => ({ value: t, label: t })),
      { value: '__empty__', label: 'Não informado' },
    ];
  }, [data.projetos]);

  const origemOptions = useMemo(() => {
    const dynamic = data.projetos.map(getProjetoOrigem).filter(Boolean);
    const unique = Array.from(new Set([...DEFAULT_ORIGENS, ...dynamic]));
    return [
      { value: '', label: 'Todas as origens' },
      ...unique.map(o => ({ value: o, label: o })),
      { value: '__empty__', label: 'Não informado' },
    ];
  }, [data.projetos]);

  const handleHeaderSort = (key) => {
    setColSort(prev => {
      if (prev?.key === key) {
        return { key, dir: prev.dir === 'asc' ? 'desc' : 'asc' };
      }
      return { key, dir: key === 'valor' || key === 'fechadoEm' ? 'desc' : 'asc' };
    });
  };

  const handleSelectSortChange = (e) => {
    setColSort(null);
    setSort(e.target.value);
  };

  const handleDuplicate = async (p) => {
    if (window.confirm('Duplicar este projeto?')) {
      const { id, ...copia } = p;
      copia.descricao = (copia.descricao || '') + ' (Cópia)';
      copia.status = 'Em andamento';
      copia.criadoEm = undefined;
      await useDash.getState().saveProjeto(copia);
    }
  };

  const { list, allIds } = useMemo(() => {
    const q = search.trim().toLowerCase();
    let filtered = data.projetos.filter(p => {
      const pTipo = getProjetoTipo(p);
      const pOrigem = getProjetoOrigem(p);
      if (q) {
        const hay = `${p.cliente || ''} ${p.descricao || ''} ${pTipo} ${pOrigem} ${p.siteUrl || ''}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      if (status && p.status !== status) return false;
      if (pag && p.pagamento !== pag) return false;
      if (tipoFilter) {
        if (tipoFilter === '__empty__' && pTipo) return false;
        if (tipoFilter !== '__empty__' && pTipo !== tipoFilter) return false;
      }
      if (origemFilter) {
        if (origemFilter === '__empty__' && pOrigem) return false;
        if (origemFilter !== '__empty__' && pOrigem !== origemFilter) return false;
      }
      return true;
    });

    if (colSort) {
      const { key, dir } = colSort;
      const mult = dir === 'asc' ? 1 : -1;
      filtered = [...filtered].sort((a, b) => {
        if (key === 'valor') {
          return ((Number(a.valor) || 0) - (Number(b.valor) || 0)) * mult;
        }
        if (key === 'fechadoEm') {
          const da = getProjetoFechadoEm(a) || '';
          const db = getProjetoFechadoEm(b) || '';
          return da.localeCompare(db) * mult;
        }
        const getVal = (item) => {
          switch (key) {
            case 'cliente': return item.cliente || '';
            case 'descricao': return item.descricao || '';
            case 'tipo': return getProjetoTipo(item) || 'zzz';
            case 'status': return item.status || '';
            case 'pagamento': return item.pagamento || '';
            case 'nf': return item.nf || 'nao';
            case 'origem': return getProjetoOrigem(item) || 'zzz';
            default: return '';
          }
        };
        return getVal(a).localeCompare(getVal(b), 'pt-BR', { sensitivity: 'base' }) * mult;
      });
    } else {
      filtered = sortData(filtered, sort);
    }

    return { list: filtered, allIds: filtered.map(x => x.id).join(',') };
  }, [data.projetos, search, status, pag, tipoFilter, origemFilter, sort, colSort]);

  const allChecked = selectedItems.length === list.length && list.length > 0;

  const statusColors = {
    'Em andamento': 'var(--blue)',
    'Aguardando cliente': 'var(--amber)',
    'Aguardando Aprovação': 'var(--purple)',
    'Concluído': 'var(--green)',
    'Pausado': 'var(--text3)',
    'Cancelado': 'var(--red)',
  };
  const pagColors = {
    'Pago': 'var(--green)',
    'Parcial (50%)': 'var(--amber)',
    'Pendente': 'var(--amber)',
  };

  const getNfDisplay = (nfVal) => {
    if (nfVal === 'sim') return { label: 'Emitida', color: 'var(--green)', bg: 'rgba(16, 185, 129, 0.12)' };
    if (nfVal === 'pendente') return { label: 'Pendente', color: 'var(--amber)', bg: 'rgba(245, 158, 11, 0.12)' };
    return { label: 'Não', color: 'var(--text3)', bg: 'transparent' };
  };

  return (
    <div>
      <div className="page-header">
        <div className="page-title">Projetos</div>
        <div className="page-actions">
          {selectedItems.length > 0 && currentBulkCol === 'projetos' && (
            <div id="proj-bulk-actions" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span style={{ fontSize: 13, fontWeight: 500, color: 'var(--text)' }}>{selectedItems.length} selecionado(s)</span>
              <button className="btn btn-sm btn-danger" onClick={bulkDelete}>Excluir</button>
              <button className="btn btn-sm btn-secondary" style={{ padding: '0 6px' }} onClick={clearBulk}>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}><path d="M18 6 6 18M6 6l12 12"/></svg>
              </button>
            </div>
          )}
          {/* Desktop: text button */}
          <button className="btn btn-primary desktop-only" onClick={() => openModal('projeto')} style={{ paddingLeft: 14 }}>
            <div style={{ position: 'relative', width: 14, height: 14, marginRight: 6 }}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}><path d="M12 5v14M5 12h14" /></svg>
            </div>
            Novo Projeto
          </button>
          {/* Mobile: icon only */}
          <button className="btn-icon mobile-only btn-icon-accent" onClick={() => openModal('projeto')} title="Novo Projeto" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ position: 'relative', width: 16, height: 16 }}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}><path d="M12 5v14M5 12h14" /></svg>
            </div>
          </button>
        </div>
      </div>

      <div className="filters" style={{ alignItems: 'center' }}>
        <div className="search-wrap">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
          <input className="filter-input" placeholder="Buscar projeto ou cliente..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <CustomSelect
          variant="filter"
          value={status}
          onChange={e => setStatus(e.target.value)}
          placeholder="Todos os status"
          options={[
            { value: '', label: 'Todos os status' },
            ...['Em andamento', 'Aguardando cliente', 'Aguardando Aprovação', 'Concluído', 'Pausado', 'Cancelado'].map(s => ({ value: s, label: s }))
          ]}
        />
        <CustomSelect
          variant="filter"
          value={pag}
          onChange={e => setPag(e.target.value)}
          placeholder="Todos pagamentos"
          options={[
            { value: '', label: 'Todos pagamentos' },
            ...['Pendente', 'Parcial (50%)', 'Pago'].map(s => ({ value: s, label: s }))
          ]}
        />
        <CustomSelect
          variant="filter"
          value={tipoFilter}
          onChange={e => setTipoFilter(e.target.value)}
          placeholder="Todos os tipos"
          options={tipoOptions}
        />
        <CustomSelect
          variant="filter"
          value={origemFilter}
          onChange={e => setOrigemFilter(e.target.value)}
          placeholder="Todas as origens"
          options={origemOptions}
        />
        <CustomSelect
          variant="filter"
          value={sort}
          onChange={handleSelectSortChange}
          options={[
            { value: 'criadoDesc', label: 'Mais recentes' },
            { value: 'criadoAsc', label: 'Mais antigos' },
            { value: 'nomeAz', label: 'Nome A-Z' },
            { value: 'valorDesc', label: 'Maior valor' },
            { value: 'valorAsc', label: 'Menor valor' }
          ]}
        />
      </div>

      {!list.length ? (
        data.projetos.length === 0 ? (
          <div style={{ padding: '20px 0', display: 'flex', justifyContent: 'flex-start' }}>
            <div 
              className="proj-card empty card-in" 
              onClick={() => openModal('projeto')}
            >
              <div style={{ 
                width: 64, 
                height: 64, 
                borderRadius: '50%', 
                background: 'var(--accent-bg)', 
                position: 'relative',
                color: 'var(--accent)',
                marginBottom: 16,
                flexShrink: 0
              }}>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', width: 32, height: 32 }}>
                  <path d="M12 5v14M5 12h14" />
                </svg>
              </div>
              <div>
                <div style={{ fontSize: 17, fontWeight: 500, color: 'var(--text)', marginBottom: 6 }}>Comece seu primeiro projeto</div>
                <div style={{ fontSize: 13, color: 'var(--text3)', lineHeight: 1.5 }}>Organize seu histórico, prazos e pagamentos em um só lugar.</div>
              </div>
              <div className="btn btn-primary" style={{ marginTop: 8, pointerEvents: 'none', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', padding: '10px 20px' }}>
                <div style={{ position: 'relative', width: 14, height: 14, marginRight: 8 }}>
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}>
                    <path d="M12 5v14M5 12h14" />
                  </svg>
                </div>
                <span style={{ lineHeight: 1 }}>Novo Projeto</span>
              </div>
            </div>
          </div>
        ) : (
          <EmptyDiv msg="Nenhum projeto encontrado" />
        )
      ) : (
        <>
          {/* DESKTOP: Tabela de histórico */}
          <div className="desktop-only">
            <Table>
              <TableHeader>
                <tr>
                  <TableHead style={{ width: 36, padding: '10px 8px 10px 14px' }}>
                    <input
                      type="checkbox"
                      checked={allChecked}
                      onChange={() => selectAll('projetos', allIds)}
                      title={`Selecionar todos (${list.length})`}
                    />
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'cliente'}
                    sortDirection={colSort?.key === 'cliente' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('cliente')}
                  >
                    Cliente
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'descricao'}
                    sortDirection={colSort?.key === 'descricao' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('descricao')}
                  >
                    Projeto
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'tipo'}
                    sortDirection={colSort?.key === 'tipo' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('tipo')}
                  >
                    Tipo
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'valor'}
                    sortDirection={colSort?.key === 'valor' ? colSort.dir : 'desc'}
                    onSort={() => handleHeaderSort('valor')}
                    style={{ textAlign: 'right' }}
                  >
                    Valor
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'fechadoEm'}
                    sortDirection={colSort?.key === 'fechadoEm' ? colSort.dir : 'desc'}
                    onSort={() => handleHeaderSort('fechadoEm')}
                  >
                    Fechado em
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'status'}
                    sortDirection={colSort?.key === 'status' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('status')}
                  >
                    Status
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'pagamento'}
                    sortDirection={colSort?.key === 'pagamento' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('pagamento')}
                  >
                    Pagamento
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'nf'}
                    sortDirection={colSort?.key === 'nf' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('nf')}
                  >
                    NF
                  </TableHead>
                  <TableHead
                    sortable
                    sorted={colSort?.key === 'origem'}
                    sortDirection={colSort?.key === 'origem' ? colSort.dir : 'asc'}
                    onSort={() => handleHeaderSort('origem')}
                  >
                    Origem
                  </TableHead>
                  <TableHead>Site</TableHead>
                  <TableHead style={{ width: 128, textAlign: 'right' }}>Ações</TableHead>
                </tr>
              </TableHeader>
              <TableBody>
                {list.map(p => {
                  const sc = statusColors[p.status] || 'var(--text3)';
                  const pc = pagColors[p.pagamento] || 'var(--text3)';
                  const isSelected = selectedItems.includes(p.id);
                  const isHovered = hoveredId === p.id;

                  const now = new Date();
                  const tsPrazo = p.prazo ? new Date(p.prazo + 'T12:00:00').getTime() : null;
                  const isAtrasado = tsPrazo && tsPrazo < now.getTime() && !['Concluído', 'Cancelado', 'Aguardando Aprovação'].includes(p.status);
                  const diasAtraso = isAtrasado ? Math.ceil((now.getTime() - tsPrazo) / (1000 * 3600 * 24)) : 0;

                  const pTipo = getProjetoTipo(p);
                  const pOrigem = getProjetoOrigem(p);
                  const fechadoEmStr = getProjetoFechadoEm(p);
                  const nfInfo = getNfDisplay(p.nf);
                  const siteHref = p.siteUrl ? (/^https?:\/\//i.test(p.siteUrl) ? p.siteUrl : `https://${p.siteUrl}`) : '';
                  const siteClean = p.siteUrl ? p.siteUrl.replace(/^https?:\/\//i, '').replace(/\/$/, '') : '';

                  return (
                    <TableRow
                      key={p.id}
                      active={isSelected}
                      onMouseEnter={() => setHoveredId(p.id)}
                      onMouseLeave={() => setHoveredId(null)}
                      onClick={() => openProjectView(p.id)}
                      style={{
                        cursor: 'pointer',
                        background: isSelected
                          ? 'var(--accent-bg)'
                          : isHovered
                          ? 'var(--bg3)'
                          : undefined,
                      }}
                    >
                      <TableCell
                        style={{ padding: '9px 8px 9px 14px' }}
                        onClick={e => e.stopPropagation()}
                      >
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleSelect('projetos', p.id)}
                        />
                      </TableCell>
                      <TableCell style={{ fontWeight: 500, whiteSpace: 'nowrap' }}>
                        {p.cliente || '—'}
                      </TableCell>
                      <TableCell>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                          <span style={{ fontWeight: 500, color: 'var(--text)' }}>
                            {p.descricao || 'Sem projeto'}
                          </span>
                          {p.prazo && (
                            <span
                              style={{
                                fontSize: 11,
                                color: isAtrasado ? 'var(--red)' : 'var(--text3)',
                                fontWeight: isAtrasado ? 600 : 400,
                              }}
                            >
                              {isAtrasado
                                ? `Prazo ${fmtDate(p.prazo)} • Atrasado ${diasAtraso}d`
                                : `Prazo: ${fmtDate(p.prazo)}`}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell style={{ color: pTipo ? 'var(--text2)' : 'var(--text3)', whiteSpace: 'nowrap' }}>
                        {pTipo || '—'}
                      </TableCell>
                      <TableCell align="right" mono style={{ fontWeight: 500, whiteSpace: 'nowrap' }}>
                        {fmtBRL(p.valor)}
                      </TableCell>
                      <TableCell mono style={{ color: fechadoEmStr ? 'var(--text2)' : 'var(--text3)', whiteSpace: 'nowrap', fontSize: 12 }}>
                        {fechadoEmStr ? fmtDate(fechadoEmStr) : '—'}
                      </TableCell>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>
                        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                          <span
                            className="indicator-glow-wrap"
                            style={{
                              display: 'inline-flex',
                              alignItems: 'center',
                              fontSize: 11,
                              fontWeight: 500,
                              color: sc,
                              background: sc + '1a',
                              borderRadius: 99,
                              padding: '3px 9px',
                            }}
                          >
                            <span className="indicator-glow"></span>
                            {p.status || 'Em andamento'}
                          </span>
                          {isAtrasado && (
                            <span
                              title={`Prazo vencido em ${fmtDate(p.prazo)} (${diasAtraso} dia(s) de atraso)`}
                              style={{
                                fontSize: 10,
                                fontWeight: 600,
                                color: 'var(--red)',
                                background: 'var(--red-bg)',
                                border: '1px solid rgba(239,68,68,0.25)',
                                borderRadius: 99,
                                padding: '2px 6px',
                              }}
                            >
                              Atrasado {diasAtraso}d
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>
                        <span
                          style={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 4,
                            fontSize: 11,
                            fontWeight: 500,
                            color: pc,
                            background: pc + '1a',
                            borderRadius: 99,
                            padding: '3px 9px',
                          }}
                        >
                          {p.pagamento || 'Pendente'}
                        </span>
                      </TableCell>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>
                        <span
                          style={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            fontSize: 11,
                            fontWeight: 500,
                            color: nfInfo.color,
                            background: nfInfo.bg,
                            borderRadius: 99,
                            padding: nfInfo.bg !== 'transparent' ? '2px 8px' : 0,
                          }}
                        >
                          {nfInfo.label}
                        </span>
                      </TableCell>
                      <TableCell style={{ color: pOrigem ? 'var(--text2)' : 'var(--text3)', whiteSpace: 'nowrap' }}>
                        {pOrigem || '—'}
                      </TableCell>
                      <TableCell onClick={e => e.stopPropagation()} style={{ maxWidth: 160, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {siteHref ? (
                          <a
                            href={siteHref}
                            target="_blank"
                            rel="noreferrer"
                            title={p.siteUrl}
                            style={{
                              color: 'var(--accent)',
                              textDecoration: 'none',
                              display: 'inline-flex',
                              alignItems: 'center',
                              gap: 4,
                              fontSize: 12,
                              fontWeight: 500,
                            }}
                          >
                            <span style={{ maxWidth: 125, overflow: 'hidden', textOverflow: 'ellipsis' }}>{siteClean}</span>
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 12, height: 12, flexShrink: 0 }}>
                              <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/>
                            </svg>
                          </a>
                        ) : (
                          <span style={{ color: 'var(--text3)' }}>—</span>
                        )}
                      </TableCell>
                      <TableCell
                        align="right"
                        onClick={e => e.stopPropagation()}
                        style={{ whiteSpace: 'nowrap', padding: '6px 12px' }}
                      >
                        <div
                          style={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 4,
                            opacity: isHovered || isSelected ? 1 : 0.25,
                            transition: 'opacity 120ms ease',
                          }}
                        >
