import { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useDash } from '../store/useStore';

// ─── Animation Variants ──────────────────────────────────────────────────────
const fadeUp = {
  hidden: { opacity: 0, y: 16 },
  visible: (i = 0) => ({
    opacity: 1, y: 0,
    transition: { duration: 0.4, delay: i * 0.06, ease: [0.22, 1, 0.36, 1] },
  }),
};

// ─── Status Config ────────────────────────────────────────────────────────────
const STATUS_CONFIG = {
  online:  { label: 'Online',   color: 'var(--green)', bg: 'var(--green-bg)' },
  offline: { label: 'Offline',  color: 'var(--red)',   bg: 'var(--red-bg)' },
  pending: { label: 'Pendente', color: 'var(--text3)', bg: 'var(--bg4)' },
  paused:  { label: 'Pausado',  color: 'var(--amber)', bg: 'var(--amber-bg)' },
};

// ─── Helpers ──────────────────────────────────────────────────────────────────
function formatLastChecked(ts) {
  if (!ts) return null;
  const d = new Date(ts * 1000);
  const now = new Date();
  const diffMin = Math.floor((now - d) / 60000);
  if (diffMin < 1) return 'agora mesmo';
  if (diffMin < 60) return `há ${diffMin} min`;
  if (diffMin < 1440) return `há ${Math.floor(diffMin / 60)}h`;
  return d.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
}

function cleanDomain(domain) {
  return domain.replace(/^https?:\/\//, '').replace(/\/$/, '');
}

// ─── Status Badge ─────────────────────────────────────────────────────────────
function StatusBadge({ status }) {
  const cfg = STATUS_CONFIG[status] || STATUS_CONFIG.pending;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 6,
      padding: '4px 10px', borderRadius: 99,
      background: cfg.bg, color: cfg.color,
      fontSize: 12, fontWeight: 600, letterSpacing: '.02em',
      border: `1px solid color-mix(in srgb, ${cfg.color} 20%, transparent)`,
    }}>
      <span style={{ 
        width: 6, 
        height: 6, 
        borderRadius: '50%', 
        background: status === 'pending' ? 'transparent' : cfg.color, 
        border: status === 'pending' ? `1.5px solid ${cfg.color}` : 'none',
        display: 'inline-block' 
      }} />
      {cfg.label}
    </span>
  );
}

// ─── Pulse Dot ────────────────────────────────────────────────────────────────
function PulseDot({ status }) {
  const cfg = STATUS_CONFIG[status] || STATUS_CONFIG.pending;
  return (
    <span style={{ position: 'relative', display: 'inline-flex', width: 10, height: 10, flexShrink: 0 }}>
      {status === 'online' && (
        <span style={{
          position: 'absolute', inset: -4, borderRadius: '50%',
          background: cfg.color, opacity: 0.15,
        }} />
      )}
      <span style={{
        position: 'relative', width: 10, height: 10, borderRadius: '50%',
        background: status === 'pending' ? 'transparent' : cfg.color,
        border: status === 'pending' ? '2px solid var(--text3)' : 'none',
      }} />
    </span>
  );
}

// ─── Summary KPI ─────────────────────────────────────────────────────────────
function KpiChip({ label, value, color, bg, index }) {
  return (
    <motion.div
      custom={index}
      variants={fadeUp}
      initial="hidden"
      animate="visible"
      style={{
        background: 'var(--bg2)', border: '1px solid var(--border)',
        borderRadius: 'var(--radius)', padding: '14px 18px',
        display: 'flex', flexDirection: 'column', gap: 6,
        minWidth: 120, flex: 1,
      }}
    >
      <span style={{ fontSize: 11, color: 'var(--text3)', fontWeight: 500, textTransform: 'uppercase', letterSpacing: '.08em' }}>
        {label}
      </span>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ width: 8, height: 8, borderRadius: '50%', background: color, boxShadow: `0 0 0 4px ${bg}`, flexShrink: 0 }} />
        <span style={{ fontSize: 26, fontWeight: 500, color: 'var(--text)', fontFamily: 'var(--sans)', letterSpacing: '-.02em' }}>
          {value}
        </span>
      </div>
    </motion.div>
  );
}

// ─── Add Monitor Form ─────────────────────────────────────────────────────────
function AddMonitorForm({ onAdd, loading }) {
  const [domain, setDomain] = useState('');
  const [label, setLabel] = useState('');
  const inputRef = useRef();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!domain.trim()) return;
    const ok = await onAdd(domain.trim(), label.trim());
    if (ok) { setDomain(''); setLabel(''); inputRef.current?.focus(); }
  };

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap' }}>
      <div className="form-group" style={{ margin: 0, flex: '2 1 200px' }}>
        <label className="form-label">URL do Site</label>
        <div style={{ position: 'relative' }}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
            style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14, color: 'var(--text3)', pointerEvents: 'none' }}>
            <circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
          </svg>
          <input
            ref={inputRef}
            className="form-input"
            style={{ paddingLeft: 36 }}
            placeholder="dominio.com.br"
            value={domain}
            onChange={e => setDomain(e.target.value)}
            required
            autoComplete="off"
          />
        </div>
      </div>
      <div className="form-group" style={{ margin: 0, flex: '1 1 140px' }}>
        <label className="form-label">Apelido <span style={{ color: 'var(--text3)', fontWeight: 400 }}>(opcional)</span></label>
        <input
          className="form-input"
          placeholder="ex: Loja Principal"
          value={label}
          onChange={e => setLabel(e.target.value)}
        />
      </div>
      <button
        type="submit"
        className="btn btn-primary"
        style={{ height: 44, paddingInline: 20, flexShrink: 0, display: 'flex', alignItems: 'center', gap: 7 }}
        disabled={loading}
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 14, height: 14 }}>
          <path d="M12 5v14M5 12h14"/>
        </svg>
        Adicionar
      </button>
    </form>
  );
}

// ─── Monitor Card ─────────────────────────────────────────────────────────────
function MonitorCard({ monitor, onDelete, onUpdate }) {
  const [confirming, setConfirming] = useState(false);
  const [editing, setEditing] = useState(false);
  const [editDomain, setEditDomain] = useState(() => cleanDomain(monitor.domain || ''));
  const [editLabel, setEditLabel] = useState(() => monitor.label || '');
  const [saving, setSaving] = useState(false);

  const isPaused = Boolean(monitor.paused || monitor.status === 'paused');
  const effectiveStatus = isPaused ? 'paused' : (monitor.status || 'pending');

  const handleDelete = () => {
    if (confirming) { onDelete(monitor.id); }
    else { setConfirming(true); setTimeout(() => setConfirming(false), 2500); }
  };

  const handleStartEdit = () => {
    setEditDomain(cleanDomain(monitor.domain || ''));
    setEditLabel(monitor.label || '');
    setEditing(true);
  };

  const handleSaveEdit = async (e) => {
    e?.preventDefault();
    if (!editDomain.trim()) return;
    setSaving(true);
    const ok = await onUpdate(monitor.id, {
      domain: editDomain.trim(),
      label: editLabel.trim(),
    });
    setSaving(false);
    if (ok) setEditing(false);
  };

  const handleTogglePause = async () => {
    setSaving(true);
    await onUpdate(monitor.id, { paused: !isPaused });
    setSaving(false);
  };

  const displayName = monitor.label || cleanDomain(monitor.domain);
  const displayUrl = cleanDomain(monitor.domain);
  const lastChecked = formatLastChecked(monitor.lastChecked);

  const statusGlow = effectiveStatus === 'online'
    ? 'radial-gradient(ellipse 200px 140px at 95% 15%, rgba(34, 197, 94, 0.15) 0%, transparent 75%), var(--bg2)'
    : effectiveStatus === 'offline'
    ? 'radial-gradient(ellipse 200px 140px at 95% 15%, rgba(239, 68, 68, 0.2) 0%, transparent 75%), var(--bg2)'
    : 'radial-gradient(ellipse 200px 140px at 95% 15%, rgba(148, 163, 184, 0.09) 0%, transparent 75%), var(--bg2)';

  const borderColor = effectiveStatus === 'online'
    ? 'rgba(34, 197, 94, 0.22)'
    : effectiveStatus === 'offline'
    ? 'rgba(239, 68, 68, 0.32)'
    : 'rgba(255, 255, 255, 0.08)';

  const shadowGlow = effectiveStatus === 'online'
    ? '0 10px 28px -8px rgba(0, 0, 0, 0.5), 0 0 20px -4px rgba(34, 197, 94, 0.12)'
    : effectiveStatus === 'offline'
    ? '0 10px 28px -8px rgba(0, 0, 0, 0.5), 0 0 22px -4px rgba(239, 68, 68, 0.18)'
    : '0 10px 28px -8px rgba(0, 0, 0, 0.4)';

  return (
    <motion.div
      layout
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95 }}
      whileHover={{ y: -2, transition: { duration: 0.2 } }}
      transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
      style={{
        background: statusGlow,
        border: 'none',
        borderRadius: 'var(--radius)',
        padding: '20px',
        display: 'flex',
        flexDirection: 'column',
        gap: '14px',
        position: 'relative',
        boxShadow: shadowGlow,
        overflow: 'hidden',
        opacity: isPaused ? 0.78 : 1,
      }}
    >
      {/* Top Section: Domain info & Status */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, minWidth: 0, flex: 1 }}>
          <PulseDot status={effectiveStatus} />
          <div style={{ minWidth: 0, flex: 1 }}>
            {editing ? (
              <form onSubmit={handleSaveEdit} style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                <input
                  className="form-input"
                  style={{ height: 30, fontSize: 12.5, padding: '4px 8px' }}
                  placeholder="Apelido (ex: Loja Principal)"
                  value={editLabel}
                  onChange={e => setEditLabel(e.target.value)}
                  autoFocus
                />
                <input
                  className="form-input"
                  style={{ height: 30, fontSize: 12, padding: '4px 8px', fontFamily: 'var(--mono)' }}
                  placeholder="dominio.com.br"
                  value={editDomain}
                  onChange={e => setEditDomain(e.target.value)}
                  required
                />
                <div style={{ display: 'flex', gap: 6, marginTop: 2 }}>
                  <button type="submit" className="btn btn-primary btn-xs" disabled={saving}>
                    {saving ? 'Salvando...' : 'Salvar'}
                  </button>
                  <button type="button" className="btn btn-ghost btn-xs" onClick={() => setEditing(false)} disabled={saving}>
                    Cancelar
                  </button>
                </div>
              </form>
            ) : (
              <>
                <div style={{
                  fontSize: 15, fontWeight: 600, color: 'var(--text)',
                  whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis'
                }}>
                  {displayName}
                </div>
                {monitor.label && (
                  <div style={{
                    fontSize: 12, color: 'var(--text3)', marginTop: 2,
                    whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis'
                  }}>
                    {displayUrl}
                  </div>
                )}
              </>
            )}
          </div>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 6, flexShrink: 0 }}>
          <StatusBadge status={effectiveStatus} />
          {!isPaused && monitor.httpCode != null && monitor.httpCode > 0 && (
            <span style={{
              fontSize: 10,
              fontWeight: 600,
              fontFamily: 'monospace',
              padding: '2px 7px',
              borderRadius: 5,
              background: monitor.httpCode >= 200 && monitor.httpCode < 400 ? 'rgba(34, 197, 94, 0.1)' : 'rgba(239, 68, 68, 0.12)',
              color: monitor.httpCode >= 200 && monitor.httpCode < 400 ? 'var(--green)' : 'var(--red)',
              border: monitor.httpCode >= 200 && monitor.httpCode < 400 ? '1px solid rgba(34, 197, 94, 0.2)' : '1px solid rgba(239, 68, 68, 0.25)',
              letterSpacing: '.02em'
            }}>
              HTTP {monitor.httpCode}
            </span>
          )}
        </div>
      </div>

      {/* Diagnostic Alert Box */}
      {!isPaused && monitor.errorDetail && (
        <div style={{
          background: 'rgba(239, 68, 68, 0.08)',
          border: '1px solid rgba(239, 68, 68, 0.22)',
          borderRadius: 8,
          padding: '10px 12px',
          display: 'flex',
          alignItems: 'flex-start',
          gap: 9,
          color: '#fca5a5',
          fontSize: 11.5,
          lineHeight: 1.45,
        }}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14, flexShrink: 0, marginTop: 2, color: '#ef4444' }}>
            <circle cx="12" cy="12" r="10"/>
            <line x1="12" y1="8" x2="12" y2="12"/>
            <line x1="12" y1="16" x2="12.01" y2="16"/>
          </svg>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 600, color: '#f87171', marginBottom: 2 }}>Diagnóstico:</div>
            <div style={{ color: 'var(--text2)' }}>{monitor.errorDetail}</div>
          </div>
        </div>
      )}

      {/* Elegant Divider */}
      <div style={{
        height: 1,
        width: '100%',
        background: 'linear-gradient(90deg, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0.03) 80%, transparent 100%)',
      }} />

      {/* Bottom Section: Metrics & Actions */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: 'auto' }}>
        <div>
          <div style={{ fontSize: 11, color: 'var(--text3)', textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 4, fontWeight: 500 }}>
            Tempo de Resposta
          </div>
          {!isPaused && monitor.responseTime != null ? (
            <div style={{
              fontSize: 16, fontFamily: 'var(--sans)', fontWeight: 600,
              color: monitor.responseTime < 500 ? 'var(--green)' : monitor.responseTime < 1500 ? 'var(--amber)' : 'var(--red)',
              display: 'flex', alignItems: 'baseline', gap: 2
            }}>
              {monitor.responseTime}
              <span style={{ fontSize: 12, color: 'var(--text3)', fontWeight: 500 }}>ms</span>
            </div>
          ) : (
            <div style={{ color: 'var(--text3)', fontSize: 15 }}>{isPaused ? 'Pausado' : '—'}</div>
          )}
          <div style={{ fontSize: 11, color: 'var(--text3)', marginTop: 4, display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
            <span>
              {isPaused
                ? 'Ignorado pelo cron até retomar'
                : `Última verificação: ${lastChecked || 'Aguardando verificação...'}`}
            </span>
            {!isPaused && monitor.attempts != null && (
              <span style={{
                fontSize: 10,
                fontWeight: 600,
                padding: '1px 6px',
                borderRadius: 4,
                background: monitor.status === 'offline' ? 'rgba(239, 68, 68, 0.12)' : 'var(--bg3)',
                color: monitor.status === 'offline' ? 'var(--red)' : 'var(--text3)',
                border: monitor.status === 'offline' ? '1px solid rgba(239, 68, 68, 0.25)' : '1px solid var(--border)'
              }}>
                {monitor.status === 'offline' 
                  ? `${monitor.attempts}/3 falharam` 
                  : monitor.attempts > 1 
                  ? `Recuperado na tentativa ${monitor.attempts}/3` 
                  : '1/3 tentativa'}
              </span>
            )}
          </div>
        </div>

        <div style={{ display: 'flex', gap: 6 }}>
          <button
            type="button"
            className="btn-icon"
            title={isPaused ? 'Retomar monitoramento' : 'Pausar monitoramento'}
            onClick={handleTogglePause}
            disabled={saving}
            style={{
              background: isPaused ? 'var(--amber-bg)' : 'var(--bg3)',
              color: isPaused ? 'var(--amber)' : 'var(--text3)',
              border: 'none',
              width: 32,
              height: 32,
              borderRadius: 8
            }}
          >
            {isPaused ? (
              <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: 13, height: 13 }}>
                <polygon points="6 4 20 12 6 20 6 4"/>
              </svg>
            ) : (
              <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: 13, height: 13 }}>
                <rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/>
              </svg>
            )}
          </button>
          <button
            type="button"
            className="btn-icon"
            title="Editar URL e apelido"
            onClick={handleStartEdit}
            style={{
              background: editing ? 'var(--accent-bg)' : 'var(--bg3)',
              color: editing ? 'var(--accent)' : 'var(--text3)',
              border: 'none',
              width: 32,
              height: 32,
              borderRadius: 8
            }}
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
              <path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>
            </svg>
          </button>
          <a
            href={monitor.domain}
            target="_blank"
            rel="noopener noreferrer"
            className="btn-icon"
            title="Abrir site em nova aba"
            style={{
              background: 'var(--bg3)',
              border: 'none',
              width: 32,
              height: 32,
              borderRadius: 8
            }}
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
              <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6"/>
              <polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/>
            </svg>
          </a>
          <button
            className={`btn-icon ${confirming ? 'active' : ''}`}
            title={confirming ? 'Clique novamente para EXCLUIR' : 'Excluir monitor'}
            onClick={handleDelete}
            style={{
              background: confirming ? 'var(--red)' : 'var(--bg3)',
              border: 'none',
              color: confirming ? '#fff' : 'var(--text3)',
              width: confirming ? 'auto' : 32,
              height: 32,
              borderRadius: 8,
              padding: confirming ? '0 12px' : 0,
              gap: 6
            }}
          >
            {confirming ? (
              <>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{ width: 13, height: 13 }}>
                  <polyline points="3 6 5 6 21 6"/>
                  <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
                </svg>
                <span style={{ fontSize: 12, fontWeight: 600 }}>Confirmar</span>
              </>
            ) : (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ width: 14, height: 14 }}>
                <polyline points="3 6 5 6 21 6"/>
                <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
                <path d="M10 11v6M14 11v6M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
              </svg>
            )}
          </button>
        </div>
      </div>
    </motion.div>
  );
}

// ─── Loading State ──────────────────────────────────────────────────────────────
function LoadingUptime() {
  return (
    <div style={{ padding: '60px 24px', textAlign: 'center', color: 'var(--text3)', gridColumn: '1 / -1' }}>
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
        style={{ width: 36, height: 36, margin: '0 auto 16px', display: 'block', color: 'var(--text3)', animation: 'spin 1s linear infinite' }}>
        <path d="M21 12a9 9 0 1 1-2.22-5.9M21 3v4h-4"/>
      </svg>
      <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--text2)' }}>
        Carregando monitores...
      </div>
    </div>
  );
}

// ─── Empty State ──────────────────────────────────────────────────────────────
function EmptyUptime() {
  return (
    <div style={{ padding: '60px 24px', textAlign: 'center', color: 'var(--text3)', gridColumn: '1 / -1' }}>
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2"
        style={{ width: 48, height: 48, margin: '0 auto 16px', display: 'block', opacity: 0.3 }}>
        <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
