    } else {
      set(s => ({ realData: { ...s.realData, leads: s.realData.leads.map(l => l.id === leadId ? { ...l, qualChips: nextChips, modificadoEm: nowISO } : l) } }));
      updateDoc(uDoc('leads', leadId), { qualChips: nextChips, modificadoEm: serverTimestamp() }).catch(e => toast('Erro ao atualizar qualificação: ' + e.message, 'error'));
    }
    get()._refreshData();
  },

  bulkEditLeads: async (field, value) => {
    const { selectedItems, showConfirm, toast, clearBulk, data, deleteFile } = get();
    if (!selectedItems.length || !value) return;
    if (!await showConfirm(`Alterar ${field === 'status' ? 'status' : 'nicho'} para "${value}"?`, `Isso afetará ${selectedItems.length} lead(s) selecionado(s).`, false)) return;

    const ids = [...selectedItems];
    const nowISO = new Date().toISOString();

    const realIds = ids.filter(id => id && !id.toString().startsWith('m-'));
    const mockIds = ids.filter(id => id && id.toString().startsWith('m-'));

    const isPerdido = field === 'status' && value === 'Perdido';

    if (realIds.length) {
      if (isPerdido) {
        for (const id of realIds) {
          const lead = data.leads.find(l => l.id === id);
          const screenshotPath = lead?.prequalData?.screenshotPath;
          if (screenshotPath) {
            await deleteFile(screenshotPath).catch(e => console.warn('[bulkEditLeads] Falha ao deletar screenshot:', e));
          }
        }
      }

      set(s => ({
        realData: {
          ...s.realData,
          leads: s.realData.leads.map(l => {
            if (realIds.includes(l.id)) {
              const updated = { ...l, [field]: value, modificadoEm: nowISO };
              // ── Fase 1.3: Gravar historicoStatus em bulk ───────────────────
              if (field === 'status' && value !== l.status) {
                const historicoBase = getHistoricoStatus(l);
                updated.historicoStatus = [...historicoBase, buildHistoricoEntry(l.status, value)];
              }
              if (isPerdido && updated.prequalData) {
                updated.prequalData = { ...updated.prequalData, screenshotUrl: null, screenshotPath: null };
              }
              return updated;
            }
            return l;
          })
        }
      }));
    }
    if (mockIds.length) {
      set(s => ({
        mockData: {
          ...s.mockData,
          leads: s.mockData.leads.map(l => {
            if (mockIds.includes(l.id)) {
              const updated = { ...l, [field]: value, modificadoEm: nowISO };
              if (field === 'status' && value !== l.status) {
                const historicoBase = getHistoricoStatus(l);
                updated.historicoStatus = [...historicoBase, buildHistoricoEntry(l.status, value)];
              }
              if (isPerdido && updated.prequalData) {
                updated.prequalData = { ...updated.prequalData, screenshotUrl: null, screenshotPath: null };
              }
              return updated;
            }
            return l;
          })
        }
      }));
    }

    clearBulk();
    get()._refreshData();
    toast(`${ids.length} leads atualizados`);

    for (const id of realIds) {
      const lead = data.leads.find(l => l.id === id);
      const updatePayload = { [field]: value, modificadoEm: serverTimestamp() };
      if (field === 'status' && value !== lead?.status) {
        const historicoBase = getHistoricoStatus(lead);
        updatePayload.historicoStatus = [...historicoBase, buildHistoricoEntry(lead.status, value)];
      }
      if (isPerdido && lead?.prequalData) {
        updatePayload.prequalData = { ...lead.prequalData, screenshotUrl: null, screenshotPath: null };
      }
      updateDoc(uDoc('leads', id), updatePayload).catch(e => get().toast('Erro ao atualizar em massa: ' + e.message, 'error'));
    }
  },

  // ── Pré-Qualificação (T4.4: estendida com qualificação em massa por IA) ───────
  runPreQualification: async (leadIds, onProgress, options = {}) => {
    const { data, configData, uploadFile, deleteFile, setAiUsage, toast } = get();
    const withAi = Boolean(options?.withAi);
    const emit = (event) => { if (onProgress) onProgress(event); };

    const leadsToProcess = leadIds.reduce((acc, id) => {
      const lead = data.leads.find(l => l.id === id);
      if (!lead) return acc;
      const { site, instagram } = parseLeadLinks(lead.site || '');
      if (!site && !instagram) {
        emit({ type: 'skipped', leadId: id, leadName: lead.nome || id, reason: 'Sem site ou Instagram válido no campo Site/Instagram' });
        return acc;
      }
      return [...acc, { lead, site, instagram }];
    }, []);

    let skipped = leadIds.length - leadsToProcess.length;
    emit({ type: 'start', total: leadsToProcess.length, skipped });

    if (!leadsToProcess.length) {
      emit({ type: 'done', processed: 0, skipped });
      return { processed: 0, skipped };
    }

    let processed = 0;
    let aiLimitHit = false;

    for (let idx = 0; idx < leadsToProcess.length; idx++) {
      const { lead, site, instagram } = leadsToProcess[idx];

      if (aiLimitHit) {
        skipped++;
        emit({
          type: 'skipped',
          leadId: lead.id,
          leadName: lead.nome || lead.id,
          reason: 'Pausado: limite diário de IA atingido',
        });
        continue;
      }

      const isMock = lead.id.toString().startsWith('m-');

      emit({ type: 'processing', leadId: lead.id, leadName: lead.nome || lead.id, site: site || instagram });

      const setLoading = (loading) => set(s => ({
        ...(isMock
          ? { mockData: { ...s.mockData, leads: s.mockData.leads.map(l => l.id === lead.id ? { ...l, prequaling: loading } : l) } }
          : { realData: { ...s.realData, leads: s.realData.leads.map(l => l.id === lead.id ? { ...l, prequaling: loading } : l) } }
        )
      }));

      setLoading(true);
      get()._refreshData();

      try {
        const step = (name, status, extra = {}) =>
          emit({ type: 'step', leadId: lead.id, step: name, status, ...extra });

        if (site) { step('pagespeed', 'running'); } else { step('pagespeed', 'skipped', { error: 'Sem site — apenas Instagram' }); }
        if (instagram) step('instagram', 'running');

        const speedPromise = site
          ? fetchPageSpeed(site).then(r => {
              r.error ? step('pagespeed', 'error', { error: r.error }) : step('pagespeed', 'done', { mobile: r.mobile, desktop: r.desktop });
              return r;
            })
          : Promise.resolve({ mobile: null, desktop: null });

        const instaPromise = (instagram ? fetchInstagramData(instagram) : Promise.resolve({ followers: null, bio: null, lastPost: null, bioLink: null }))
          .then(r => {
            if (instagram) { r.error ? step('instagram', 'error', { error: r.error }) : step('instagram', 'done', { followers: r.followers }); }
            return r;
          });

        const [speedResult, instaResult] = await Promise.all([speedPromise, instaPromise]);

        let screenshotResult = { url: null, path: null };
        if (site) {
          step('screenshot', 'running');
          const oldScreenshotPath = lead.prequalData?.screenshotPath;
          if (oldScreenshotPath) {
            await deleteFile(oldScreenshotPath).catch(e => console.warn('[runPreQualification] Failed to delete old screenshot:', e));
          }
          screenshotResult = isMock
            ? (() => { step('screenshot', 'skipped', { error: 'Modo demo' }); return { url: null, path: null }; })()
            : await fetchScreenshot(site, lead.id, uploadFile).then(r => {
                r && r.url ? step('screenshot', 'done') : step('screenshot', 'error', { error: r?.error || 'Sem URL retornada' });
                return r || { url: null, path: null };
              });
        } else {
          step('screenshot', 'skipped', { error: 'Sem site — apenas Instagram' });
        }

        const nowISO = new Date().toISOString();
        const prequalData = {
          site,
          instagram: instagram || null,
          pagespeed: { mobile: speedResult.mobile, desktop: speedResult.desktop },
          instagramData: { followers: instaResult.followers, bio: instaResult.bio, lastPost: instaResult.lastPost, bioLink: instaResult.bioLink },
          screenshotUrl: screenshotResult.url || null,
          screenshotPath: screenshotResult.path || null,
          prequalizedAt: nowISO,
        };

        let aiQualificacao = lead.aiQualificacao || null;
        let nextQualChips = Array.isArray(lead.qualChips) ? lead.qualChips : [];
        let nextObservacoes = lead.observacoes || '';

        if (withAi) {
          if (lead.aiQualificacao?.resumo && !options.forceAi) {
            step('ai', 'skipped', { error: 'Já qualificado com IA (reaproveitado)' });
          } else {
            step('ai', 'running');
            const aiRes = await qualifyLeadWithAi(
              { ...lead, prequalData },
              {
                aiProvider: configData?.aiProvider || 'gemini',
                ollamaModel: configData?.ollamaModel || 'llama3.2',
              }
            );
            if (aiRes.usage) setAiUsage(aiRes.usage);

            if (!aiRes.ok) {
              if (aiRes.code === 'DAILY_LIMIT_REACHED') {
                aiLimitHit = true;
                const warnMsg = aiRes.error || 'Limite diário de IA atingido. Qualificação em massa pausada.';
                step('ai', 'error', { error: 'Limite diário atingido' });
                emit({ type: 'ai_limit_reached', error: warnMsg });
                toast(warnMsg, 'error');
              } else {
                step('ai', 'error', { error: aiRes.error || 'Falha na IA' });
              }
            } else {
              nextQualChips = Array.from(new Set([...nextQualChips, ...(aiRes.chips || [])]));
              aiQualificacao = {
                chips: nextQualChips,
                resumo: aiRes.resumo || '',
                prioridade: aiRes.prioridade || 'media',
                qualifiedAt: nowISO,
              };
              if (!nextObservacoes.trim() && aiRes.resumo) {
                nextObservacoes = aiRes.resumo;
              }
              step('ai', 'done', { prioridade: aiQualificacao.prioridade });
            }
          }
        }

        const updatedFields = {
          prequalData,
          qualChips: nextQualChips,
          ...(aiQualificacao ? { aiQualificacao } : {}),
          observacoes: nextObservacoes,
        };

        set(s => ({
          ...(isMock
            ? { mockData: { ...s.mockData, leads: s.mockData.leads.map(l => l.id === lead.id ? { ...l, ...updatedFields, prequaling: false, modificadoEm: nowISO } : l) } }
            : { realData: { ...s.realData, leads: s.realData.leads.map(l => l.id === lead.id ? { ...l, ...updatedFields, prequaling: false, modificadoEm: nowISO } : l) } }
          )
        }));
        get()._refreshData();

        if (!isMock) {
          updateDoc(uDoc('leads', lead.id), { ...updatedFields, modificadoEm: serverTimestamp() })
            .catch(e => console.error('[runPreQualification] Firestore sync error:', e));
        }

        processed++;
        emit({
          type: 'success',
          leadId: lead.id,
          leadName: lead.nome || lead.id,
          site,
          result: {
            pagespeedMobile: prequalData.pagespeed.mobile,
            pagespeedDesktop: prequalData.pagespeed.desktop,
            hasScreenshot: !!prequalData.screenshotUrl,
            hasInstagram: instaResult.followers != null,
            aiPrioridade: aiQualificacao?.prioridade || null,
          },
        });
      } catch (e) {
        console.error('[runPreQualification] Error for lead', lead.id, e);
        setLoading(false);
        get()._refreshData();
        emit({ type: 'error', leadId: lead.id, leadName: lead.nome || lead.id, site, error: e.message });
      }
    }

    emit({ type: 'done', processed, skipped });
    return { processed, skipped, aiLimitHit };
  },

  deleteLeadScreenshot: async (leadId) => {
    const { data, deleteFile, toast } = get();
    const lead = data.leads.find(l => l.id === leadId);
    if (!lead?.prequalData?.screenshotPath) return;

    await deleteFile(lead.prequalData.screenshotPath).catch(e =>
      console.warn('[deleteLeadScreenshot] Storage delete failed:', e)
    );

    const updatedPrequalData = { ...lead.prequalData, screenshotUrl: null, screenshotPath: null };

    const isMock = leadId.toString().startsWith('m-');
    if (isMock) {
      set(s => ({ mockData: { ...s.mockData, leads: s.mockData.leads.map(l => l.id === leadId ? { ...l, prequalData: updatedPrequalData } : l) } }));
    } else {
      set(s => ({ realData: { ...s.realData, leads: s.realData.leads.map(l => l.id === leadId ? { ...l, prequalData: updatedPrequalData } : l) } }));
      updateDoc(uDoc('leads', leadId), { prequalData: updatedPrequalData, modificadoEm: serverTimestamp() }).catch(e => console.error('[deleteLeadScreenshot] Firestore sync error:', e));
    }

    get()._refreshData();
    toast('Screenshot removido.');
  },

  uploadManualScreenshot: async (leadId, file) => {
    const { data, uploadFile, deleteFile, toast } = get();
    const lead = data.leads.find(l => l.id === leadId);
    if (!lead || !file) return;

    const oldPath = lead.prequalData?.screenshotPath;
    if (oldPath) {
      await deleteFile(oldPath).catch(e => console.warn('[uploadManualScreenshot] Falha ao remover print anterior:', e));
    }

    const isMock = leadId.toString().startsWith('m-') || lead.isMock;
    let url = null;
    let path = null;

    if (isMock) {
      url = URL.createObjectURL(file);
      path = `mock/screenshots/${leadId}_${Date.now()}.jpg`;
    } else {
      const res = await uploadFile(file, 'screenshots', leadId);
      url = res.url;
      path = res.path;
    }

    const nowISO = new Date().toISOString();
    const updatedPrequalData = {
      ...(lead.prequalData || {}),
      screenshotUrl: url,
      screenshotPath: path,
      prequalizedAt: nowISO,
    };

    if (isMock) {
      set(s => ({
        mockData: {
          ...s.mockData,
          leads: s.mockData.leads.map(l => l.id === leadId ? { ...l, prequalData: updatedPrequalData, screenshotManual: true, modificadoEm: nowISO } : l),
        },
      }));
    } else {
      set(s => ({
        realData: {
          ...s.realData,
          leads: s.realData.leads.map(l => l.id === leadId ? { ...l, prequalData: updatedPrequalData, screenshotManual: true, modificadoEm: nowISO } : l),
        },
      }));
      await updateDoc(uDoc('leads', leadId), {
        prequalData: updatedPrequalData,
        screenshotManual: true,
        modificadoEm: serverTimestamp(),
      }).catch(e => toast('Erro ao salvar print no banco: ' + e.message, 'error'));
    }

    get()._refreshData();
    toast('Print colado e salvo com sucesso!');
  },

  bulkAddLeads: async (items) => {
    const { toast, _refreshData, currentUser } = get();
    try {
      const now = new Date().toISOString();
      const st = serverTimestamp();

      const newItems = items.map((it, idx) => ({
        ...it,
        uid: currentUser.uid,
        id: `temp_bulk_${Date.now()}_${idx}`,
        // Fase 0: inicializa historicoStatus na criação
        historicoStatus: [{ statusAnterior: null, statusNovo: it.status || 'Novo', data: now }],
        dataAbordagem: null,
        criadoEm: now,
        modificadoEm: now
      }));

      set(s => ({ realData: { ...s.realData, leads: [...newItems, ...s.realData.leads] } }));
      _refreshData();

      const CHUNK_SIZE = 450;
      for (let i = 0; i < items.length; i += CHUNK_SIZE) {
        const batch = writeBatch(db);
        const chunk = items.slice(i, i + CHUNK_SIZE);
        const chunkStartIndex = i;

        chunk.forEach((it, idx) => {
          const ref = doc(uCol('leads'));
          const payload = {
            ...it,
            uid: currentUser.uid,
            historicoStatus: [{ statusAnterior: null, statusNovo: it.status || 'Novo', data: now }],
            dataAbordagem: null,
            criadoEm: st,
            modificadoEm: st
          };
          batch.set(ref, payload);
          newItems[chunkStartIndex + idx].realId = ref.id;
        });

        await batch.commit();
      }

      set(s => ({
        realData: {
          ...s.realData,
          leads: s.realData.leads.map(x => {
            const found = newItems.find(ni => ni.id === x.id);
            return found ? { ...x, id: found.realId } : x;
          })
        }
      }));
      _refreshData();
      toast(`${items.length} leads importados com sucesso!`);
    } catch (e) {
      console.error('bulkAddLeads error:', e);
      toast('Erro ao importar leads: ' + e.message, 'error');
    }
  },

  repairMojibakeData: async () => {
    const { data, toast, _refreshData } = get();
    const batch = writeBatch(db);
    let count = 0;
    const leadsToUpdate = [];

    (data.leads || []).forEach(lead => {
      if (lead.isMock) return;
      const sanitized = sanitizeObjectStrings(lead);
      let changed = false;
      ['nome', 'nicho', 'cidade', 'observacoes'].forEach(field => {
        if (lead[field] && sanitized[field] !== lead[field]) {
          changed = true;
        }
      });
      if (changed) {
        count++;
        leadsToUpdate.push(sanitized);
        const ref = uDoc('leads', lead.id);
        batch.update(ref, {
          nome: sanitized.nome || '',
          nicho: sanitized.nicho || '',
          cidade: sanitized.cidade || '',
          observacoes: sanitized.observacoes || ''
        });
      }
    });

    if (count > 0) {
      await batch.commit();
      set(s => ({
        realData: {
          ...s.realData,
          leads: s.realData.leads.map(l => {
            const updated = leadsToUpdate.find(u => u.id === l.id);
            return updated ? { ...l, ...updated } : l;
          })
        }
      }));
      _refreshData();
      toast(`${count} lead(s) tiveram sua acentuação reparada com sucesso!`, 'success');
    } else {
      toast('Todos os leads já estão com acentuação correta!', 'info');
    }
  },
});

import { db, doc, setDoc, addDoc, updateDoc, deleteDoc, serverTimestamp, getDocs, writeBatch } from '../../firebase';
import { uDoc, uCol, getCurrentMonthKey, buildMonthlyDate, fmtDateISO } from '../storeUtils';

export const createFinanceSlice = (set, get) => ({
  saveRecorrencia: async (fields) => {
    if (!fields.cliente) return get().toast('Cliente obrigatório', 'error');
    await get().saveGeneric('recorrencia', { ...fields, modificadoEm: serverTimestamp() }, 'Cliente');
    get().runFinancialAutomations();
  },

  saveNegocio: async (fields) => {
    if (!fields.descricao) return get().toast('Descrição obrigatória', 'error');
    await get().saveGeneric('negocio', { ...fields, modificadoEm: serverTimestamp() }, 'Lançamento');
  },

  savePessoal: async (fields) => {
    if (!fields.descricao) return get().toast('Descrição obrigatória', 'error');
    await get().saveGeneric('pessoal', { ...fields, modificadoEm: serverTimestamp() }, 'Lançamento');
  },

  togglePessoalPago: async (id, pago) => {
    const newPago = !pago;
    set(s => ({
      realData: {
        ...s.realData,
        pessoal: s.realData.pessoal.map(x => x.id === id ? { ...x, pago: newPago } : x)
      }
    }));
    get()._refreshData();
    updateDoc(uDoc('pessoal', id), { pago: newPago }).catch(e => get().toast('Sync Error: ' + e.message, 'error'));
  },

  toggleNegocioPago: async (id, pago) => {
    const newPago = !pago;
    set(s => ({
      realData: {
        ...s.realData,
        negocio: s.realData.negocio.map(x => x.id === id ? { ...x, pago: newPago } : x)
      }
    }));
    get()._refreshData();
    updateDoc(uDoc('negocio', id), { pago: newPago }).catch(e => get().toast('Sync Error: ' + e.message, 'error'));
  },

  saveDespesaFixa: async (fields) => {
    if (!fields.descricao) return get().toast('Descrição obrigatória', 'error');
    await get().saveGeneric('despesasFixas', { ...fields, modificadoEm: serverTimestamp() }, 'Despesa');
    get().runFinancialAutomations();
  },

  saveNegocioParcelado: async (fields) => {
    const { toast, closeModal, _refreshData } = get();
    try {
      const { descricao, valor, totalParcelas, dataInicio, data, categoria, entidade, nf, formaPagamento, observacoes, projetoId } = fields;
      const dateToUse = dataInicio || data;

      if (!descricao || !valor || !totalParcelas || !dateToUse) {
        return toast('Descrição, Valor, Parcelas e Data são obrigatórios', 'error');
      }

      const total = parseFloat(valor) || 0;
      const numParcelas = parseInt(totalParcelas, 10) || 1;
      const valorParcela = Math.round((total / numParcelas) * 100) / 100;
      const totalTaxa = parseFloat(fields.taxaGateway) || 0;
      const taxaParcela = Math.round((totalTaxa / numParcelas) * 100) / 100;

      const grupoId = `grupo_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

      const newItems = [];
      const { db, writeBatch, doc } = await import('../../firebase');
      const batch = writeBatch(db);
      const colRef = uCol('negocio');

      for (let i = 0; i < numParcelas; i++) {
        const d = new Date(dateToUse + 'T12:00:00');
        d.setMonth(d.getMonth() + i);
        const dataStr = fmtDateISO(d);

        const currValor = i === numParcelas - 1 ? Math.round((total - valorParcela * (numParcelas - 1)) * 100) / 100 : valorParcela;
        const currTaxa = i === numParcelas - 1 ? Math.round((totalTaxa - taxaParcela * (numParcelas - 1)) * 100) / 100 : taxaParcela;
        const currLiq = currValor - currTaxa;

        const payload = {
          tipo: fields.tipo || 'Receita',
          descricao: `${descricao} (${i + 1}/${numParcelas})`,
          valor: currValor,
          taxaGateway: currTaxa,
          valorLiquido: currLiq,
          data: dataStr,
          categoria: categoria || '',
          entidade: entidade || '',
          nf: nf || 'nao',
          formaPagamento: formaPagamento || 'PIX',
          observacoes: observacoes || '',
          projetoId: projetoId || '',
          parcelamento: { total: numParcelas, parcela: i + 1, valorTotal: total, grupoId },
          modificadoEm: serverTimestamp(),
          criadoEm: serverTimestamp(),
        };

        const ref = doc(colRef);
        batch.set(ref, payload);

        const local = { ...payload, id: ref.id, criadoEm: new Date().toISOString(), modificadoEm: new Date().toISOString() };
        newItems.push(local);
      }

      set(s => ({ realData: { ...s.realData, negocio: [...newItems, ...s.realData.negocio] } }));
      _refreshData();
      closeModal();
      toast(`Salvando ${numParcelas} parcelas...`);

      await batch.commit();

      toast(`${numParcelas} parcelas salvas com sucesso!`);
    } catch (e) {
      console.error('saveNegocioParcelado error:', e);
      toast('Erro ao processar parcelamento: ' + e.message, 'error');
    }
  },

  bulkDeleteParcelamento: async (grupoId) => {
    const { data, showConfirm, toast } = get();
    const grupo = data.negocio.filter(m => m.parcelamento?.grupoId === grupoId);
    if (!grupo.length) return toast('Nenhuma parcela encontrada para este grupo.', 'error');
    const confirmed = await showConfirm(`Excluir todas as ${grupo.length} parcelas?`, 'Esta ação é irreversível.', true);
    if (!confirmed) return;
    const now = new Date().toISOString();

    set(s => ({
      realData: {
        ...s.realData,
        negocio: s.realData.negocio.filter(m => m.parcelamento?.grupoId !== grupoId)
      }
    }));
    get()._refreshData();
    for (const m of grupo) {
      updateDoc(uDoc('negocio', m.id), { deletadoEm: now }).catch(e => get().toast('Erro ao deletar em massa: ' + e.message, 'error'));
    }
    toast(`${grupo.length} parcela(s) excluída(s)!`);
  },

  registrarPagamentoRecorrencia: async (recorrenciaId, fields) => {
    const { data, toast, closeModal } = get();
    const rec = data.recorrencia.find(r => r.id === recorrenciaId);
    if (!rec) return toast('Recorrência não encontrada', 'error');
    const valorBruto = parseFloat(fields.valor) || 0;
    const valorNet = parseFloat(fields.valorLiquido) || valorBruto;
    const taxaGateway = Math.max(0, valorBruto - valorNet);
    const competenciaVal = fields.competencia || fields.referenciaMes || getCurrentMonthKey();

    const payload = {
      tipo: 'Receita',
      descricao: fields.descricao || (rec.plano || `Recorrência ${rec.cliente || ''}`).trim(),
      valor: valorBruto,
      valorLiquido: valorNet,
      taxaGateway: taxaGateway.toFixed(2),
      data: fields.data || fmtDateISO(),
      categoria: fields.categoria || 'Receita Recorrente',
      entidade: rec.cliente || '',
      clienteId: rec.clienteId || '',
      nf: fields.nf || 'pendente',
      formaPagamento: fields.formaPagamento || 'PIX',
      observacoes: fields.observacoes || '',
      origemAutomatica: 'recorrencia',
      recorrenciaId,
      competencia: competenciaVal,
      referenciaMes: competenciaVal,
      modificadoEm: serverTimestamp(),
      criadoEm: serverTimestamp(),
    };
    const local = { ...payload, id: 'temp_' + Date.now(), criadoEm: new Date().toISOString(), modificadoEm: new Date().toISOString() };
    set(s => ({ realData: { ...s.realData, negocio: [local, ...s.realData.negocio] } }));
    get()._refreshData();
    closeModal();
    toast('Pagamento registrado em Finanças Negócio!');

    import('../../firebase').then(({ addDoc }) => {
      addDoc(uCol('negocio'), payload).then(r => {
        set(s => ({ realData: { ...s.realData, negocio: s.realData.negocio.map(x => x.id === local.id ? { ...x, id: r.id } : x) } }));
        get()._refreshData();
      }).catch(e => toast('Sync Error: ' + e.message, 'error'));
    });

    if ((rec.periodicidade === 'Anual' || rec.periodicidade === 'Semestral') && rec.renovacao) {
      const parts = rec.renovacao.split('-');
      if (parts.length === 3) {
        let nextYear = parseInt(parts[0], 10);
        let nextMonth = parseInt(parts[1], 10);

        if (rec.periodicidade === 'Semestral') {
          nextMonth += 6;
          if (nextMonth > 12) {
            nextMonth -= 12;
            nextYear += 1;
          }
        } else {
          nextYear += 1;
        }

        const nextMonthStr = String(nextMonth).padStart(2, '0');
        const newRenovacao = `${nextYear}-${nextMonthStr}-${parts[2]}`;
        updateDoc(uDoc('recorrencia', recorrenciaId), { renovacao: newRenovacao, modificadoEm: serverTimestamp() }).catch(() => {});
        set(s => ({
          realData: { ...s.realData, recorrencia: s.realData.recorrencia.map(x => x.id === recorrenciaId ? { ...x, renovacao: newRenovacao } : x) }
        }));
      }
    }
  },

  updateRecorrenciaCompetenciaNf: async (recorrenciaId, competenciaKey, patch) => {
    const { data, toast } = get();
    const rec = data.recorrencia.find(r => r.id === recorrenciaId);
    if (!rec || !competenciaKey) return;
    const prevMap = rec.competencias || {};
    const prevComp = prevMap[competenciaKey] || { nfEmitida: false, nfNumero: '', nfEmitidaEm: null };
    const nextEmitida = patch.nfEmitida !== undefined ? !!patch.nfEmitida : !!prevComp.nfEmitida;
    const nextComp = {
      ...prevComp,
      ...patch,
      nfEmitida: nextEmitida,
      nfNumero: patch.nfNumero !== undefined ? String(patch.nfNumero) : (prevComp.nfNumero || ''),
      nfEmitidaEm: nextEmitida ? (prevComp.nfEmitidaEm || new Date().toISOString()) : null,
    };
    const nextCompetencias = { ...prevMap, [competenciaKey]: nextComp };
    const now = new Date().toISOString();

    if (rec.isMock) {
      set(s => ({
        mockData: {
          ...s.mockData,
          recorrencia: s.mockData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, competencias: nextCompetencias, modificadoEm: now } : r
          )
        }
      }));
    } else {
      set(s => ({
        realData: {
          ...s.realData,
          recorrencia: s.realData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, competencias: nextCompetencias, modificadoEm: now } : r
          )
        }
      }));
      updateDoc(uDoc('recorrencia', recorrenciaId), {
        competencias: nextCompetencias,
        modificadoEm: serverTimestamp()
      }).catch(e => toast('Sync Error: ' + e.message, 'error'));
    }
    get()._refreshData();
  },

  bulkAddFinancas: async (colName, items) => {
    const { toast, _refreshData } = get();
    try {
      const now = new Date().toISOString();
      const st = serverTimestamp();

      const newItems = items.map((it, idx) => ({ ...it, id: `temp_bulk_${Date.now()}_${idx}`, criadoEm: now, modificadoEm: now }));

      set(s => ({ realData: { ...s.realData, [colName]: [...newItems, ...s.realData[colName]] } }));
      _refreshData();

      const CHUNK_SIZE = 450;
      for (let i = 0; i < items.length; i += CHUNK_SIZE) {
        const batch = writeBatch(db);
        const chunk = items.slice(i, i + CHUNK_SIZE);
        const chunkStartIndex = i;

        chunk.forEach((it, idx) => {
          const ref = doc(uCol(colName));
          const payload = { ...it, criadoEm: st, modificadoEm: st };
          batch.set(ref, payload);
          newItems[chunkStartIndex + idx].realId = ref.id;
        });

        await batch.commit();
      }

      set(s => ({
        realData: {
          ...s.realData,
          [colName]: s.realData[colName].map(x => {
            const found = newItems.find(ni => ni.id === x.id);
            return found ? { ...x, id: found.realId } : x;
          })
        }
      }));
      _refreshData();
      toast(`${items.length} lançamentos importados!`);
    } catch (e) {
      console.error('bulkAddFinancas error:', e);
      toast('Erro ao importar: ' + e.message, 'error');
    }
  },

  runFinancialAutomations: async (loadedData = null, loadedConfig = null) => {
    const { isSyncingAutomations, toast } = get();
    if (isSyncingAutomations) return;

    set({ isSyncingAutomations: true });

    try {
      const dataSource = loadedData || get().data;
      const configSource = loadedConfig || get().configData;
      const monthKey = getCurrentMonthKey();
      const createdNegocio = [];
      const createdPessoal = [];
      const updatedFixaIds = [];

      for (const despesa of (dataSource.despesasFixas || [])) {
        if (!despesa?.id) continue;
        const isNegocio = despesa.contexto === 'negocio';
        if (!isNegocio && !configSource.lancarDespesasAuto) continue;

        const targetList = isNegocio ? (dataSource.negocio || []) : (dataSource.pessoal || []);
        const targetCol = isNegocio ? 'negocio' : 'pessoal';

        const alreadyByUltimo = despesa.ultimoLancamento === monthKey;
        const alreadyInList = targetList.some(item =>
          item.tipo === 'Despesa' &&
          ((item.origemAutomatica === 'despesaFixa' && item.despesaFixaId === despesa.id && item.referenciaMes === monthKey) ||
          ((item.descricao || '') === (despesa.descricao || '') && String(item.data || '').startsWith(monthKey)))
        );
        if (alreadyByUltimo || alreadyInList) {
          if (!alreadyByUltimo && alreadyInList && !despesa.isMock) {
            updatedFixaIds.push(despesa.id);
            updateDoc(uDoc('despesasFixas', despesa.id), { ultimoLancamento: monthKey, modificadoEm: serverTimestamp() }).catch(() => {});
          }
          continue;
        }

        const payload = {
          data: buildMonthlyDate(despesa.dia || 1),
          tipo: 'Despesa',
          descricao: despesa.descricao,
          valor: Number(despesa.valor || 0),
          categoria: despesa.categoria || (isNegocio ? 'Impostos' : ''),
          cartao: !!despesa.cartao,
          pago: false,
          origemAutomatica: 'despesaFixa',
          despesaFixaId: despesa.id,
          referenciaMes: monthKey,
          modificadoEm: serverTimestamp(),
          criadoEm: serverTimestamp()
        };

        updatedFixaIds.push(despesa.id);
        if (!despesa.isMock) {
          const { addDoc } = await import('../../firebase');
          const res = await addDoc(uCol(targetCol), payload);
          await updateDoc(uDoc('despesasFixas', despesa.id), { ultimoLancamento: monthKey, modificadoEm: serverTimestamp() }).catch(() => {});
          const createdObj = { id: res.id, ...payload, criadoEm: new Date().toISOString(), modificadoEm: new Date().toISOString() };
          if (isNegocio) createdNegocio.push(createdObj);
          else createdPessoal.push(createdObj);
        }
      }

      if (createdNegocio.length || createdPessoal.length || updatedFixaIds.length) {
        set(s => ({
          realData: {
            ...s.realData,
            negocio: [...createdNegocio, ...s.realData.negocio],
            pessoal: [...createdPessoal, ...s.realData.pessoal],
            despesasFixas: s.realData.despesasFixas.map(d =>
              updatedFixaIds.includes(d.id) ? { ...d, ultimoLancamento: monthKey } : d
            ),
          }
        }));
        get()._refreshData();
      }
    } catch (e) {
      toast('Erro na automação: ' + e.message, 'error');
    } finally {
      set({ isSyncingAutomations: false });
    }
  },

  lancarDespesasMensais: async (contextoFilter = null) => {
    const { data, showConfirm, toast } = get();
    if (!contextoFilter && !await showConfirm('Lançar despesas fixas?', 'As despesas fixas pendentes de lançamento neste mês serão criadas.', false)) return;
    const now = new Date();
    const monthKey = getCurrentMonthKey(now);
    let count = 0;
    const { addDoc } = await import('../../firebase');

    for (const d of (data.despesasFixas || [])) {
      const ctx = d.contexto === 'negocio' ? 'negocio' : 'pessoal';
      if (contextoFilter && ctx !== contextoFilter) continue;
      const targetList = ctx === 'negocio' ? (data.negocio || []) : (data.pessoal || []);
      const alreadyExists = d.ultimoLancamento === monthKey || targetList.some(item => 
        item.tipo === 'Despesa' &&
        ((item.origemAutomatica === 'despesaFixa' && item.despesaFixaId === d.id && item.referenciaMes === monthKey) ||
        ((item.descricao || '') === (d.descricao || '') && String(item.data || '').startsWith(monthKey)))
      );
      if (alreadyExists) continue;
      const payload = {
        data: buildMonthlyDate(d.dia || 1, now),
        tipo: 'Despesa',
        descricao: d.descricao,
        valor: Number(d.valor || 0),
        categoria: d.categoria || (ctx === 'negocio' ? 'Impostos' : ''),
        cartao: !!d.cartao,
        pago: false,
        origemAutomatica: 'despesaFixa',
        despesaFixaId: d.id,
        referenciaMes: monthKey,
        modificadoEm: serverTimestamp(),
        criadoEm: serverTimestamp()
      };
      const res = await addDoc(uCol(ctx), payload);
      await updateDoc(uDoc('despesasFixas', d.id), { ultimoLancamento: monthKey, modificadoEm: serverTimestamp() }).catch(() => {});
      set(s => ({
        realData: {
          ...s.realData,
          [ctx]: [{ id: res.id, ...payload, criadoEm: new Date().toISOString() }, ...s.realData[ctx]],
          despesasFixas: s.realData.despesasFixas.map(x => x.id === d.id ? { ...x, ultimoLancamento: monthKey } : x),
        }
      }));
      count++;
    }
    get()._refreshData();
    toast(`${count} lançamento(s) criado(s)!`);
  },

  // ── ATIVIDADES DE MANUTENÇÃO ──

  /**
   * Salva (cria ou edita) uma atividade de manutenção em uma recorrência.
   * O campo `atividades` é um array armazenado diretamente no documento de recorrência.
   * Cada atividade é um snapshot imutável; o limite histórico é preservado no campo `limiteHorasNaEpoca`
   * (capturado no momento do lançamento), garantindo que futuras alterações no limiteHoras do cliente
   * não reinterpretem retroativamente os meses já registrados.
   *
   * @param {string} recorrenciaId - ID da recorrência
   * @param {object} atividade - { id?, descricao, minutos, data }
   * @param {boolean} closeModalAfter - se deve fechar o modal ao salvar
   */
  saveAtividadeManutencao: async (recorrenciaId, atividade, closeModalAfter = true) => {
    const { data, toast, closeModal } = get();
    const rec = data.recorrencia.find(r => r.id === recorrenciaId);
    if (!rec) return toast('Recorrência não encontrada', 'error');

    if (!atividade.descricao?.trim()) return toast('Descrição da atividade é obrigatória.', 'error');
    const minutos = parseInt(atividade.minutos) || 0;
    if (minutos <= 0) return toast('Informe o tempo gasto em minutos (mínimo 1 minuto).', 'error');
    if (!atividade.data) return toast('Data da atividade é obrigatória.', 'error');

    const atividades = Array.isArray(rec.atividades) ? [...rec.atividades] : [];
    const now = new Date().toISOString();

    let novasAtividades;
    if (atividade.id) {
      // Edição: preserva limiteHorasNaEpoca original
      novasAtividades = atividades.map(a =>
        a.id === atividade.id
          ? { ...a, descricao: atividade.descricao.trim(), minutos, data: atividade.data, modificadoEm: now }
          : a
      );
    } else {
      // Criação: captura o limite atual como snapshot histórico
      const novaAtividade = {
        id: `act_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        descricao: atividade.descricao.trim(),
        minutos,
        data: atividade.data,
        limiteHorasNaEpoca: rec.limiteHoras || null, // snapshot imutável do limite na época
        criadoEm: now,
        modificadoEm: now,
      };
      novasAtividades = [novaAtividade, ...atividades];
    }

    // Idem ao padrão do sistema: atualiza localmente e dispara sync assíncrono no Firebase
    const isMock = rec.isMock;
    if (isMock) {
      set(s => ({
        mockData: {
          ...s.mockData,
          recorrencia: s.mockData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, atividades: novasAtividades, modificadoEm: now } : r
          )
        }
      }));
    } else {
      set(s => ({
        realData: {
          ...s.realData,
          recorrencia: s.realData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, atividades: novasAtividades, modificadoEm: now } : r
          )
        }
      }));
      updateDoc(uDoc('recorrencia', recorrenciaId), { atividades: novasAtividades, modificadoEm: serverTimestamp() })
        .catch(e => toast('Sync Error: ' + e.message, 'error'));
    }
    get()._refreshData();
    if (closeModalAfter) closeModal();
    toast(atividade.id ? 'Atividade atualizada!' : 'Atividade registrada!');
  },

  /**
   * Exclui uma atividade de manutenção de uma recorrência.
   * @param {string} recorrenciaId - ID da recorrência
   * @param {string} atividadeId - ID da atividade a excluir
   */
  deleteAtividadeManutencao: async (recorrenciaId, atividadeId) => {
    const { data, toast, showConfirm } = get();
    const rec = data.recorrencia.find(r => r.id === recorrenciaId);
    if (!rec) return toast('Recorrência não encontrada', 'error');

    const confirmed = await showConfirm('Excluir atividade?', 'O tempo registrado será removido do controle do mês.', false);
    if (!confirmed) return;

    const novasAtividades = (rec.atividades || []).filter(a => a.id !== atividadeId);
    const now = new Date().toISOString();

    const isMock = rec.isMock;
    if (isMock) {
      set(s => ({
        mockData: {
          ...s.mockData,
          recorrencia: s.mockData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, atividades: novasAtividades, modificadoEm: now } : r
          )
        }
      }));
    } else {
      set(s => ({
        realData: {
          ...s.realData,
          recorrencia: s.realData.recorrencia.map(r =>
            r.id === recorrenciaId ? { ...r, atividades: novasAtividades, modificadoEm: now } : r
          )
        }
      }));
      updateDoc(uDoc('recorrencia', recorrenciaId), { atividades: novasAtividades, modificadoEm: serverTimestamp() })
        .catch(e => toast('Sync Error: ' + e.message, 'error'));
    }
    get()._refreshData();
    toast('Atividade excluída!');
  },
});

import { db, doc, setDoc, getDoc, updateDoc, deleteDoc, serverTimestamp, getDocs, collection, query, orderBy, writeBatch, addDoc } from '../../firebase';
import { uCol, uDoc, fmtDateISO, fmtDate, fmtBRL, detectCSVDelimiter, parseCSVRows, cleanCSVValue, buildCSVHeaderMap, getCSVCell, normalizeImportedStatus, TRASH_COLS, ALL_COLS, EMPTY_DATA, getRecorrenciaVencimento } from '../storeUtils';
import { syncAlertsWithHostinger } from '../../utils/syncAlerts';
import { MOCK_DATA } from '../mockData';
import { getPageFromUrl, syncUrlWithPage } from '../../utils/routes';
import { sanitizeObjectStrings } from '../../utils/textUtils';

let IS_REPORTING_AUTOMATIC_ERROR = false;

export const createUISlice = (set, get) => ({
  // ── State ──
  data: { ...EMPTY_DATA },
  realData: { ...EMPTY_DATA },
  mockData: { ...EMPTY_DATA },
  demoMode: false,
  configData: { nichos: [], categoriasPessoal: [], categoriasNegocioDespesa: [], categoriasReceita: [], cartaoNome: '', cartaoVenc: '', cartoes: [], modules: {}, notifEnabled: true, notifLeadTime: 24, lancarDespesasAuto: false, metaFaturamento: 0, tipoEmpresa: 'MEI', limiteAnual: 81000, pdfLogo: '', nomeEmpresa: '', cnpj: '', responsavel: '', emailEmpresa: '', telefoneEmpresa: '', cidade: '', estado: '', site: '' },
  isSyncingAutomations: false,
  maintenanceMode: false,
  editingId: { leads: null, projetos: null, recorrencia: null, negocio: null, pessoal: null, clientes: null, lembretes: null, despesasFixas: null, atividadeManutencaoId: null },
  activePage: getPageFromUrl(),
  previousPage: 'dashboard',
  configActiveTab: 'cfg-conta',
  activeProjectView: null,
  selectedItems: [],
  currentBulkCol: null,
  theme: localStorage.getItem('theme') || 'dark',
  sidebarCollapsed: localStorage.getItem('msk_sidebar_collapsed') === 'true',
  zoomControl: localStorage.getItem('zoom') || '100',
  notifications: [],
  _firedReminders: new Set(),
  
  modalOpen: false,
  modalType: null,
  modalTitle: '',
  modalSize: null,
  toasts: [],
  loading: false,
  csvProgress: { pct: 0, text: "Iniciando importação..." },
  setCsvProgress: (progress) => set(s => ({ csvProgress: { ...s.csvProgress, ...progress } })),
  confirm: null,

  setLoading: (v) => set({ loading: v }),

  _refreshData: () => {
    const { realData, mockData, demoMode } = get();
    const combined = { ...EMPTY_DATA };
    Object.keys(EMPTY_DATA).forEach(k => {
      const items = [...(realData[k] || []), ...(demoMode ? (mockData[k] || []) : [])];
      combined[k] = items.map(sanitizeObjectStrings);
    });
    set({ data: combined });
  },

  loadAll: async () => {
    const { currentUser } = get();
    const newData = { ...EMPTY_DATA };
    const fetchPromises = ALL_COLS.map(async (colName) => {
      const snap = await getDocs(uCol(colName));
      return {
        colName,
        docs: snap.docs.map(d => ({ id: d.id, ...sanitizeObjectStrings(d.data()) })).filter(x => !x.deletadoEm)
      };
    });
    
    const results = await Promise.all(fetchPromises);
    results.forEach(({ colName, docs }) => { newData[colName] = docs; });

    set({ realData: newData });

    const configDoc = await getDoc(uDoc('settings', 'main'));
    let configData = { nichos: [], categoriasPessoal: [], categoriasNegocioDespesa: [], categoriasReceita: [], cartaoNome: '', cartaoVenc: '', modules: {} };
    if (configDoc.exists()) {
      const d = configDoc.data();
      configData = { ...configData, ...d };
    } else {
      configData.nichos = ['Advogados', 'Clínicas médicas', 'E-commerce', 'Estética'];
      configData.categoriasPessoal = ['Alimentação', 'Moradia', 'Transporte', 'Saúde', 'Lazer', 'Educação', 'Vestuário', 'Assinaturas', 'Investimentos', 'Outros'];
      configData.categoriasNegocioDespesa = ['Marketing', 'Ferramentas', 'Impostos', 'Operacional', 'Fornecedores', 'Serviços', 'Transporte', 'Outros'];
      configData.categoriasReceita = ['Receita Recorrente', 'Trabalho Fixo', 'Freelancer', 'Comissão', 'Bonificação', 'Presente'];
      configData.modules = { leads: true, projetos: true, recorrencia: true, negocio: true, pessoal: true };
      configData.notifEnabled = true;
      configData.notifLeadTime = 24;
      await setDoc(uDoc('settings', 'main'), configData);
    }

    const cloudTheme = configData.theme || 'dark';
    const cloudZoom = configData.zoom || '100';
    const cloudDemo = configData.demoMode || false;

    if (cloudTheme === 'light') document.body.classList.add('light');
    else document.body.classList.remove('light');
    document.documentElement.style.setProperty('--app-scale', (parseInt(cloudZoom) / 100).toString());

    set({ 
      realData: newData, 
      configData, 
      theme: cloudTheme, 
      zoomControl: cloudZoom,
      demoMode: cloudDemo
    });

    get()._refreshData();
    if (cloudDemo) {
      set({ mockData: JSON.parse(JSON.stringify(MOCK_DATA || {})) });
      get()._refreshData();
    }

    get().runFinancialAutomations(newData, configData).catch(() => {});
    get().autoPurgeTrash();
    get().trackSession();
    get().loadSessions();
    syncAlertsWithHostinger(get);
  },

  autoPurgeTrash: async () => {
    const { currentUser, deleteFile } = get();
    if (!currentUser) return;
    
    const cutoff = Date.now() - 15 * 24 * 60 * 60 * 1000;
    const allRefs = [];
    
    for (const colName of TRASH_COLS) {
      const snap = await getDocs(uCol(colName));
      for (const d of snap.docs) {
        const dt = d.data().deletadoEm;
        if (!dt) continue;
        const ms = typeof dt === 'string' ? new Date(dt).getTime() : (dt?.seconds || 0) * 1000;
        
        if (ms > 0 && ms < cutoff) {
          if (colName === 'leads') {
            const path = d.data().prequalData?.screenshotPath;
            if (path) {
              await deleteFile(path).catch(e => console.warn('[autoPurgeTrash] Falha ao deletar screenshot:', e));
            }
          }
          allRefs.push(uDoc(colName, d.id));
        }
      }
    }

    if (allRefs.length === 0) return;

    const CHUNK_SIZE = 450;
    for (let i = 0; i < allRefs.length; i += CHUNK_SIZE) {
      const chunk = allRefs.slice(i, i + CHUNK_SIZE);
      const batch = writeBatch(db);
      chunk.forEach(ref => batch.delete(ref));
      await batch.commit().catch(e => console.warn('[autoPurgeTrash] Erro no batch:', e));
    }
  },

  setDemoMode: async (enabled) => {
    const { currentUser, configData } = get();
    if (enabled) {
      // @ts-ignore
      set({ demoMode: true, mockData: JSON.parse(JSON.stringify(MOCK_DATA || {})) });
    } else {
