    };
    const titles = {
      lead: id ? 'Editar Lead' : 'Novo Lead',
      projeto: id ? 'Editar Projeto' : 'Novo Projeto',
      recorrencia: id ? 'Editar Cliente' : 'Novo Cliente de Recorrência',
      negocioReceita: id ? 'Editar Receita Negócio' : 'Nova Receita Negócio',
