  selectAll: (colName, ids) => {
    set(s => {
      if (!ids) return { selectedItems: [], currentBulkCol: null };
      const all = ids.split(',');
      const sel = s.selectedItems.length === all.length ? [] : all;
      return { selectedItems: sel, currentBulkCol: colName };
